export const SITE_DEF = {"prods": [{"id": 1, "cat": "rebar", "n": {"uk": "Фіксатор «Настил»", "en": "Slab chair “Nastil”"}, "d": {"uk": "Забезпечує проєктну висоту захисного шару бетону під горизонтальною арматурою на сипкій основі: ґрунті, щебені, піску, а також на мембрані чи плівці. Збільшена площа основи не дає виробу занурюватися.", "en": "Sets the design concrete cover under horizontal rebar on loose bases: soil, gravel, sand, membranes and films. The enlarged base keeps the part from sinking."}, "u": "pc", "v": [["25-30", "1.728", 300], ["30-40", "1.480", 200], ["50-60", "1.728", 200], ["70-80", "1.860", 150], ["90-100", "1.980", 150]], "sp": [["Призначення", "Purpose", "Сипуча основа", "Loose base"], ["Тип", "Type", "Стійка", "Chair"], ["Матеріал", "Material", "Пластик", "Plastic"], ["Робоче положення", "Working position", "Горизонтальне", "Horizontal"]], "on": true}, {"id": 2, "cat": "rebar", "n": {"uk": "Фіксатор «Стійка»", "en": "Rebar chair “Stiika”"}, "d": {"uk": "Тримає арматуру в горизонтальному положенні в плитах перекриття, стяжках і промислових підлогах на бетонній чи іншій твердій основі. Конструкція розподіляє навантаження по всій площі й витримує тиск арматурного каркаса.", "en": "Keeps rebar level in floor slabs, screeds and industrial floors on concrete or another solid base. The design spreads the load across the footprint and withstands the pressure of the rebar cage."}, "u": "pc", "v": [["20-25-30", "1.728", 300], ["25-30", "1.480", 200], ["35-40", "1.728", 200], ["35-40-35", "1.860", 150]], "sp": [["Витрата", "Consumption", "4–6 шт/м²", "4–6 pcs/m²"], ["Тип", "Type", "Стійка", "Chair"], ["Матеріал", "Material", "Пластик", "Plastic"], ["Робоче положення", "Working position", "Горизонтальне", "Horizontal"]], "on": true}, {"id": 3, "cat": "rebar", "n": {"uk": "Фіксатор «Зірочка»", "en": "Star spacer “Zirochka”"}, "d": {"uk": "Створює захисний шар для вертикальної арматури діаметром 6–16 мм у стінах, колонах і стовпах, а також у кутових горизонтальних каркасах. Міцний еластичний замок дозволяє працювати з арматурою різного діаметра.", "en": "Creates the concrete cover for vertical rebar of 6–16 mm in walls, columns and pillars, and in corner horizontal cages. A strong elastic lock fits rebar of different diameters."}, "u": "pc", "v": [["15/6-12", "1.728", 2000], ["25/6-12", "0.504", 1000], ["25/4-20", "0.630", 500], ["30/8-20", "0.804", 500], ["35/6-12", "0.960", 500], ["40/14-20", "1.260", 200], ["50/12-20", "1.608", 200]], "sp": [["Арматура", "Rebar", "Ø 6–16 мм", "Ø 6–16 mm"], ["Застосування", "Use", "Вертикальні елементи", "Vertical elements"], ["Матеріал", "Material", "Пластик", "Plastic"]], "on": true}, {"id": 4, "cat": "rebar", "n": {"uk": "Фіксатор «Защіпка»", "en": "Clip spacer “Zashchipka”"}, "d": {"uk": "Фіксує арматуру в горизонтальному положенні при влаштуванні плит перекриття, стяжок і промислових підлог на бетонній поверхні.", "en": "Holds rebar horizontally in floor slabs, screeds and industrial floors on a concrete surface."}, "u": "pc", "v": [["15/10", "0.456", 1000], ["20/10", "0.480", 1000], ["25/10", "0.528", 1000]], "sp": [["Витрата", "Consumption", "4–6 шт/м²", "4–6 pcs/m²"], ["Матеріал", "Material", "Пластик", "Plastic"], ["Робоче положення", "Working position", "Горизонтальне", "Horizontal"]], "on": true}, {"id": 5, "cat": "rebar", "n": {"uk": "Фіксатор «Засувка»", "en": "Slide spacer “Zasuvka”"}, "d": {"uk": "Фіксує арматуру на бетонній основі в плитах перекриття, стяжках і промислових підлогах. Конструкція розподіляє навантаження по площі виробу й надійно витримує тиск арматурного каркаса.", "en": "Holds rebar on a concrete base in slabs, screeds and industrial floors. The design spreads the load and reliably withstands the pressure of the rebar cage."}, "u": "pc", "v": [["50/8-24", "1.98", 250]], "sp": [["Тип", "Type", "Стійка", "Chair"], ["Матеріал", "Material", "Пластик", "Plastic"], ["Робоче положення", "Working position", "Горизонтальне", "Horizontal"]], "on": true}, {"id": 6, "cat": "form", "n": {"uk": "Фіксатор «Конус»", "en": "Cone spacer “Konus”"}, "d": {"uk": "Надягається на ПВХ- або поліетиленову трубку діаметром 22 мм і захищає елементи опалубки від впливу бетону, збільшуючи площу контакту зі щитом. Не допускає затікання бетону в трубку й потрапляння його на стяжний гвинт; стійкий до навантажень, агресивного середовища та перепаду температур.", "en": "Fits a 22 mm PVC or PE tube and protects formwork elements from concrete, increasing the contact area with the panel. Keeps concrete out of the tube and off the tie rod; resistant to loads, aggressive environments and temperature swings."}, "u": "pc", "v": [["22", "0.444", 1000]], "sp": [["Діаметр трубки", "Tube diameter", "22 мм", "22 mm"], ["Матеріал", "Material", "Пластик", "Plastic"]], "on": true}, {"id": 7, "cat": "form", "n": {"uk": "Фіксатор «Корок-ялинка»", "en": "Fir-tree plug"}, "d": {"uk": "Універсальний корок для закриття невикористаних отворів під анкерні стрижні в опалубці, а також отворів у стінах після демонтажу опалубки.", "en": "A universal plug that closes unused anchor-rod holes in formwork, as well as holes left in walls after the formwork is removed."}, "u": "pc", "v": [["24", "0.84", 1000]], "sp": [["Матеріал", "Material", "Пластик", "Plastic"]], "on": true}, {"id": 8, "cat": "form", "n": {"uk": "Фіксатор «Корок»", "en": "Plug “Korok”"}, "d": {"uk": "Пластикова заглушка циліндричної форми. Запобігає затіканню бетонної суміші в монтажні отвори опалубних щитів і герметизує отвори в монолітних конструкціях.", "en": "A cylindrical plastic plug. Keeps concrete mix out of the mounting holes in formwork panels and seals holes in monolithic structures."}, "u": "pc", "v": [["24", "0.60", 1000]], "sp": [["Матеріал", "Material", "Пластик", "Plastic"]], "on": true}, {"id": 9, "cat": "form", "n": {"uk": "Фіксатор «Труба»", "en": "Spacer tube"}, "d": {"uk": "Утримує відстань між опалубними щитами при влаштуванні колон і пілонів та не допускає потрапляння бетону на стяжний гвинт під час заливання. Гвинт легко виймається з конструкції. Доступна з поліетилену (П/Е) і ПВХ.", "en": "Keeps the distance between formwork panels when casting columns and pylons and prevents concrete from reaching the tie rod during pouring. The rod is easy to remove. Available in PE and PVC."}, "u": "m", "v": [[["П/Е", "PE"], "10.60", 100], [["ПВХ", "PVC"], "13.50", 100]], "sp": [["Матеріал", "Material", "П/Е, ПВХ", "PE, PVC"], ["Стійкість", "Resistance", "До навантажень, агресивного середовища, перепаду температур", "Loads, aggressive environments, temperature swings"]], "on": true}], "posts": [{"id": 17, "st": "pub", "img": "/assets/img/blog/komplektatsiia-obiekta.webp", "tag": ["Будівництво", "Construction"], "date": "2026-10-13", "slug": {"uk": "komplektatsiia-budivelnoho-obiekta", "en": "construction-site-supply"}, "t": ["Комплектація будівельного об’єкта: фіксатори, опалубка та матеріали від одного постачальника", "Construction site supply: spacers, formwork accessories and materials from one supplier"], "e": ["Як підряднику чи забудовнику закупити фіксатори арматури, елементи опалубки й супутні матеріали в одного постачальника: специфікація, графік поставок, документи й доставка на об’єкт.", "How a contractor or developer can buy rebar spacers, formwork accessories and related materials from one supplier: specification, delivery schedule, paperwork and delivery to site."], "b": [[["p", "На будівництві матеріали рідко закінчуються вчасно. Фіксатори докуповують у одному магазині, конуси для опалубки — в іншому, труби — в третьому. Кожна закупівля — це окремий рахунок, окрема доставка й час прораба. Комплектація об’єкта одним постачальником знімає більшість цих проблем."], ["p", "У цій статті розповідаємо, як працює комплектація будівельного об’єкта, які матеріали можна отримати в одному замовленні і як організувати поставки під етапи робіт. Детальніше про послугу — на сторінці <a href=\"/komplektatsiia-obiektiv\" data-go=\"soon\" data-a=\"2\">«Комплектація об’єктів»</a>."], ["h2", "Що таке комплектація об’єкта"], ["p", "Комплектація — це коли постачальник приймає вашу специфікацію чи кошторис і забезпечує поставку всіх позицій: власної продукції та супутніх матеріалів від перевірених партнерів. Ви отримуєте один рахунок, один графік і одного відповідального менеджера."], ["h2", "Що можна отримати в одному замовленні"], ["ul", "<li><b>Фіксатори арматури власного виробництва</b> — <a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">«Настил»</a>, <a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">«Стійка»</a>, <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">«Зірочка»</a>, «Защіпка», «Засувка» під захисний шар вашого проєкту;</li><li><b>Елементи для опалубки</b> — <a href=\"/dystantsiina-truba\" data-go=\"product\" data-a=\"9-0\">дистанційні труби</a> (метрами), <a href=\"/fiksator-konus\" data-go=\"product\" data-a=\"6-0\">конуси</a>, <a href=\"/fiksator-korok\" data-go=\"product\" data-a=\"8-0\">корки</a> і корки-ялинки;</li><li><b>Супутні будівельні матеріали</b> за вашою специфікацією — підбираємо через перевірених постачальників.</li>"], ["blockquote", "<p>Один постачальник — це не лише зручність. Це менше помилок у специфікаціях, менше простоїв бригади й прозорі документи для бухгалтерії.</p>"], ["h2", "Як ми працюємо"], ["ol", "<li><b>Специфікація.</b> Ви надсилаєте кошторис, специфікацію або креслення. Якщо переліку ще немає, допоможемо порахувати фіксатори — методика є в статті <a href=\"/blog/yak-rozrakhuvaty-kilkist-fiksatoriv\" data-go=\"post\" data-a=\"9\">«Як розрахувати кількість фіксаторів»</a>.</li><li><b>Пропозиція.</b> Готуємо комерційну пропозицію за всіма позиціями з цінами й термінами.</li><li><b>Графік.</b> Погоджуємо поставки партіями під етапи: фундамент, стіни, перекриття.</li><li><b>Відвантаження.</b> Відвантажуємо зі складів у Львові та Києві й доставляємо на об’єкт.</li><li><b>Документи.</b> Рахунок, видаткові накладні й ТТН до кожної поставки.</li>"], ["cta", "{\"t\": \"Комплектуємо ваш об’єкт\", \"d\": \"Надішліть специфікацію або кошторис — підготуємо пропозицію з графіком поставок під етапи робіт.\", \"b\": [[\"Комплектація об’єктів\", \"srv2\", \"soon\", \"2\", \"/komplektatsiia-obiektiv\"], [\"Надіслати специфікацію\", \"rfq\"]]}"], ["h2", "Поставки під етапи будівництва"], ["p", "Не потрібно завозити все одразу й захаращувати майданчик. Типовий графік:"], ["ul", "<li><b>Фундамент:</b> «Настил» під нижню сітку, «Зірочки» для бічних граней.</li><li><b>Стіни й колони:</b> «Зірочки», дистанційні труби, конуси й корки для щитової опалубки.</li><li><b>Перекриття:</b> «Стійки» й «Защіпки» під нижню сітку, «Зірочки» для торців.</li>"], ["p", "Так ви платите за матеріали ближче до моменту використання, а на майданчику немає зайвих запасів."], ["h2", "Переваги для підрядника й забудовника"], ["ul", "<li>менше постачальників — менше договорів і рахунків;</li><li>ціни виробника на фіксатори й елементи опалубки;</li><li>графік поставок під етапи робіт;</li><li>повний пакет документів для безготівкового розрахунку;</li><li>доставка по всій Україні — перевізниками, транспортом партнерів або поштою.</li>"], ["p", "Про спосіб і вартість доставки читайте на сторінці <a href=\"/dostavka\" data-go=\"delivery\">«Доставка та оплата»</a>."], ["h2", "Часті питання"], ["h3", "Чи є мінімальна сума замовлення?"], ["p", "Умови залежать від складу й обсягу. Надішліть специфікацію — запропонуємо оптимальний варіант."], ["h3", "Чи можна змінити графік поставок під час будівництва?"], ["p", "Так. Графік коригуємо разом із вами, якщо змінюються етапи робіт."], ["h3", "Чи працюєте ви з тендерними закупівлями?"], ["p", "Надаємо комерційні пропозиції та документи, потрібні для закупівель. Уточніть вимоги вашого тендеру в менеджера."], ["h2", "Висновок"], ["p", "Комплектація об’єкта одним постачальником — це фіксатори, елементи опалубки й супутні матеріали в одному замовленні, поставки під етапи й прозорі документи. Надішліть специфікацію через форму нижче — підготуємо пропозицію з графіком поставок."]], [["p", "On a construction site, materials rarely run out on time. Spacers are bought in one shop, formwork cones in another, tubes in a third. Each purchase means a separate invoice, a separate delivery and the site manager’s time. Supplying a site through one supplier removes most of these problems."], ["p", "This article explains how site supply works, which materials you can get in one order and how to schedule deliveries by work stage. More about the service: <a href=\"/en/construction-supply\" data-go=\"soon\" data-a=\"2\">Site supply</a>."], ["h2", "What site supply is"], ["p", "The supplier takes your specification or bill of quantities and delivers every item: its own products plus related materials from trusted partners. You get one invoice, one schedule and one responsible manager."], ["h2", "What you can get in one order"], ["ul", "<li><b>Rebar spacers from our own production</b> — <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil”</a>, <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika”</a>, <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka”</a>, “Zashchipka”, “Zasuvka” matched to your design cover;</li><li><b>Formwork accessories</b> — <a href=\"/en/spacer-tube\" data-go=\"product\" data-a=\"9-0\">spacer tubes</a> (by the metre), <a href=\"/en/cone-spacer-konus\" data-go=\"product\" data-a=\"6-0\">cones</a>, <a href=\"/en/formwork-plug-korok\" data-go=\"product\" data-a=\"8-0\">plugs</a> and fir-tree plugs;</li><li><b>Related building materials</b> to your specification, sourced from trusted suppliers.</li>"], ["blockquote", "<p>One supplier is not just convenience. It means fewer specification errors, less crew downtime and clear paperwork for accounting.</p>"], ["h2", "How we work"], ["ol", "<li><b>Specification.</b> You send a bill of quantities, specification or drawings. If there is no list yet, we will help calculate spacers — see <a href=\"/en/blog/how-to-calculate-rebar-spacers\" data-go=\"post\" data-a=\"9\">“How to calculate rebar spacers”</a>.</li><li><b>Offer.</b> We prepare a quote for all items with prices and lead times.</li><li><b>Schedule.</b> We agree deliveries in batches by stage: foundation, walls, slabs.</li><li><b>Shipping.</b> We ship from our Lviv and Kyiv warehouses and deliver to site.</li><li><b>Paperwork.</b> Invoice, delivery notes and waybills with every shipment.</li>"], ["cta", "{\"t\": \"We will supply your site\", \"d\": \"Send a specification or bill of quantities — we will prepare an offer with a delivery schedule by work stage.\", \"b\": [[\"Site supply\", \"srv2\", \"soon\", \"2\", \"/en/construction-supply\"], [\"Send a specification\", \"rfq\"]]}"], ["h2", "Deliveries by construction stage"], ["p", "There is no need to bring everything at once and clutter the site. A typical schedule:"], ["ul", "<li><b>Foundation:</b> “Nastil” for the bottom mesh, “Zirochka” for side faces.</li><li><b>Walls and columns:</b> “Zirochka”, spacer tubes, cones and plugs for panel formwork.</li><li><b>Slabs:</b> “Stiika” and “Zashchipka” for the bottom mesh, “Zirochka” for edges.</li>"], ["p", "You pay for materials closer to when you use them, and the site holds no surplus."], ["h2", "Benefits for contractors and developers"], ["ul", "<li>fewer suppliers — fewer contracts and invoices;</li><li>manufacturer prices on spacers and formwork accessories;</li><li>a delivery schedule matched to work stages;</li><li>full paperwork for bank-transfer payment;</li><li>delivery across Ukraine — by carriers, partner transport or post.</li>"], ["p", "Delivery options and cost: <a href=\"/en/delivery\" data-go=\"delivery\">Delivery and payment</a>."], ["h2", "FAQ"], ["h3", "Is there a minimum order?"], ["p", "It depends on contents and volume. Send your specification and we will propose the best option."], ["h3", "Can the delivery schedule change during construction?"], ["p", "Yes. We adjust the schedule with you when work stages change."], ["h3", "Do you work with tenders?"], ["p", "We provide quotes and the documents needed for procurement. Check your tender’s requirements with your manager."], ["h2", "Conclusion"], ["p", "Site supply from one supplier means spacers, formwork accessories and related materials in one order, deliveries by stage and clear paperwork. Send your specification through the form below and we will prepare an offer with a delivery schedule."]]]}, {"id": 16, "st": "pub", "img": "/assets/img/blog/remont-presform.webp", "tag": ["Пресформи", "Molds"], "date": "2026-09-08", "slug": {"uk": "remont-i-modernizatsiia-presform", "en": "mold-repair-and-upgrade"}, "t": ["Ремонт і модернізація пресформ: коли вигідніше відновити стару, ніж замовляти нову", "Mold repair and upgrade: when restoring an old mold beats buying a new one"], "e": ["Ознаки зношеної пресформи, які ремонти можливі, коли модернізація окупається і як оцінити, що вигідніше — відновити форму чи виготовити нову.", "Signs of a worn injection mold, which repairs are possible, when an upgrade pays off and how to decide whether to restore the mold or make a new one."], "b": [[["p", "Пресформа працює роками, але не вічно. Облой на деталях, сліди на поверхні, підтікання, заїдання рухомих елементів — усе це сигнали, що форма потребує уваги. Багато хто одразу думає про нову пресформу, хоча часто ремонт або модернізація обходяться значно дешевше й швидше."], ["p", "У цій статті розповідаємо, за якими ознаками видно зношену пресформу, які ремонти можливі і як вирішити, що вигідніше — відновити форму чи замовити нову."], ["h2", "Ознаки, що пресформа потребує ремонту"], ["ul", "<li><b>Облой</b> — тонкий «ласт» по лінії рознімання через знос площин змикання.</li><li><b>Сліди, подряпини чи матовість</b> на поверхні деталі.</li><li><b>Нестабільні розміри</b> від партії до партії.</li><li><b>Заїдання</b> повзунів, знаків, виштовхувачів.</li><li><b>Підтікання</b> в системі охолодження.</li><li><b>Збільшений час циклу</b>, щоб отримати якісну деталь.</li>"], ["blockquote", "<p>Чим раніше помітити знос, тим дешевший ремонт. Облой, на який не звертали уваги, з часом руйнує площини змикання.</p>"], ["h2", "Які роботи можливі"], ["h3", "Ремонт"], ["ul", "<li>відновлення площин змикання й усунення облою;</li><li>заміна зношених виштовхувачів, втулок, напрямних;</li><li>ремонт рухомих елементів;</li><li>відновлення формоутворної поверхні, полірування;</li><li>ремонт каналів охолодження.</li>"], ["h3", "Модернізація"], ["ul", "<li>зміна виробу — подовження, поглиблення, нові отвори (якщо зміни зводяться до видалення металу);</li><li>додавання гнізд або змінних вставок під нові типорозміри;</li><li>покращення охолодження для скорочення циклу;</li><li>заміна ливникової системи.</li>"], ["h2", "Ремонт чи нова пресформа: як вирішити"], ["p", "Ремонт вигідний, якщо:"], ["ul", "<li>основний корпус і формоутворні частини в задовільному стані;</li><li>проблема локальна — облой, знос виштовхувачів, полірування;</li><li>виріб не змінюється кардинально.</li>"], ["p", "Нова форма доцільніша, якщо:"], ["ul", "<li>формоутворні вставки сильно зношені або пошкоджені;</li><li>виріб суттєво змінюється;</li><li>потрібно значно збільшити продуктивність — більше гнізд, гарячі канали.</li>"], ["p", "Ми оцінюємо стан форми й пропонуємо обидва варіанти з вартістю й термінами, щоб ви бачили різницю. Якщо вирішите робити нову, процес описано в статті <a href=\"/blog/vyhotovlennia-presform-vid-kreslennia-do-partii\" data-go=\"post\" data-a=\"13\">«Виготовлення пресформ: від креслення до першої партії»</a>."], ["cta", "{\"t\": \"Потрібен ремонт пресформи?\", \"d\": \"Надішліть фото форми й деталі з дефектом — оцінимо стан і запропонуємо ремонт, модернізацію або нову форму.\", \"b\": [[\"Виготовлення пресформ\", \"srv1\", \"soon\", \"1\", \"/vyhotovlennia-presform\"], [\"Надіслати фото\", \"rfq\"]]}"], ["h2", "Як продовжити життя пресформи"], ["ul", "<li>регулярно чистіть площини змикання й вентиляційні канали;</li><li>змащуйте рухомі елементи;</li><li>контролюйте стан системи охолодження;</li><li>зберігайте форму з консервацією між тиражами;</li><li>не ігноруйте перший облой.</li>"], ["p", "Якщо форма зберігається в нас, ми обслуговуємо її між партіями — і ви отримуєте стабільну якість кожного тиражу."], ["h2", "Часті питання"], ["h3", "Чи ремонтуєте ви пресформи, виготовлені іншими виробниками?"], ["p", "Так. Ми оцінюємо стан будь-якої форми, сумісної з нашим обладнанням, і пропонуємо варіанти ремонту."], ["h3", "Скільки триває ремонт?"], ["p", "Залежить від обсягу робіт: дрібний ремонт — від кількох днів, модернізація — довше. Терміни називаємо після огляду."], ["h3", "Чи можна після ремонту одразу відлити партію?"], ["p", "Так. Після ремонту робимо пробне лиття і, за погодженням, запускаємо партію на нашому обладнанні — <a href=\"/lyttia-plastyku\" data-go=\"soon\" data-a=\"0\">послуга лиття</a>."], ["h2", "Висновок"], ["p", "Облой, сліди на поверхні й нестабільні розміри — сигнал перевірити пресформу. Часто ремонт або модернізація обходяться дешевше за нову форму і повертають якість деталей. Надішліть нам фото форми й дефектної деталі — оцінимо й запропонуємо оптимальне рішення."]], [["p", "A mold runs for years, but not forever. Flash on parts, surface marks, leaks, sticking moving elements — all signal that the mold needs attention. Many people immediately think of a new mold, although repair or upgrade is often much cheaper and faster."], ["p", "This article covers the signs of a worn mold, the repairs that are possible and how to decide what pays off better — restoring the mold or ordering a new one."], ["h2", "Signs a mold needs repair"], ["ul", "<li><b>Flash</b> — thin fins on the parting line from worn shut-off surfaces.</li><li><b>Marks, scratches or dullness</b> on the part surface.</li><li><b>Unstable dimensions</b> from batch to batch.</li><li><b>Sticking</b> slides, lifters or ejectors.</li><li><b>Leaks</b> in the cooling system.</li><li><b>Longer cycle time</b> needed to get a good part.</li>"], ["blockquote", "<p>The earlier you catch wear, the cheaper the repair. Flash that is ignored eventually destroys the shut-off surfaces.</p>"], ["h2", "What can be done"], ["h3", "Repair"], ["ul", "<li>restoring shut-off surfaces and eliminating flash;</li><li>replacing worn ejectors, bushings and guides;</li><li>repairing moving elements;</li><li>restoring and polishing cavity surfaces;</li><li>repairing cooling channels.</li>"], ["h3", "Upgrade"], ["ul", "<li>part changes — longer, deeper, new holes (when changes mean removing steel);</li><li>adding cavities or interchangeable inserts for new sizes;</li><li>better cooling to shorten the cycle;</li><li>a new runner system.</li>"], ["h2", "Repair or a new mold: how to decide"], ["p", "Repair pays off if:"], ["ul", "<li>the mold base and cavity parts are in reasonable condition;</li><li>the problem is local — flash, worn ejectors, polishing;</li><li>the part does not change radically.</li>"], ["p", "A new mold makes more sense if:"], ["ul", "<li>cavity inserts are badly worn or damaged;</li><li>the part changes significantly;</li><li>you need much higher output — more cavities, hot runners.</li>"], ["p", "We assess the mold and propose both options with cost and timing so you can see the difference. If you go for a new mold, the process is described in <a href=\"/en/blog/mold-making-from-drawing-to-first-batch\" data-go=\"post\" data-a=\"13\">“Mold making: from drawing to first batch”</a>."], ["cta", "{\"t\": \"Need a mold repaired?\", \"d\": \"Send photos of the mold and a defective part — we will assess it and propose repair, upgrade or a new mold.\", \"b\": [[\"Mold making\", \"srv1\", \"soon\", \"1\", \"/en/mold-making\"], [\"Send photos\", \"rfq\"]]}"], ["h2", "How to extend mold life"], ["ul", "<li>clean shut-off surfaces and vents regularly;</li><li>lubricate moving elements;</li><li>monitor the cooling system;</li><li>store the mold preserved between runs;</li><li>do not ignore the first flash.</li>"], ["p", "If your mold is stored with us, we maintain it between batches — and you get stable quality in every run."], ["h2", "FAQ"], ["h3", "Do you repair molds made by other manufacturers?"], ["p", "Yes. We assess any mold compatible with our equipment and propose repair options."], ["h3", "How long does repair take?"], ["p", "It depends on the work: minor repairs from a few days, upgrades longer. We give timing after inspection."], ["h3", "Can you mold a batch right after repair?"], ["p", "Yes. After repair we run trial shots and, if agreed, mold a batch on our equipment — <a href=\"/en/injection-molding\" data-go=\"soon\" data-a=\"0\">molding service</a>."], ["h2", "Conclusion"], ["p", "Flash, surface marks and unstable dimensions are signals to check the mold. Repair or upgrade is often cheaper than a new mold and restores part quality. Send us photos of the mold and a defective part and we will propose the best solution."]]]}, {"id": 15, "st": "pub", "img": "/assets/img/blog/zamina-importnykh-detalei.webp", "tag": ["Виробництво", "Production"], "date": "2026-07-28", "slug": {"uk": "zamina-importnykh-plastykovykh-detalei", "en": "replacing-imported-plastic-parts"}, "t": ["Заміна імпортних пластикових деталей: як перенести виробництво з Китаю в Україну", "Replacing imported plastic parts: how to move production from China to Ukraine"], "e": ["Чому компанії переносять лиття пластикових деталей з Азії в Україну, як виготовити деталь за зразком без креслень і що потрібно, щоб перейти на українського виробника без зупинки поставок.", "Why companies move plastic part molding from Asia to Ukraine, how to make a part from a sample without drawings and how to switch to a Ukrainian manufacturer without interrupting supply."], "b": [[["p", "Ще кілька років тому замовлення пластикових деталей у Китаї здавалося безальтернативним: низька ціна за штуку перекривала все. Сьогодні багато компаній рахують інакше — з урахуванням логістики, термінів, мінімальних партій, курсових ризиків і заморожених на складі грошей. І все частіше переносять лиття ближче до себе — в Україну."], ["p", "У цій статті розповідаємо, коли заміна імпортних пластикових деталей вигідна, як виготовити деталь за зразком без креслень і як перейти на українського виробника без зупинки поставок."], ["h2", "Чому компанії переносять виробництво"], ["ul", "<li><b>Терміни.</b> Доставка з Азії займає тижні, а будь-яка затримка зупиняє ваш конвеєр чи продажі.</li><li><b>Мінімальні партії.</b> Іноземні фабрики часто вимагають великих тиражів, і гроші місяцями лежать на складі.</li><li><b>Логістика й мито</b> збільшують реальну ціну деталі.</li><li><b>Комунікація.</b> Узгодити зміну чи розібратися з браком значно простіше, коли виробник у твоїй країні.</li><li><b>Контроль якості.</b> Можна приїхати на виробництво й побачити процес.</li>"], ["blockquote", "<p>Порівнюйте не ціну деталі на заводі, а повну вартість: доставку, мито, заморожені гроші, ризик затримок і брак.</p>"], ["h2", "Деталь за зразком: якщо креслень немає"], ["p", "Найчастіша ситуація — у вас є лише сама деталь, а креслень і пресформи немає (вона лишилася у виробника за кордоном). Це не проблема:"], ["ol", "<li>Ви надсилаєте зразки деталі.</li><li>Ми виконуємо обмір і будуємо 3D-модель.</li><li>Погоджуємо модель з вами і, за потреби, покращуємо слабкі місця оригіналу.</li><li>Проєктуємо й виготовляємо нову пресформу — <a href=\"/vyhotovlennia-presform\" data-go=\"soon\" data-a=\"1\">послуга виготовлення пресформ</a>.</li><li>Відливаємо пробну партію й порівнюємо з оригіналом.</li>"], ["h2", "Матеріал"], ["p", "Важливо підібрати пластик, який відповідає оригіналу за властивостями: міцністю, гнучкістю, стійкістю до температури чи УФ. Якщо марка невідома, ми підберемо аналог за умовами роботи деталі."], ["h2", "Як перейти без зупинки поставок"], ["ul", "<li>Почніть процес, поки у вас ще є запас імпортних деталей.</li><li>Погодьте пробну партію й випробуйте її у вашому виробі.</li><li>Запускайте серію до того, як закінчиться складський запас.</li><li>Плануйте наступні партії з урахуванням коротших термінів — склад можна зменшити.</li>"], ["cta", "{\"t\": \"Хочете замінити імпортну деталь?\", \"d\": \"Надішліть зразок або фото з розмірами — оцінимо, підготуємо модель і розрахуємо пресформу й лиття.\", \"b\": [[\"Лиття пластикових виробів\", \"srv0\", \"soon\", \"0\", \"/lyttia-plastyku\"], [\"Надіслати зразок\", \"rfq\"]]}"], ["h2", "Що ми пропонуємо"], ["ul", "<li>виготовлення деталей за зразком, кресленням або 3D-моделлю;</li><li>проєктування й виготовлення пресформ, що належать замовнику;</li><li>серійне лиття на нашому обладнанні у Львові — <a href=\"/lyttia-plastyku\" data-go=\"soon\" data-a=\"0\">послуга лиття</a>;</li><li>пакування й доставку по Україні, документи для юридичних осіб.</li>"], ["p", "Як обрати виробника для контрактного лиття, ми розповідали в статті <a href=\"/blog/kontraktne-lyttia-plastyku\" data-go=\"post\" data-a=\"11\">«Контрактне лиття пластику в Україні»</a>."], ["h2", "Часті питання"], ["h3", "Чи можна відлити деталь у пресформі, привезеній з-за кордону?"], ["p", "Так, якщо вона сумісна з нашим обладнанням. Ми перевіримо форму, підберемо режими й зробимо пробне лиття."], ["h3", "Скільки зразків потрібно для обміру?"], ["p", "Зазвичай достатньо кількох штук: одну можна використати для обміру, інші — для порівняння з пробною партією."], ["h3", "Чи вийде дешевше, ніж у Китаї?"], ["p", "Ціна деталі на заводі може бути співставною або трохи вищою, але повна вартість з урахуванням логістики, термінів і запасів часто виявляється нижчою. Порахуємо для вашого випадку."], ["h2", "Висновок"], ["p", "Перенести лиття пластикових деталей в Україну можна навіть без креслень: за зразком ми підготуємо модель, виготовимо пресформу й запустимо серію. Почніть, поки є запас імпортних деталей, — і перейдете без зупинки поставок. Залиште заявку нижче з описом деталі."]], [["p", "A few years ago ordering plastic parts in China seemed the only option: the low unit price outweighed everything. Today many companies count differently — including logistics, lead times, minimum orders, currency risk and cash frozen in stock. And more and more of them move molding closer to home — to Ukraine."], ["p", "This article explains when replacing imported plastic parts pays off, how to make a part from a sample without drawings and how to switch suppliers without stopping supply."], ["h2", "Why companies move production"], ["ul", "<li><b>Lead times.</b> Shipping from Asia takes weeks, and any delay stops your line or sales.</li><li><b>Minimum orders.</b> Foreign factories often require large runs, and cash sits in stock for months.</li><li><b>Logistics and duties</b> raise the real part price.</li><li><b>Communication.</b> Agreeing changes or resolving defects is far easier with a manufacturer in your own country.</li><li><b>Quality control.</b> You can visit the plant and see the process.</li>"], ["blockquote", "<p>Compare not the ex-works part price but the total cost: shipping, duties, frozen cash, delay risk and rejects.</p>"], ["h2", "A part from a sample: no drawings needed"], ["p", "The most common situation: you only have the part itself, with no drawings or mold (it stayed with the overseas factory). That is not a problem:"], ["ol", "<li>You send samples of the part.</li><li>We measure them and build a 3D model.</li><li>We agree the model with you and, if needed, improve weak points of the original.</li><li>We design and build a new mold — <a href=\"/en/mold-making\" data-go=\"soon\" data-a=\"1\">mold making service</a>.</li><li>We mold a trial batch and compare it with the original.</li>"], ["h2", "Material"], ["p", "It is important to match the original’s properties: strength, flexibility, temperature or UV resistance. If the grade is unknown, we choose an equivalent for the part’s operating conditions."], ["h2", "Switching without stopping supply"], ["ul", "<li>Start while you still have imported parts in stock.</li><li>Approve a trial batch and test it in your product.</li><li>Launch the series before stock runs out.</li><li>Plan further batches around shorter lead times — you can hold less stock.</li>"], ["cta", "{\"t\": \"Want to replace an imported part?\", \"d\": \"Send a sample or photos with dimensions — we will assess it, prepare a model and quote the mold and molding.\", \"b\": [[\"Injection molding\", \"srv0\", \"soon\", \"0\", \"/en/injection-molding\"], [\"Send a sample\", \"rfq\"]]}"], ["h2", "What we offer"], ["ul", "<li>parts made from a sample, drawing or 3D model;</li><li>design and manufacture of molds owned by the customer;</li><li>series molding on our equipment in Lviv — <a href=\"/en/injection-molding\" data-go=\"soon\" data-a=\"0\">molding service</a>;</li><li>packing, delivery across Ukraine and paperwork for businesses.</li>"], ["p", "How to choose a contract molder: <a href=\"/en/blog/contract-injection-molding-ukraine\" data-go=\"post\" data-a=\"11\">“Contract plastic injection molding in Ukraine”</a>."], ["h2", "FAQ"], ["h3", "Can you mold in a mold brought from abroad?"], ["p", "Yes, if it fits our machines. We check the mold, set the process and run trial shots."], ["h3", "How many samples do you need?"], ["p", "Usually a few: one for measuring, others for comparison with the trial batch."], ["h3", "Will it be cheaper than China?"], ["p", "The ex-works part price may be similar or slightly higher, but the total cost including logistics, lead time and stock often turns out lower. We will calculate it for your case."], ["h2", "Conclusion"], ["p", "You can move plastic part molding to Ukraine even without drawings: from a sample we prepare a model, build a mold and start the series. Begin while you still have imported stock and switch without stopping supply. Leave a request below describing your part."]]]}, {"id": 14, "st": "pub", "img": "/assets/img/blog/kontraktne-vyrobnytstvo.webp", "tag": ["Виробництво", "Production"], "date": "2026-06-23", "slug": {"uk": "yak-zapustyty-vlasnyi-plastykovyi-produkt", "en": "launch-your-own-plastic-product"}, "t": ["Як запустити власний пластиковий продукт без власного цеху: від ідеї до серійної партії", "How to launch your own plastic product without a factory: from idea to series batch"], "e": ["Покроковий план для підприємців і виробників: як перетворити ідею пластикового виробу на серійну продукцію без купівлі обладнання — модель, прототип, пресформа, лиття, пакування.", "A step-by-step plan for entrepreneurs and manufacturers to turn a plastic product idea into series production without buying equipment — model, prototype, mold, molding, packing."], "b": [[["p", "Багато сильних продуктів починаються з простої ідеї: зручніше кріплення, міцніша заглушка, власний аксесуар для лінійки товарів. Але між ідеєю і полицею — виробництво, і саме воно лякає найбільше: термопластавтомати, пресформи, технологи, сировина. Добра новина — купувати все це не обов’язково."], ["p", "У цій статті розповідаємо, як запустити власний пластиковий продукт без власного цеху, з контрактним виробником, і які кроки пройти, щоб не втратити час і гроші."], ["h2", "Крок 1. Сформулюйте вимоги до виробу"], ["p", "Перш ніж малювати, запишіть, що виріб має робити: навантаження, температура, контакт із водою чи хімією, вулиця чи приміщення, колір, вимоги до вигляду. Від цього залежать матеріал і конструкція."], ["h2", "Крок 2. Креслення або 3D-модель"], ["p", "Для розрахунку й виготовлення пресформи потрібна модель. Якщо у вас є лише ескіз або зразок аналогу, ми допоможемо: виконаємо обмір і побудуємо 3D-модель. На цьому ж етапі варто врахувати технологічність — рівні стінки, ухили, радіуси."], ["h2", "Крок 3. Прототип"], ["p", "Якщо конструкція ще не остаточна, перевірте її на прототипі: зібрати, примірити, показати клієнтам. Зміна в моделі коштує копійки порівняно зі зміною в металі пресформи."], ["blockquote", "<p>Найчастіша помилка новачків — замовити пресформу «одразу начисто», а потім переробляти її після перших відгуків покупців.</p>"], ["h2", "Крок 4. Пресформа"], ["p", "Пресформа — найбільша стартова інвестиція. Щоб вона окупилася, кількість гнізд і ресурс підбирають під реальний обсяг продажів, а не «на виріст». Як ми проєктуємо й виготовляємо форми, читайте в статті <a href=\"/blog/vyhotovlennia-presform-vid-kreslennia-do-partii\" data-go=\"post\" data-a=\"13\">«Виготовлення пресформ: від креслення до першої партії»</a>."], ["h2", "Крок 5. Пробна партія"], ["p", "Перші деталі з пресформи — це ще й маркетинговий інструмент: їх можна показати дистриб’юторам, протестувати в реальних умовах і зібрати перші замовлення до запуску великої серії."], ["h2", "Крок 6. Серія, пакування й логістика"], ["p", "Після погодження зразків запускаємо серійне лиття. За потреби пакуємо вироби під ваші вимоги й доставляємо по Україні. Вам залишається продавати."], ["cta", "{\"t\": \"Маєте ідею пластикового виробу?\", \"d\": \"Розкажіть про продукт — підкажемо, з чого почати, і порахуємо пресформу та першу партію.\", \"b\": [[\"Лиття пластикових виробів\", \"srv0\", \"soon\", \"0\", \"/lyttia-plastyku\"], [\"Виготовлення пресформ\", \"srv1\", \"soon\", \"1\", \"/vyhotovlennia-presform\"], [\"Обговорити проєкт\", \"rfq\"]]}"], ["h2", "Скільки коштує старт"], ["p", "Бюджет запуску складається з трьох частин:"], ["ul", "<li><b>модель і прототип</b> — найменша частка, але вона економить найбільше;</li><li><b>пресформа</b> — основна інвестиція, залежить від розмірів і складності виробу та кількості гнізд;</li><li><b>перша партія</b> — матеріал і машинний час.</li>"], ["p", "Пресформа, яку ви оплатили, належить вам. Ціна деталі знижується зі зростанням тиражу, тому продукт стає вигіднішим, щойно продажі ростуть. Що впливає на вартість лиття, ми розписали в статті <a href=\"/blog/lyttia-plastykovykh-vyrobiv-na-zamovlennia-lviv\" data-go=\"post\" data-a=\"12\">«Лиття пластикових виробів на замовлення: ціна й терміни»</a>."], ["h2", "Чому контрактне виробництво вигідне на старті"], ["ul", "<li>не потрібно купувати обладнання й наймати технологів;</li><li>витрати пропорційні обсягам продажів;</li><li>швидкий запуск — за тижні, а не за місяці;</li><li>можна протестувати ринок невеликою партією.</li>"], ["p", "Як обрати надійного виробника, ми розповідали в статті <a href=\"/blog/kontraktne-lyttia-plastyku\" data-go=\"post\" data-a=\"11\">«Контрактне лиття пластику в Україні»</a>."], ["h2", "Часті питання"], ["h3", "Чи можна почати з невеликого тиражу?"], ["p", "Так. Часто старт роблять із пробної партії, а потім переходять до серії. Підкажемо, як оптимізувати пресформу під невеликі обсяги."], ["h3", "Хто відповідає за конструкцію виробу?"], ["p", "Конструкцію визначаєте ви, а ми перевіряємо її технологічність і пропонуємо зміни, які спростять виробництво."], ["h3", "Чи захищені мої креслення?"], ["p", "Ми використовуємо ваші креслення лише для вашого замовлення. За потреби угоду про нерозголошення можна обговорити з менеджером."], ["h2", "Висновок"], ["p", "Власний пластиковий продукт можна запустити без цеху: сформулювати вимоги, підготувати модель, перевірити прототип, виготовити пресформу й запустити лиття з контрактним виробником. Розкажіть нам про свій виріб у формі нижче — і ми запропонуємо план запуску з розрахунком."]], [["p", "Many strong products start with a simple idea: a handier fastener, a tougher cap, your own accessory for a product line. But between the idea and the shelf lies production — machines, molds, process engineers, raw materials. The good news: you do not have to buy any of it."], ["p", "This article explains how to launch your own plastic product with a contract manufacturer, and which steps to take so you do not lose time or money."], ["h2", "Step 1. Define the requirements"], ["p", "Before drawing, write down what the part must do: load, temperature, contact with water or chemicals, indoor or outdoor, colour, appearance. Material and design depend on this."], ["h2", "Step 2. Drawing or 3D model"], ["p", "A model is needed to quote and build the mold. If you only have a sketch or a sample of something similar, we will measure it and build a 3D model. Design for manufacturing at this stage too — even walls, draft, radii."], ["h2", "Step 3. Prototype"], ["p", "If the design is not final, test it with a prototype: assemble it, try it, show it to customers. A change in the model costs very little compared with a change in mold steel."], ["blockquote", "<p>The most common beginner mistake is ordering a “final” mold straight away and reworking it after the first customer feedback.</p>"], ["h2", "Step 4. The mold"], ["p", "The mold is the biggest start-up investment. To pay back, its cavities and tool life are matched to realistic sales, not “room to grow”. How we design and build molds: <a href=\"/en/blog/mold-making-from-drawing-to-first-batch\" data-go=\"post\" data-a=\"13\">“Mold making: from drawing to first batch”</a>."], ["h2", "Step 5. Trial batch"], ["p", "The first parts from the mold are also a sales tool: show them to distributors, test them in real conditions and collect first orders before a large run."], ["h2", "Step 6. Series, packing and logistics"], ["p", "After sample approval we start series molding, pack parts to your requirements and deliver across Ukraine. You focus on selling."], ["cta", "{\"t\": \"Have a plastic product idea?\", \"d\": \"Tell us about it — we will suggest where to start and quote the mold and first batch.\", \"b\": [[\"Injection molding\", \"srv0\", \"soon\", \"0\", \"/en/injection-molding\"], [\"Mold making\", \"srv1\", \"soon\", \"1\", \"/en/mold-making\"], [\"Discuss the project\", \"rfq\"]]}"], ["h2", "What the start costs"], ["p", "The launch budget has three parts:"], ["ul", "<li><b>model and prototype</b> — the smallest share, but it saves the most;</li><li><b>the mold</b> — the main investment, depending on part size, complexity and cavities;</li><li><b>the first batch</b> — material and machine time.</li>"], ["p", "The mold you paid for is yours. The part price falls as runs grow, so the product becomes more profitable as sales grow. What drives molding cost is covered in <a href=\"/en/blog/custom-plastic-injection-molding-lviv\" data-go=\"post\" data-a=\"12\">“Custom plastic injection molding: price and lead times”</a>."], ["h2", "Why contract production pays off at the start"], ["ul", "<li>no equipment to buy and no process engineers to hire;</li><li>costs scale with sales;</li><li>fast launch — weeks, not months;</li><li>you can test the market with a small batch.</li>"], ["p", "How to choose a reliable manufacturer: <a href=\"/en/blog/contract-injection-molding-ukraine\" data-go=\"post\" data-a=\"11\">“Contract plastic injection molding in Ukraine”</a>."], ["h2", "FAQ"], ["h3", "Can I start with a small run?"], ["p", "Yes. Many start with a trial batch and then move to a series. We will suggest how to optimise the mold for small volumes."], ["h3", "Who is responsible for the part design?"], ["p", "You define the design; we check manufacturability and suggest changes that simplify production."], ["h3", "Are my drawings protected?"], ["p", "We use your drawings only for your order. A non-disclosure agreement can be discussed with your manager if needed."], ["h2", "Conclusion"], ["p", "You can launch your own plastic product without a factory: define requirements, prepare a model, test a prototype, build a mold and start molding with a contract manufacturer. Tell us about your part in the form below and we will propose a launch plan with a quote."]]]}, {"id": 13, "st": "pub", "img": "/assets/img/blog/vyhotovlennia-presform.webp", "tag": ["Пресформи", "Molds"], "date": "2026-05-19", "slug": {"uk": "vyhotovlennia-presform-vid-kreslennia-do-partii", "en": "mold-making-from-drawing-to-first-batch"}, "t": ["Виготовлення пресформ для лиття пластику: як ми проходимо шлях від креслення до першої партії", "Mold making for plastic injection: how we go from drawing to the first batch"], "e": ["Як PLASTIZA виготовляє пресформи на замовлення: аналіз виробу, проєктування, виготовлення, пробне лиття й запуск серії. Що отримує замовник на кожному етапі.", "How PLASTIZA makes custom injection molds: part review, design, manufacturing, trial shots and series launch — and what the customer gets at each stage."], "b": [[["p", "Пресформа — це серце будь-якого пластикового виробу. Від її конструкції залежить, скільки коштуватиме кожна деталь, якою буде якість поверхні й розмірів і скільки років форма пропрацює без ремонту. Тому, обираючи виробника пресформи, важливо розуміти не лише ціну, а й те, як побудовано процес."], ["p", "У цій статті розповідаємо, як ми виготовляємо пресформи на замовлення — від першого креслення до першої серійної партії — і що замовник отримує на кожному етапі. Детальніше про послугу — на сторінці <a href=\"/vyhotovlennia-presform\" data-go=\"soon\" data-a=\"1\">«Виготовлення пресформ»</a>."], ["h2", "Етап 1. Аналіз виробу й технічне завдання"], ["p", "Усе починається з креслення, 3D-моделі або зразка. Ми аналізуємо технологічність: товщину стінок, ухили, піднутрення, місце впорскування, вимоги до поверхні. На цьому етапі часто пропонуємо невеликі зміни конструкції, які спрощують форму й зменшують брак."], ["p", "<b>Що ви отримуєте:</b> висновок щодо технологічності, рекомендації та комерційну пропозицію з вартістю й термінами."], ["h2", "Етап 2. Проєктування пресформи"], ["p", "Інженери створюють 3D-модель пресформи: формоутворні вставки, ливникову систему, охолодження, систему виштовхування й рухомі елементи. Кількість гнізд підбираємо під ваш річний обсяг, щоб збалансувати вартість форми й ціну деталі."], ["p", "<b>Що ви отримуєте:</b> погодження конструкції перед виготовленням — зміни на цьому етапі коштують найменше."], ["h2", "Етап 3. Виготовлення"], ["p", "Деталі пресформи обробляють на верстатах із ЧПК, виконують електроерозійну обробку, шліфування й термообробку формоутворних частин. Потім форму збирають і перевіряють рухомі елементи та канали охолодження."], ["blockquote", "<p>Найдешевше виправити помилку на кресленні, дорожче — у металі, і найдорожче — у готовій партії. Тому перші два етапи для нас не формальність.</p>"], ["h2", "Етап 4. Пробне лиття й доведення"], ["p", "Форму встановлюють на термопластавтомат і відливають перші деталі. Технолог підбирає режими, ми вимірюємо зразки й за потреби доводимо форму, доки деталь не відповідатиме кресленню."], ["p", "<b>Що ви отримуєте:</b> пробні зразки для перевірки розмірів, складання й зовнішнього вигляду."], ["h2", "Етап 5. Серія або передача форми"], ["p", "Після погодження зразків є два варіанти:"], ["ul", "<li>ми запускаємо серійне лиття на нашому обладнанні у Львові й постачаємо вам готові вироби — <a href=\"/lyttia-plastyku\" data-go=\"soon\" data-a=\"0\">послуга лиття</a>;</li><li>ми передаємо пресформу вам для використання на вашому підприємстві.</li>"], ["p", "Пресформа, оплачена замовником, належить замовнику."], ["cta", "{\"t\": \"Маєте виріб для нової пресформи?\", \"d\": \"Надішліть креслення, 3D-модель або зразок — підготуємо пропозицію на пресформу й лиття.\", \"b\": [[\"Виготовлення пресформ\", \"srv1\", \"soon\", \"1\", \"/vyhotovlennia-presform\"], [\"Надіслати креслення\", \"rfq\"]]}"], ["h2", "Від чого залежать вартість і терміни"], ["ul", "<li>розміри й складність виробу;</li><li>кількість гнізд;</li><li>піднутрення й рухомі елементи (повзуни, знаки);</li><li>тип ливникової системи;</li><li>вимоги до ресурсу, точності й поверхні.</li>"], ["p", "Проста форма виготовляється за кілька тижнів, складна багатогніздна — довше. Що підготувати до звернення, щоб розрахунок був точним, ми розписали в статті <a href=\"/blog/presforma-pid-vash-vyrib\" data-go=\"post\" data-a=\"4\">«Пресформа на замовлення»</a>."], ["h2", "Часті питання"], ["h3", "Чи можна виготовити пресформу за зразком без креслення?"], ["p", "Так. Ми виконаємо обмір, побудуємо 3D-модель і погодимо її з вами перед проєктуванням форми."], ["h3", "Чи робите ви ремонт пресформ?"], ["p", "Так, оцінюємо стан форми й пропонуємо ремонт або модернізацію. Детальніше — у статті <a href=\"/blog/remont-i-modernizatsiia-presform\" data-go=\"post\" data-a=\"16\">«Ремонт і модернізація пресформ»</a>."], ["h3", "Чи можна змінити виріб після виготовлення пресформи?"], ["p", "Частково: зміни, що зводяться до видалення металу, зазвичай можливі. Тому ключові рішення краще погодити на етапі проєктування."], ["h2", "Висновок"], ["p", "Пресформа на замовлення проходить п’ять етапів: аналіз, проєктування, виготовлення, пробне лиття й запуск. На кожному з них ви бачите результат і погоджуєте наступний крок. Залиште заявку нижче — і ми підготуємо розрахунок пресформи для вашого виробу."]], [["p", "The mold is the heart of any plastic product. Its design determines what every part costs, how good the surface and dimensions are and how many years the mold runs without repair. So when choosing a mold maker, it matters to understand not only the price but how the process is built."], ["p", "This article explains how we make custom molds — from the first drawing to the first series batch — and what you get at each stage. More about the service: <a href=\"/en/mold-making\" data-go=\"soon\" data-a=\"1\">Mold making</a>."], ["h2", "Stage 1. Part review and brief"], ["p", "Everything starts with a drawing, 3D model or sample. We review manufacturability: wall thickness, draft, undercuts, gate location, surface requirements. At this stage we often suggest small design changes that simplify the mold and reduce rejects."], ["p", "<b>You get:</b> a manufacturability review, recommendations and a quote with cost and timing."], ["h2", "Stage 2. Mold design"], ["p", "Engineers build a 3D model of the mold: cavity inserts, runner system, cooling, ejection and moving elements. The number of cavities is matched to your annual volume to balance mold cost and part price."], ["p", "<b>You get:</b> design approval before manufacturing — changes cost least at this stage."], ["h2", "Stage 3. Manufacturing"], ["p", "Mold parts are CNC machined, EDM-processed, ground and heat-treated. The mold is then assembled and moving elements and cooling channels are checked."], ["blockquote", "<p>Fixing a mistake on the drawing is cheapest, in steel it costs more, and in a finished batch it costs most. That is why the first two stages are not a formality for us.</p>"], ["h2", "Stage 4. Trial shots and tuning"], ["p", "The mold goes onto an injection molding machine and the first parts are molded. The process engineer sets the parameters, we measure samples and fine-tune the mold until the part matches the drawing."], ["p", "<b>You get:</b> trial samples to check dimensions, assembly and appearance."], ["h2", "Stage 5. Series or handover"], ["p", "After sample approval there are two options:"], ["ul", "<li>we start series molding on our equipment in Lviv and supply finished parts — <a href=\"/en/injection-molding\" data-go=\"soon\" data-a=\"0\">molding service</a>;</li><li>we hand the mold over for use at your plant.</li>"], ["p", "A mold paid for by the customer belongs to the customer."], ["cta", "{\"t\": \"Have a part that needs a new mold?\", \"d\": \"Send a drawing, 3D model or sample — we will quote the mold and molding.\", \"b\": [[\"Mold making\", \"srv1\", \"soon\", \"1\", \"/en/mold-making\"], [\"Send a drawing\", \"rfq\"]]}"], ["h2", "What drives cost and lead time"], ["ul", "<li>part size and complexity;</li><li>number of cavities;</li><li>undercuts and moving elements (slides, lifters);</li><li>runner type;</li><li>tool life, precision and surface requirements.</li>"], ["p", "A simple mold takes a few weeks; a complex multi-cavity tool takes longer. What to prepare for an accurate quote is covered in <a href=\"/en/blog/custom-mold-checklist\" data-go=\"post\" data-a=\"4\">“Custom mold”</a>."], ["h2", "FAQ"], ["h3", "Can you make a mold from a sample without drawings?"], ["p", "Yes. We measure the sample, build a 3D model and agree it with you before designing the mold."], ["h3", "Do you repair molds?"], ["p", "Yes, we assess the mold and propose repair or upgrade. See <a href=\"/en/blog/mold-repair-and-upgrade\" data-go=\"post\" data-a=\"16\">“Mold repair and upgrade”</a>."], ["h3", "Can the part be changed after the mold is made?"], ["p", "Partly: changes that mean removing steel are usually possible. Key decisions are best agreed at the design stage."], ["h2", "Conclusion"], ["p", "A custom mold goes through five stages: review, design, manufacturing, trial shots and launch. At each one you see the result and approve the next step. Leave a request below and we will quote a mold for your part."]]]}, {"id": 12, "st": "pub", "img": "/assets/img/blog/lyttia-plastyku-lviv.webp", "tag": ["Виробництво", "Production"], "date": "2026-04-14", "slug": {"uk": "lyttia-plastykovykh-vyrobiv-na-zamovlennia-lviv", "en": "custom-plastic-injection-molding-lviv"}, "t": ["Лиття пластикових виробів на замовлення у Львові: ціна, терміни та мінімальний тираж", "Custom plastic injection molding in Lviv: price, lead times and minimum run"], "e": ["Скільки коштує лиття пластику на замовлення, від чого залежать ціна й терміни, який мінімальний тираж і як отримати розрахунок на виробництві PLASTIZA у Львові.", "What custom plastic molding costs, what drives price and lead time, what the minimum run is and how to get a quote from the PLASTIZA plant in Lviv."], "b": [[["p", "Коли компанії потрібна партія пластикових деталей — корпусів, заглушок, кріплень, фіксаторів чи технічних виробів, — перше питання завжди однакове: скільки це коштуватиме і як швидко буде готово. Відповідь залежить від кількох чинників, і якщо їх знати заздалегідь, можна і зекономити, і уникнути затримок."], ["p", "У цій статті пояснюємо, як формується ціна лиття пластикових виробів на замовлення, які терміни реальні, з якого тиражу лиття вигідне і що потрібно, щоб отримати точний розрахунок на нашому виробництві у Львові. Про саму послугу — на сторінці <a href=\"/lyttia-plastyku\" data-go=\"soon\" data-a=\"0\">«Лиття пластикових виробів»</a>."], ["h2", "Що ми відливаємо"], ["p", "На власних термопластавтоматах PLASTIZA відливає вироби з термопластів для будівництва, промисловості й побутового призначення:"], ["ul", "<li>технічні деталі, кріплення, втулки, заглушки;</li><li>корпуси й кришки;</li><li>будівельні вироби — фіксатори арматури, елементи опалубки;</li><li>деталі за кресленнями замовника або за зразком.</li>"], ["p", "Ми працюємо як із власними пресформами, так і з формами замовника. Як проходить процес від креслення до серії, ми описали в статті <a href=\"/blog/lyttia-pid-tyskom\" data-go=\"post\" data-a=\"3\">«Лиття пластмас під тиском»</a>."], ["h2", "З чого складається ціна лиття"], ["p", "Ціна виробу складається з кількох частин:"], ["ul", "<li><b>Матеріал і маса деталі.</b> Що важча деталь і дорожчий пластик, то більша частка сировини в ціні.</li><li><b>Час циклу.</b> Товсті стінки довше охолоджуються, а отже займають більше машинного часу на кожну деталь.</li><li><b>Кількість гнізд у пресформі.</b> Чотиригніздна форма дає чотири деталі за цикл і знижує ціну одиниці.</li><li><b>Пресформа.</b> Якщо форми ще немає, її вартість розподіляється на тираж або оплачується окремо.</li><li><b>Додаткові операції:</b> складання, маркування, пакування за вашими вимогами.</li>"], ["blockquote", "<p>Для серійного виробу ціна деталі майже завжди падає зі зростанням тиражу: машинний час налагодження й вартість пресформи розподіляються на більшу кількість виробів.</p>"], ["h2", "Мінімальний тираж"], ["p", "Лиття під тиском найвигідніше від кількох тисяч деталей. Але мінімальний тираж залежить від виробу: для простих деталей у готовій пресформі партія може бути меншою, для нового виробу ми можемо почати з пробної партії, щоб ви перевірили деталь перед серією."], ["p", "Якщо обсяг поки невеликий, підкажемо, як спростити конструкцію пресформи, щоб старт коштував дешевше."], ["h2", "Терміни"], ["ul", "<li><b>Є пресформа, виріб уже випускався:</b> терміни залежать від обсягу партії й завантаження обладнання — фіксуємо їх у комерційній пропозиції.</li><li><b>Є ваша пресформа, але ми її ще не використовували:</b> перевірка форми, підбір режимів і пробне лиття займають кілька днів.</li><li><b>Пресформи немає:</b> найдовший етап — її проєктування й виготовлення, зазвичай кілька тижнів. Про це — в статті <a href=\"/blog/presforma-pid-vash-vyrib\" data-go=\"post\" data-a=\"4\">«Пресформа на замовлення»</a>.</li>"], ["cta", "{\"t\": \"Розрахуємо лиття вашого виробу\", \"d\": \"Надішліть креслення, 3D-модель або зразок — підготуємо ціну деталі, вартість пресформи та терміни.\", \"b\": [[\"Лиття пластикових виробів\", \"srv0\", \"soon\", \"0\", \"/lyttia-plastyku\"], [\"Надіслати креслення\", \"rfq\"]]}"], ["h2", "Як отримати точний розрахунок"], ["ol", "<li>Надішліть креслення або 3D-модель (STEP, IGES) чи фото зразка з розмірами.</li><li>Вкажіть матеріал або умови роботи деталі: навантаження, температура, вулиця чи приміщення.</li><li>Назвіть плановий обсяг — партію й річну потребу.</li><li>Додайте вимоги до кольору, поверхні та пакування.</li>"], ["p", "Менеджер у робочий час зв’яжеться з вами, уточнить деталі й підготує комерційну пропозицію."], ["h2", "Чому замовляють у PLASTIZA"], ["ul", "<li><b>Власне виробництво у Львові</b> — без посередників між вами й термопластавтоматом.</li><li><b>Повний цикл:</b> аналіз креслення, пресформа, пробне лиття, серія, пакування й доставка.</li><li><b>Досвід серійного випуску</b> будівельних фіксаторів, де важливі стабільні розміри кожної партії.</li><li><b>Пресформа належить замовнику</b> — ви не прив’язані до виробника.</li><li><b>Доставка по Україні</b> та документи для юридичних осіб.</li>"], ["p", "Детальніше про обладнання — на сторінці <a href=\"/vyrobnytstvo\" data-go=\"about\">«Виробництво»</a>."], ["h2", "Часті питання"], ["h3", "Скільки коштує лиття однієї деталі?"], ["p", "Однієї ціни немає: вона залежить від маси, матеріалу, часу циклу й тиражу. Точний розрахунок робимо за кресленням або зразком."], ["h3", "Чи можна замовити лиття без пресформи?"], ["p", "Пресформа потрібна для лиття під тиском. Якщо її немає, ми спроєктуємо й виготовимо її під ваш виріб."], ["h3", "Ви працюєте з клієнтами з інших міст?"], ["p", "Так, працюємо з усією Україною: креслення приймаємо онлайн, готову продукцію доставляємо службами доставки або перевізниками."], ["h2", "Висновок"], ["p", "Ціну лиття пластикових виробів визначають матеріал, час циклу, кількість гнізд, тираж і пресформа. Що більше даних ви надасте, то точніший розрахунок. Заповніть форму нижче — і ми підготуємо пропозицію на лиття вашого виробу у Львові."]], [["p", "When a company needs a batch of plastic parts — housings, caps, fasteners, spacers or technical components — the first question is always the same: how much will it cost and how soon will it be ready? The answer depends on a few factors, and knowing them in advance helps you save money and avoid delays."], ["p", "This article explains how the price of custom plastic molding is formed, which lead times are realistic, from what run size molding pays off and what we need to give you an exact quote at our Lviv plant. More about the service: <a href=\"/en/injection-molding\" data-go=\"soon\" data-a=\"0\">Plastic injection molding</a>."], ["h2", "What we mold"], ["p", "On our own injection molding machines PLASTIZA molds thermoplastic parts for construction, industry and consumer use:"], ["ul", "<li>technical parts, fasteners, bushings, caps;</li><li>housings and covers;</li><li>construction products — rebar spacers and formwork accessories;</li><li>parts to customer drawings or from a sample.</li>"], ["p", "We work with our own molds and with customer molds. The full path from drawing to series is described in <a href=\"/en/blog/injection-molding-process\" data-go=\"post\" data-a=\"3\">“Plastic injection molding”</a>."], ["h2", "What the price is made of"], ["ul", "<li><b>Material and part weight.</b> Heavier parts and dearer plastics mean a larger raw-material share.</li><li><b>Cycle time.</b> Thick walls cool longer and take more machine time per part.</li><li><b>Number of cavities.</b> A four-cavity mold makes four parts per cycle and lowers the unit price.</li><li><b>The mold.</b> If there is none yet, its cost is spread over the run or paid separately.</li><li><b>Secondary operations:</b> assembly, marking and packing to your requirements.</li>"], ["blockquote", "<p>For a series part, the unit price almost always falls as the run grows: setup time and mold cost are spread over more parts.</p>"], ["h2", "Minimum run"], ["p", "Injection molding pays off from several thousand parts. But the minimum depends on the part: simple parts in an existing mold can run in smaller batches, and for a new part we can start with a trial batch so you can test it before the series."], ["p", "If volumes are still small, we will suggest how to simplify the mold so the start costs less."], ["h2", "Lead times"], ["ul", "<li><b>The mold exists and the part has run before:</b> timing depends on batch size and machine load — fixed in the quote.</li><li><b>You have a mold we have not used yet:</b> mold check, process setup and trial shots take a few days.</li><li><b>No mold yet:</b> its design and manufacture is the longest stage, usually a few weeks. See <a href=\"/en/blog/custom-mold-checklist\" data-go=\"post\" data-a=\"4\">“Custom mold”</a>.</li>"], ["cta", "{\"t\": \"We will quote your part\", \"d\": \"Send a drawing, 3D model or sample — we will prepare the part price, mold cost and lead time.\", \"b\": [[\"Injection molding\", \"srv0\", \"soon\", \"0\", \"/en/injection-molding\"], [\"Send a drawing\", \"rfq\"]]}"], ["h2", "How to get an exact quote"], ["ol", "<li>Send a drawing or 3D model (STEP, IGES) or photos of a sample with dimensions.</li><li>State the material or the part’s operating conditions: load, temperature, indoor or outdoor.</li><li>Give the planned volume — batch size and annual demand.</li><li>Add colour, surface and packing requirements.</li>"], ["p", "A manager will contact you during working hours, clarify the details and send a quote."], ["h2", "Why customers choose PLASTIZA"], ["ul", "<li><b>Own production in Lviv</b> — no middlemen between you and the machine.</li><li><b>Full cycle:</b> drawing review, mold, trial shots, series, packing and delivery.</li><li><b>Series experience</b> with construction spacers, where stable dimensions in every batch matter.</li><li><b>The mold belongs to the customer</b> — you are not tied to the manufacturer.</li><li><b>Delivery across Ukraine</b> and full paperwork for businesses.</li>"], ["p", "More on our equipment: <a href=\"/en/production\" data-go=\"about\">Production</a>."], ["h2", "FAQ"], ["h3", "How much does one part cost?"], ["p", "There is no single price: it depends on weight, material, cycle time and run size. We quote from a drawing or sample."], ["h3", "Can you mold without a mold?"], ["p", "Injection molding needs a mold. If you do not have one, we will design and build it for your part."], ["h3", "Do you work with customers in other cities?"], ["p", "Yes, across Ukraine: we accept drawings online and deliver finished parts by courier or freight."], ["h2", "Conclusion"], ["p", "The price of molded plastic parts is set by material, cycle time, cavities, run size and the mold. The more data you provide, the more accurate the quote. Fill in the form below and we will prepare an offer for molding your part in Lviv."]]]}, {"id": 11, "st": "pub", "img": "/assets/img/blog/kontraktne-lyttia-plastyku.webp", "tag": ["Виробництво", "Production"], "date": "2026-03-10", "slug": {"uk": "kontraktne-lyttia-plastyku", "en": "contract-injection-molding-ukraine"}, "t": ["Контрактне лиття пластику в Україні: як обрати виробника і не переплатити", "Contract plastic injection molding in Ukraine: how to choose a manufacturer and not overpay"], "e": ["На що звернути увагу, обираючи виробника для лиття пластикових виробів на замовлення: обладнання, пресформи, матеріали, контроль якості, терміни та прихована вартість.", "What to check when choosing a contract manufacturer for custom plastic parts: equipment, molds, materials, quality control, lead times and hidden costs."], "b": [[["p", "Контрактне лиття пластику — це коли ви розробили виріб, а виготовлення доручаєте виробнику з власними термопластавтоматами. Так працюють і стартапи з першим продуктом, і великі компанії, яким невигідно тримати власний цех. Але від вибору виробника залежить усе: якість деталей, стабільність поставок, ціна партії і навіть те, чи залишиться у вас пресформа."], ["p", "У цій статті розповідаємо, як обрати виробника для лиття пластмас під тиском, які питання поставити на старті і де найчастіше ховається переплата. Як влаштований сам процес лиття, ми описали в статті <a href=\"/blog/lyttia-pid-tyskom\" data-go=\"post\" data-a=\"3\">«Лиття пластмас під тиском»</a>."], ["h2", "Що таке контрактне лиття і кому воно потрібне"], ["p", "Контрактний виробник бере на себе виготовлення пластикових виробів за вашими кресленнями: від підбору матеріалу й пресформи до серійних партій, пакування та доставки. Замовник зосереджується на розробці, продажах і логістиці, а не на обладнанні й технологах."], ["p", "Такий формат підходить, якщо:"], ["ul", "<li>у вас новий виріб і немає власного виробництва;</li><li>обсяги не виправдовують купівлю термопластавтоматів;</li><li>потрібно швидко запустити серію без капіталовкладень;</li><li>треба розвантажити власний цех у пікові сезони.</li>"], ["h2", "На що звернути увагу при виборі виробника"], ["h3", "Обладнання"], ["p", "Запитайте, на яких машинах відливатимуть ваш виріб: зусилля змикання, об’єм упорскування, вік обладнання. Від цього залежить, чи підходить виробник для ваших розмірів і маси деталі та наскільки стабільним буде процес."], ["h3", "Пресформи: виготовлення і власність"], ["p", "Уточніть, чи виробник проєктує й виготовляє пресформи сам, хто є власником форми після оплати і чи можна її забрати. Чесна модель — пресформа, оплачена замовником, належить замовнику. Про те, що впливає на вартість форми, ми розповідали в статті <a href=\"/blog/presforma-pid-vash-vyrib\" data-go=\"post\" data-a=\"4\">«Пресформа на замовлення»</a>, а про послугу — на сторінці <a href=\"/vyhotovlennia-presform\" data-go=\"soon\" data-a=\"1\">«Виготовлення пресформ»</a>."], ["h3", "Матеріали"], ["p", "Хороший виробник допомагає підібрати пластик під умови роботи виробу — PP, PE, ABS, поліамід тощо — і пояснює, як вибір матеріалу вплине на ціну та довговічність."], ["h3", "Контроль якості"], ["p", "Запитайте, як погоджуються зразки, як контролюються розміри під час серії і що відбувається з бракованими виробами."], ["h3", "Терміни й логістика"], ["p", "Важливі не лише терміни першої партії, а й стабільність наступних. Уточніть, чи є склад готової продукції й доставка по Україні."], ["blockquote", "<p>Найдешевша ціна за деталь не завжди означає найдешевший проєкт. Переплата часто ховається в пресформі, браку й зірваних термінах.</p>"], ["h2", "Де ховається переплата"], ["ul", "<li><b>Дешева пресформа з малим ресурсом</b> — доводиться ремонтувати або виготовляти нову вже на другому тиражі.</li><li><b>Неоптимальна кількість гнізд</b> — або переплата за форму, або висока ціна деталі.</li><li><b>Відсутність аналізу технологічності</b> — дефекти й доопрацювання форми після запуску.</li><li><b>Пресформа, яку не можна забрати</b> — ви прив’язані до одного виробника.</li><li><b>Нестабільна якість партій</b> — витрати на сортування й повернення.</li>"], ["cta", "{\"t\": \"Запустимо ваш виріб у виробництво\", \"d\": \"Повний цикл у Львові: аналіз креслення, пресформа, пробне лиття, серійні партії й доставка.\", \"b\": [[\"Лиття пластикових виробів\", \"srv0\", \"soon\", \"0\", \"/lyttia-plastyku\"], [\"Виготовлення пресформ\", \"srv1\", \"soon\", \"1\", \"/vyhotovlennia-presform\"], [\"Надіслати креслення\", \"rfq\"]]}"], ["h2", "Як проходить співпраця з PLASTIZA"], ["ol", "<li>Ви надсилаєте креслення, 3D-модель або зразок.</li><li>Ми аналізуємо технологічність, пропонуємо матеріал і готуємо комерційну пропозицію з вартістю пресформи та лиття.</li><li>Проєктуємо й виготовляємо пресформу або перевіряємо вашу.</li><li>Робимо пробне лиття й погоджуємо зразки.</li><li>Запускаємо серію, пакуємо й доставляємо по Україні.</li>"], ["p", "Наше виробництво у Львові — це власні термопластавтомати й досвід серійного випуску будівельних фіксаторів. Детальніше — на сторінці <a href=\"/vyrobnytstvo\" data-go=\"about\">«Виробництво»</a>."], ["h2", "Часті питання"], ["h3", "Який мінімальний тираж для контрактного лиття?"], ["p", "Залежить від виробу й пресформи. Лиття під тиском найвигідніше від кількох тисяч деталей, але можна почати з пробної партії."], ["h3", "Чи можна перенести виробництво з іншого заводу?"], ["p", "Так. Ми перевіримо вашу пресформу, підберемо обладнання й режими та виготовимо пробну партію."], ["h3", "Скільки часу займає запуск нового виробу?"], ["p", "Найдовший етап — виготовлення пресформи. Після неї пробне лиття й погодження займають від кількох днів."], ["h2", "Висновок"], ["p", "Обираючи виробника для контрактного лиття пластику, дивіться не лише на ціну деталі, а й на обладнання, власність і ресурс пресформи, контроль якості та стабільність поставок. Надішліть нам креслення чи зразок — підготуємо розрахунок вартості й термінів."]], [["p", "Contract plastic molding means you design the part and a manufacturer with its own injection molding machines produces it. Start-ups with a first product work this way, and so do large companies that do not want to run their own shop. But the choice of manufacturer decides everything: part quality, supply stability, batch price and even whether you keep your mold."], ["p", "This article explains how to choose an injection molding manufacturer, which questions to ask up front and where overpayment usually hides. How the process itself works is covered in <a href=\"/en/blog/injection-molding-process\" data-go=\"post\" data-a=\"3\">“Plastic injection molding”</a>."], ["h2", "What contract molding is and who needs it"], ["p", "A contract manufacturer produces plastic parts to your drawings — from material and mold selection to series batches, packing and delivery. You focus on design, sales and logistics, not on machines and process engineers."], ["p", "This model suits you if:"], ["ul", "<li>you have a new product and no production of your own;</li><li>volumes do not justify buying injection molding machines;</li><li>you need to launch a series quickly without capital investment;</li><li>your own shop needs relief in peak seasons.</li>"], ["h2", "What to check when choosing a manufacturer"], ["h3", "Equipment"], ["p", "Ask which machines will mold your part: clamping force, shot volume, machine age. This determines whether the manufacturer can handle your part size and weight and how stable the process will be."], ["h3", "Molds: making and ownership"], ["p", "Check whether the manufacturer designs and builds molds in-house, who owns the mold once paid for and whether you can take it away. The fair model: a mold paid for by the client belongs to the client. What drives mold cost is covered in <a href=\"/en/blog/custom-mold-checklist\" data-go=\"post\" data-a=\"4\">“Custom mold”</a>, and the service on <a href=\"/en/mold-making\" data-go=\"soon\" data-a=\"1\">Mold making</a>."], ["h3", "Materials"], ["p", "A good manufacturer helps choose the plastic for the part’s operating conditions — PP, PE, ABS, polyamide and others — and explains how the choice affects price and durability."], ["h3", "Quality control"], ["p", "Ask how samples are approved, how dimensions are controlled during the run and what happens to rejects."], ["h3", "Lead times and logistics"], ["p", "Not only the first batch date matters but the stability of the following ones. Check whether there is a finished-goods warehouse and delivery across Ukraine."], ["blockquote", "<p>The lowest price per part is not always the cheapest project. Overpayment often hides in the mold, rejects and missed deadlines.</p>"], ["h2", "Where overpayment hides"], ["ul", "<li><b>A cheap mold with short tool life</b> — it needs repair or replacement by the second run.</li><li><b>The wrong number of cavities</b> — either overpaying for the mold or a high part price.</li><li><b>No manufacturability review</b> — defects and mold rework after launch.</li><li><b>A mold you cannot take away</b> — you are tied to one manufacturer.</li><li><b>Unstable batch quality</b> — sorting and return costs.</li>"], ["cta", "{\"t\": \"We will put your part into production\", \"d\": \"Full cycle in Lviv: drawing review, mold, trial shots, series batches and delivery.\", \"b\": [[\"Injection molding\", \"srv0\", \"soon\", \"0\", \"/en/injection-molding\"], [\"Mold making\", \"srv1\", \"soon\", \"1\", \"/en/mold-making\"], [\"Send a drawing\", \"rfq\"]]}"], ["h2", "How working with PLASTIZA goes"], ["ol", "<li>You send a drawing, 3D model or sample.</li><li>We review manufacturability, suggest a material and prepare a quote for the mold and molding.</li><li>We design and build the mold, or check yours.</li><li>We run trial shots and approve samples.</li><li>We start the series, pack and deliver across Ukraine.</li>"], ["p", "Our Lviv plant has its own injection molding machines and experience in series production of construction spacers. More on <a href=\"/en/production\" data-go=\"about\">Production</a>."], ["h2", "FAQ"], ["h3", "What is the minimum run for contract molding?"], ["p", "It depends on the part and mold. Injection molding pays off from several thousand parts, but you can start with a trial batch."], ["h3", "Can production be transferred from another plant?"], ["p", "Yes. We check your mold, choose the machine and settings and produce a trial batch."], ["h3", "How long does a new part take to launch?"], ["p", "Mold making is the longest stage. After it, trials and approval take from a few days."], ["h2", "Conclusion"], ["p", "When choosing a contract molding manufacturer, look beyond the part price: equipment, mold ownership and tool life, quality control and supply stability. Send us a drawing or sample for a price and lead-time estimate."]]]}, {"id": 9, "st": "pub", "img": "/assets/img/blog/rozrakhunok-fiksatoriv.webp", "tag": ["Поради", "Guides"], "date": "2026-01-20", "slug": {"uk": "yak-rozrakhuvaty-kilkist-fiksatoriv", "en": "how-to-calculate-rebar-spacers"}, "t": ["Як розрахувати кількість фіксаторів арматури на об’єкт: формули та приклади", "How to calculate the number of rebar spacers for a project: formulas and examples"], "e": ["Покрокова методика розрахунку фіксаторів арматури для плит, фундаментів, стін і колон: витрата на м², крок установки, запас і приклад розрахунку для приватного будинку.", "A step-by-step method for calculating rebar spacers for slabs, foundations, walls and columns: consumption per m², spacing, reserve and a worked example for a private house."], "b": [[["p", "Фіксатори арматури коштують недорого, але їхня нестача на майданчику коштує дорого: бригада простоює, каркас кладуть на цеглу, а захисний шар порушується. Надлишок — теж зайві гроші й залишки на складі. Тому кількість фіксаторів краще порахувати заздалегідь, разом із кошторисом на арматуру й бетон."], ["p", "У цій статті даємо просту методику розрахунку фіксаторів для різних конструкцій і приклад для приватного будинку. Тип фіксатора під кожну конструкцію ми розбирали в статті <a href=\"/blog/yak-obraty-fiksator-armatury\" data-go=\"post\" data-a=\"1\">«Як обрати фіксатор арматури»</a>."], ["h2", "Від чого залежить кількість фіксаторів"], ["ul", "<li><b>Тип конструкції:</b> плити, фундаменти, стіни, колони, балки.</li><li><b>Діаметр і крок арматури:</b> тонкі стрижні прогинаються між опорами, тому потребують частішого кроку.</li><li><b>Навантаження під час робіт:</b> ходіння, тачки, рукав бетононасоса.</li><li><b>Основа:</b> на сипкій основі опори ставлять частіше.</li><li><b>Конфігурація:</b> кути, отвори, нахлести й зони додаткового армування потребують додаткових фіксаторів.</li>"], ["h2", "Базові норми витрати"], ["p", "Ці значення — практичний орієнтир, на який спираються більшість будівельників:"], ["ul", "<li>плити перекриття та фундаментні плити (нижня сітка) — 4–6 шт. на м²;</li><li>стіни й пілони — 1–2 шт. на м² з кожного боку стіни;</li><li>колони — 3–4 фіксатори на кожну грань на кожні 3 м висоти;</li><li>балки й ригелі — фіксатор знизу кожні 0,8–1 м плюс бічні «Зірочки».</li>"], ["blockquote", "<p>Норма на м² — це середнє значення. Остаточну кількість завжди коригують під діаметр арматури й конфігурацію конструкції.</p>"], ["h2", "Формули розрахунку"], ["h3", "Плити й фундаменти"], ["p", "Кількість = площа плити (м²) × норма (шт./м²) × 1,1"], ["p", "Множник 1,1 — запас 10 % на втрати, підрізку й додаткові опори біля отворів."], ["h3", "Стіни"], ["p", "Кількість = площа стіни (м²) × 2 сторони × норма (шт./м²) × 1,1"], ["h3", "Колони"], ["p", "Кількість = кількість граней × кількість ярусів по висоті × кількість колон × 1,1"], ["h3", "Через крок установки"], ["p", "Якщо в проєкті вказано крок фіксаторів, рахуйте точніше: кількість = (довжина / крок + 1) × (ширина / крок + 1)."], ["h2", "Приклад розрахунку для приватного будинку"], ["p", "Будинок із фундаментною плитою 12×10 м, монолітними стінами підвалу і перекриттям:"], ["ol", "<li><b>Фундаментна плита 120 м²</b>, норма 5 шт./м²: 120 × 5 × 1,1 = 660 фіксаторів <a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">«Настил»</a>.</li><li><b>Стіни підвалу:</b> периметр 44 м, висота 2,7 м — площа 119 м². З двох боків при нормі 1,5 шт./м²: 119 × 2 × 1,5 × 1,1 ≈ 393 <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">«Зірочки»</a>.</li><li><b>Перекриття 110 м²</b>, норма 5 шт./м²: 110 × 5 × 1,1 = 605 <a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">«Стійок»</a>.</li><li><b>Торці плит:</b> периметр плити й перекриття — по 44 м, з кроком 1 м — близько 90 «Зірочок».</li>"], ["p", "Разом: 660 «Настилів», 605 «Стійок» і близько 480 «Зірочок». Фіксатори постачаються упаковками, тому результат округлюють до цілих упаковок — точне фасування є в картці кожного товару."], ["cta", "{\"t\": \"Порахуємо фіксатори за вашим проєктом\", \"d\": \"Надішліть креслення або специфікацію — підготуємо точний розрахунок за типами й розмірами та ціну з доставкою.\", \"b\": [[\"Каталог фіксаторів\", \"cat_rebar\", \"catalog\", \"rebar\", \"/fiksatory-armatury\"], [\"Надіслати креслення\", \"rfq\"]]}"], ["h2", "Розрахунок елементів для опалубки"], ["p", "Якщо стіни бетонують у щитовій опалубці зі стяжними гвинтами, окремо рахують:"], ["ul", "<li><a href=\"/dystantsiina-truba\" data-go=\"product\" data-a=\"9-0\">дистанційну трубу</a> — у метрах: кількість точок стяжки × товщина стіни;</li><li><a href=\"/fiksator-konus\" data-go=\"product\" data-a=\"6-0\">конуси</a> — по два на кожну точку стяжки;</li><li><a href=\"/fiksator-korok\" data-go=\"product\" data-a=\"8-0\">корки</a> — по два на кожну точку, плюс <a href=\"/korok-yalynka\" data-go=\"product\" data-a=\"7-0\">корки-ялинки</a> для невикористаних отворів щитів.</li>"], ["p", "Як працює кожен елемент, ми пояснили в статті <a href=\"/blog/korky-i-konusy-dlia-opalubky\" data-go=\"post\" data-a=\"5\">«Конуси, корки й дистанційні труби для опалубки»</a>."], ["h2", "Типові помилки в розрахунку"], ["ul", "<li>Рахують лише площу плит і забувають про стіни, колони й торці.</li><li>Не закладають запас — і докуповують фіксатори вже під час робіт.</li><li>Беруть одну висоту на весь об’єкт, хоча захисний шар фундаменту й перекриття різний.</li><li>Не враховують, що труба для опалубки продається метрами, а не штуками.</li>"], ["h2", "Часті питання"], ["h3", "Чи можна порахувати фіксатори без креслень?"], ["p", "Орієнтовно — так, за площею плит і стін за нормами вище. Але для точної специфікації за розмірами краще мати креслення."], ["h3", "Скільки фіксаторів потрібно на 1 м² плити?"], ["p", "У середньому 4–6 шт. для нижньої сітки — менше для товстої арматури, більше для тонкої."], ["h3", "Ви можете зробити розрахунок за нас?"], ["p", "Так. Надішліть креслення або кошторис — менеджер підготує специфікацію з типами, розмірами й кількістю фіксаторів."], ["h2", "Висновок"], ["p", "Кількість фіксаторів рахують за площею конструкцій і нормою витрати з урахуванням діаметра арматури та запасу 10 %. Для плит — 4–6 шт./м², для стін — 1–2 шт./м² з кожного боку, для колон — 3–4 на грань на ярус. Надішліть нам проєкт — підготуємо точний розрахунок і комерційну пропозицію."]], [["p", "Rebar spacers are cheap, but running out on site is expensive: the crew waits, the cage goes onto bricks and cover is lost. Too many is wasted money and leftover stock. It pays to calculate spacers in advance, together with the rebar and concrete estimate."], ["p", "This article gives a simple method for different elements and a worked example for a private house. Spacer types for each element are covered in <a href=\"/en/blog/how-to-choose-rebar-spacer\" data-go=\"post\" data-a=\"1\">“How to choose a rebar spacer”</a>."], ["h2", "What the quantity depends on"], ["ul", "<li><b>Element type:</b> slabs, foundations, walls, columns, beams.</li><li><b>Bar diameter and spacing:</b> thin bars sag between supports and need closer spacing.</li><li><b>Site loads:</b> foot traffic, barrows, the pump hose.</li><li><b>Base:</b> loose bases need more supports.</li><li><b>Geometry:</b> corners, openings, laps and extra-reinforcement zones need extra spacers.</li>"], ["h2", "Basic consumption rates"], ["p", "These practical guide values are what most builders use:"], ["ul", "<li>floor slabs and raft foundations (bottom mesh) — 4–6 pcs per m²;</li><li>walls and piers — 1–2 pcs per m² per face;</li><li>columns — 3–4 spacers per face for every 3 m of height;</li><li>beams — a chair every 0.8–1 m plus side “Zirochka” spacers.</li>"], ["blockquote", "<p>A per-m² rate is an average. Always adjust the final number for bar diameter and geometry.</p>"], ["h2", "Formulas"], ["h3", "Slabs and foundations"], ["p", "Quantity = slab area (m²) × rate (pcs/m²) × 1.1"], ["p", "The 1.1 factor is a 10 % reserve for losses, trimming and extra supports at openings."], ["h3", "Walls"], ["p", "Quantity = wall area (m²) × 2 faces × rate (pcs/m²) × 1.1"], ["h3", "Columns"], ["p", "Quantity = faces × levels over height × number of columns × 1.1"], ["h3", "From a given spacing"], ["p", "If the design specifies spacing, calculate more precisely: quantity = (length / spacing + 1) × (width / spacing + 1)."], ["h2", "Worked example: a private house"], ["p", "A house with a 12×10 m raft, cast basement walls and a floor slab:"], ["ol", "<li><b>Raft 120 m²</b> at 5 pcs/m²: 120 × 5 × 1.1 = 660 <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil”</a> spacers.</li><li><b>Basement walls:</b> 44 m perimeter, 2.7 m high — 119 m². Two faces at 1.5 pcs/m²: 119 × 2 × 1.5 × 1.1 ≈ 393 <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka”</a> spacers.</li><li><b>Floor slab 110 m²</b> at 5 pcs/m²: 110 × 5 × 1.1 = 605 <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika”</a> chairs.</li><li><b>Slab edges:</b> 44 m perimeter each for raft and slab at 1 m spacing — about 90 “Zirochka”.</li>"], ["p", "Total: 660 “Nastil”, 605 “Stiika” and about 480 “Zirochka”. Spacers ship in packs, so round up to whole packs — pack sizes are on each product page."], ["cta", "{\"t\": \"We will calculate spacers from your design\", \"d\": \"Send a drawing or schedule — we will prepare an exact list by type and size, with prices and delivery.\", \"b\": [[\"Spacer catalog\", \"cat_rebar\", \"catalog\", \"rebar\", \"/en/rebar-spacers\"], [\"Send a drawing\", \"rfq\"]]}"], ["h2", "Formwork accessories"], ["p", "If walls are cast in panel formwork with tie rods, calculate separately:"], ["ul", "<li><a href=\"/en/spacer-tube\" data-go=\"product\" data-a=\"9-0\">spacer tube</a> — in metres: tie points × wall thickness;</li><li><a href=\"/en/cone-spacer-konus\" data-go=\"product\" data-a=\"6-0\">cones</a> — two per tie point;</li><li><a href=\"/en/formwork-plug-korok\" data-go=\"product\" data-a=\"8-0\">plugs</a> — two per tie point, plus <a href=\"/en/fir-tree-plug\" data-go=\"product\" data-a=\"7-0\">fir-tree plugs</a> for unused panel holes.</li>"], ["p", "How each part works is explained in <a href=\"/en/blog/formwork-plugs-and-cones\" data-go=\"post\" data-a=\"5\">“Formwork cones, plugs and spacer tubes”</a>."], ["h2", "Common mistakes"], ["ul", "<li>Counting only slab areas and forgetting walls, columns and edges.</li><li>No reserve — and buying more spacers mid-job.</li><li>One height for the whole project, although foundation and slab cover differ.</li><li>Forgetting that formwork tube is sold by the metre, not by the piece.</li>"], ["h2", "FAQ"], ["h3", "Can spacers be calculated without drawings?"], ["p", "Roughly, yes — from slab and wall areas using the rates above. An exact size-by-size list needs drawings."], ["h3", "How many spacers per m² of slab?"], ["p", "On average 4–6 pcs for the bottom mesh — fewer for heavy bars, more for thin ones."], ["h3", "Can you do the calculation for us?"], ["p", "Yes. Send drawings or a bill of quantities and a manager will prepare a list of spacer types, sizes and quantities."], ["h2", "Conclusion"], ["p", "Spacer quantity is calculated from element areas and consumption rates, adjusted for bar diameter with a 10 % reserve: 4–6 pcs/m² for slabs, 1–2 pcs/m² per face for walls, 3–4 per face per level for columns. Send us your design for an exact calculation and quote."]]]}, {"id": 8, "st": "pub", "img": "/assets/img/blog/fiksator-zirochka-stiny.webp", "tag": ["Поради", "Guides"], "date": "2025-11-25", "slug": {"uk": "fiksator-zirochka-dlia-stin-i-kolon", "en": "zirochka-wheel-spacer-walls-columns"}, "t": ["Фіксатор «Зірочка» для стін і колон: розміри, монтаж і крок установки", "“Zirochka” wheel spacer for walls and columns: sizes, installation and spacing"], "e": ["Як працює фіксатор «Зірочка», як підібрати розмір під захисний шар і діаметр арматури, як правильно встановити його на стінах і колонах і скільки штук потрібно.", "How the “Zirochka” wheel spacer works, how to choose its size for cover and bar diameter, how to fit it on walls and columns and how many you need."], "b": [[["p", "Стіни, колони й пілони бетонують у вертикальній опалубці, і тут фіксатори працюють інакше, ніж у плитах. Арматурний каркас треба втримати на однаковій відстані від щитів з обох боків, а під час монтажу опалубки нічого не повинно чіплятися й зсуватися. Для цього використовують кільцеві фіксатори — у нашому асортименті це <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">фіксатор «Зірочка»</a>."], ["p", "У статті розповідаємо, як влаштована «Зірочка», як підібрати її розмір, як правильно встановити й скільки штук закласти на стіну чи колону."], ["h2", "Як працює фіксатор «Зірочка»"], ["p", "«Зірочка» — це кільце з променями, яке надягається на вертикальний або горизонтальний стрижень. Його зовнішній край впирається в щит опалубки по колу, тому захисний шар однаковий незалежно від того, як повернувся фіксатор. Під час закриття опалубки «колесо» прокочується по щиту, а не чіпляється за нього."], ["p", "Еластичний замок у центрі охоплює стрижні різних діаметрів у межах типорозміру й тримається на арматурі без в’язального дроту."], ["blockquote", "<p>Перевага кільцевого фіксатора в тому, що він дає однаковий шар у будь-якому положенні: його не треба орієнтувати, він просто котиться разом зі щитом.</p>"], ["h2", "Розміри «Зірочки» і як їх читати"], ["p", "Позначення розміру складається з двох частин: перше число — захисний шар у міліметрах, далі — діапазон діаметрів арматури. Наприклад, 25/6-12 означає шар 25 мм для стрижнів від 6 до 12 мм. У нашому асортименті:"], ["ul", "<li>15/6-12 — для тонких стін і перегородок;</li><li>25/6-12 і 25/4-20 — найпоширеніші розміри для стін і колон;</li><li>30/8-20 і 35/6-12 — для збільшеного захисного шару;</li><li>40/14-20 і 50/12-20 — для фундаментних стін, ростверків і масивних конструкцій.</li>"], ["p", "Щоб обрати розмір, візьміть із проєкту захисний шар і діаметр стрижня, на який буде встановлено фіксатор. Пам’ятайте: шар відраховують до найближчого стрижня — часто це горизонтальна арматура або хомути, а не вертикальні стрижні."], ["h2", "Як правильно встановити «Зірочку»"], ["ol", "<li>Встановлюйте фіксатори після в’язання каркаса, але до монтажу другого щита опалубки.</li><li>Надягайте «Зірочку» на стрижень, найближчий до щита, так щоб площина кільця була перпендикулярна до опалубки.</li><li>На стінах розташовуйте фіксатори в шаховому порядку з обох боків каркаса.</li><li>На колонах ставте фіксатори на кожну грань — щонайменше по одному на грань у кожному ярусі.</li><li>Біля кутів, отворів, закладних деталей і в місцях стиків каркаса додайте фіксатори.</li>"], ["cta", "{\"t\": \"Потрібні «Зірочки» на стіни чи колони?\", \"d\": \"Підберемо розміри під ваш захисний шар і діаметри, порахуємо кількість і відвантажимо зі складу.\", \"b\": [[\"Фіксатор «Зірочка»\", \"p3\", \"product\", \"3-0\", \"/fiksator-zirochka\"], [\"Запросити розрахунок\", \"rfq\"]]}"], ["h2", "Крок установки й кількість"], ["p", "Орієнтовний крок — близько 1 м по висоті й довжині стіни з кожного боку, у шаховому порядку. Для тонкої арматури й високих стін крок зменшують до 0,6–0,8 м. Отже, на 1 м² стіни припадає приблизно 1–2 фіксатори з кожного боку."], ["p", "Приклад: стіна завдовжки 10 м і заввишки 3 м має площу 30 м² з кожного боку. При кроці 1 м це близько 30–40 фіксаторів на сторону, тобто 60–80 на стіну, плюс 10 % запасу. Для колони перерізом 400×400 мм і висотою 3 м — по 3–4 фіксатори на кожну грань, разом 12–16 шт."], ["p", "Детальну методику розрахунку для всього об’єкта ми розібрали в статті <a href=\"/blog/yak-rozrakhuvaty-kilkist-fiksatoriv\" data-go=\"post\" data-a=\"9\">«Як розрахувати кількість фіксаторів»</a>."], ["h2", "«Зірочка» в горизонтальних конструкціях"], ["p", "Кільцеві фіксатори використовують не лише на вертикальних каркасах. Їх ставлять на крайні стрижні плит і балок біля бортової опалубки, на арматуру ростверків і на бічні грані фундаментних плит. А для нижньої сітки плит краще підходять опорні фіксатори — <a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">«Стійка»</a> або <a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">«Настил»</a>."], ["h2", "Типові помилки"], ["ul", "<li>«Зірочку» обирають не під той діаметр — вона сповзає зі стрижня або не надягається.</li><li>Фіксатори ставлять лише з одного боку стіни.</li><li>Встановлюють на вертикальний стрижень, хоча ближче до щита розташована горизонтальна арматура — і шар виходить меншим.</li><li>Не додають фіксатори біля отворів і кутів.</li>"], ["h2", "Часті питання"], ["h3", "Чи можна використовувати «Зірочку» на горизонтальній арматурі?"], ["p", "Так. Її ставлять на крайні стрижні плит і балок біля бортової опалубки, а також на горизонтальні стрижні стін."], ["h3", "Чи не зламається «Зірочка» під час монтажу опалубки?"], ["p", "Кільце прокочується по щиту й розраховане на такі навантаження. Важливо не тягнути щит уздовж каркаса з великим зусиллям."], ["h3", "Скільки «Зірочок» в упаковці?"], ["p", "Залежно від розміру — від кількох сотень до тисяч штук. Точне фасування вказане в картці товару."], ["h2", "Висновок"], ["p", "«Зірочка» — основний фіксатор для стін, колон і пілонів: вона дає однаковий захисний шар з усіх боків і не чіпляється за опалубку. Підберіть розмір за проєктним шаром і діаметром стрижня, ставте фіксатори в шаховому порядку з кроком близько 1 м і не забувайте про кути й отвори. Залиште заявку — і ми підготуємо розрахунок."]], [["p", "Walls, columns and piers are cast in vertical formwork, and spacers work differently here than in slabs. The cage must stay at equal distance from the panels on both sides, and nothing should snag or shift while the formwork is closed. That is the job of wheel spacers — in our range, the <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka” spacer</a>."], ["p", "This article explains how “Zirochka” works, how to choose its size, how to install it and how many to order for a wall or column."], ["h2", "How “Zirochka” works"], ["p", "“Zirochka” is a ring with spokes that clips onto a vertical or horizontal bar. Its outer rim bears against the formwork all around, so cover stays equal however the spacer turns. When the panel is closed, the wheel rolls along it instead of catching."], ["p", "A flexible lock in the centre grips bars of different diameters within its size range and holds without tie wire."], ["blockquote", "<p>A wheel spacer gives the same cover in any position: no orientation needed — it simply rolls with the panel.</p>"], ["h2", "Sizes and how to read them"], ["p", "The size has two parts: the first number is cover in millimetres, followed by the bar diameter range. For example, 25/6-12 means 25 mm cover for 6–12 mm bars. Our range includes:"], ["ul", "<li>15/6-12 — thin walls and partitions;</li><li>25/6-12 and 25/4-20 — the most common sizes for walls and columns;</li><li>30/8-20 and 35/6-12 — increased cover;</li><li>40/14-20 and 50/12-20 — basement walls, pile caps and massive elements.</li>"], ["p", "Choose by the design cover and the diameter of the bar the spacer sits on. Remember that cover is measured to the nearest bar — often horizontal bars or links rather than vertical bars."], ["h2", "How to install “Zirochka”"], ["ol", "<li>Fit spacers after the cage is tied but before the second formwork panel is closed.</li><li>Clip each spacer onto the bar nearest the panel, with the ring perpendicular to the formwork.</li><li>On walls, place spacers in a staggered pattern on both faces.</li><li>On columns, fit at least one spacer per face at each level.</li><li>Add spacers at corners, openings, embedded items and cage joints.</li>"], ["cta", "{\"t\": \"Need “Zirochka” spacers for walls or columns?\", \"d\": \"We will choose sizes for your cover and bar diameters, calculate quantities and ship from stock.\", \"b\": [[\"“Zirochka” spacer\", \"p3\", \"product\", \"3-0\", \"/en/star-spacer-zirochka\"], [\"Request a quote\", \"rfq\"]]}"], ["h2", "Spacing and quantity"], ["p", "A typical spacing is about 1 m vertically and horizontally on each face, staggered. For thin bars and tall walls reduce it to 0.6–0.8 m. That gives roughly 1–2 spacers per m² per face."], ["p", "Example: a wall 10 m long and 3 m high has 30 m² per face. At 1 m spacing that is about 30–40 spacers per face, 60–80 per wall, plus 10 % reserve. A 400×400 mm column 3 m high needs 3–4 spacers per face — 12–16 in total."], ["p", "See <a href=\"/en/blog/how-to-calculate-rebar-spacers\" data-go=\"post\" data-a=\"9\">“How to calculate rebar spacers”</a> for a whole-project method."], ["h2", "“Zirochka” in horizontal elements"], ["p", "Wheel spacers are not only for vertical cages. They go on the edge bars of slabs and beams next to edge formwork, on pile-cap reinforcement and on raft side faces. For the bottom mesh of slabs, use chairs — <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika”</a> or <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil”</a>."], ["h2", "Common mistakes"], ["ul", "<li>Choosing a size for the wrong diameter — it slides off or will not fit.</li><li>Fitting spacers on one face of the wall only.</li><li>Fitting on vertical bars when horizontal bars are closer to the panel — so cover comes out smaller.</li><li>Skipping spacers at openings and corners.</li>"], ["h2", "FAQ"], ["h3", "Can “Zirochka” go on horizontal bars?"], ["p", "Yes — on the outer bars of slabs and beams next to edge formwork, and on the horizontal bars of walls."], ["h3", "Will it break when the formwork is closed?"], ["p", "The ring rolls along the panel and is designed for this. Just avoid dragging the panel along the cage with excessive force."], ["h3", "How many come in a pack?"], ["p", "Depending on size, from several hundred to several thousand. The exact pack is on the product page."], ["h2", "Conclusion"], ["p", "“Zirochka” is the main spacer for walls, columns and piers: it gives equal cover on all sides and does not snag the formwork. Choose the size by design cover and bar diameter, place spacers staggered at about 1 m and remember corners and openings. Leave a request and we will prepare a quote."]]]}, {"id": 7, "st": "pub", "img": "/assets/img/blog/armuvannia-perekryttia.webp", "tag": ["Будівництво", "Construction"], "date": "2025-10-21", "slug": {"uk": "armuvannia-monolitnoho-perekryttia", "en": "floor-slab-reinforcement-cover"}, "t": ["Армування монолітного перекриття: як витримати захисний шар і не зіпсувати каркас", "Reinforcing a cast-in-place floor slab: keeping concrete cover and protecting the cage"], "e": ["Як забезпечити проєктний захисний шар у плиті перекриття: які фіксатори обрати для нижньої сітки на опалубці, як закріпити каркас і чого уникати під час бетонування.", "How to achieve design cover in a floor slab: which spacers to use for the bottom mesh on formwork, how to secure the cage and what to avoid during the pour."], "b": [[["p", "Монолітне перекриття — це тонка плита, в якій кожен міліметр має значення. Товщина перекриття зазвичай 160–220 мм, а захисний шар нижньої арматури — лише 15–25 мм. Якщо сітка опуститься до опалубки, після розпалублення на стелі проступлять іржаві смуги, а вогнестійкість перекриття знизиться. Якщо ж сітка підніметься вище проєкту, зменшиться робоча висота перерізу й несна здатність плити."], ["p", "У цій статті розповідаємо, які фіксатори арматури використовують для перекриттів, як їх розставляти на опалубці та як зберегти каркас під час бетонування."], ["h2", "Особливості захисного шару в перекриттях"], ["p", "Нижня арматура перекриття працює на розтяг і найбільше впливає на несну здатність. Захисний шар тут відносно тонкий: для внутрішніх приміщень — орієнтовно 15–25 мм, для вологих приміщень і перекриттів над паркінгами — більше. Значення для вашого об’єкта беруть із проєкту."], ["p", "Тонкий шар має дві вразливості:"], ["ul", "<li>його легко «з’їсти» — достатньо сітці прогнутися між опорами на 5–10 мм;</li><li>будь-який дефект видно на стелі — іржаві плями, тріщини вздовж стрижнів, відшарування.</li>"], ["blockquote", "<p>У перекритті немає запасу. Якщо фундамент може пробачити кілька міліметрів, то тонка плита одразу покаже помилку на стелі.</p>"], ["h2", "Які фіксатори використовувати для перекриття"], ["p", "Нижня сітка перекриття лежить на опалубці — фанері або щитах, тобто на твердій рівній основі. Тут підходять такі вироби:"], ["h3", "«Стійка»"], ["p", "<a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">Фіксатор «Стійка»</a> — основний вибір для перекриттів. Він стабільно стоїть на опалубці, рівномірно розподіляє вагу сітки, а багаторівневі моделі (наприклад, 20-25-30) дають кілька висот в одному виробі."], ["h3", "«Защіпка»"], ["p", "<a href=\"/fiksator-zashchipka\" data-go=\"product\" data-a=\"4-0\">«Защіпка»</a> защіпається на стрижень і утримує його на заданій висоті — 15, 20 або 25 мм. Вона зручна для тонких захисних шарів і не дає фіксатору випасти під час ходіння по сітці."], ["h3", "«Засувка»"], ["p", "<a href=\"/fiksator-zasuvka\" data-go=\"product\" data-a=\"5-0\">«Засувка»</a> розрахована на більші навантаження й діаметри арматури — до 24 мм. Її використовують у зонах із густим армуванням, біля капітелей і над опорами."], ["h3", "«Зірочка» по торцях"], ["p", "По торцях плити, біля бортової опалубки й отворів, на крайні стрижні надягають <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">«Зірочки»</a>, щоб витримати шар і з боку щита."], ["cta", "{\"t\": \"Комплект фіксаторів для перекриття\", \"d\": \"Порахуємо «Стійки», «Защіпки» та «Зірочки» під площу й армування вашої плити.\", \"b\": [[\"Фіксатори арматури\", \"cat_rebar\", \"catalog\", \"rebar\", \"/fiksatory-armatury\"], [\"Запросити розрахунок\", \"rfq\"]]}"], ["h2", "Як розставити фіксатори на опалубці"], ["ol", "<li>Візьміть із креслень захисний шар нижньої арматури й підберіть фіксатор точно під нього.</li><li>Розставте опори в шаховому порядку з кроком близько 0,6–0,8 м для стрижнів 8–12 мм.</li><li>Додайте фіксатори вздовж бортів, біля отворів, під місцями нахлесту й зонами додаткового армування.</li><li>Верхню сітку встановлюйте на окремі підставки — фіксатори захисного шару для неї не призначені.</li><li>Перед бетонуванням пройдіться по каркасу й перевірте відстань до опалубки в кількох точках.</li>"], ["h2", "Як зберегти каркас під час бетонування"], ["ul", "<li>Прокладайте містки або трапи для руху по арматурі, особливо там, де катають тачки.</li><li>Не кидайте бетон з висоти в одне місце — подавайте рівномірно, щоб не продавити сітку.</li><li>Не впирайте глибинний вібратор у фіксатори й арматуру.</li><li>Тримайте запас фіксаторів на майданчику, щоб одразу замінити пошкоджені.</li>"], ["h2", "Скільки фіксаторів потрібно на перекриття"], ["p", "Орієнтовно 4–6 шт. на м² для нижньої сітки. Для перекриття площею 150 м² це 600–900 фіксаторів плюс 5–10 % запасу. Тонкі стрижні (8–10 мм) вимагають частішого кроку, ніж 12–16 мм. Детальніше — у статті <a href=\"/blog/yak-rozrakhuvaty-kilkist-fiksatoriv\" data-go=\"post\" data-a=\"9\">«Як розрахувати кількість фіксаторів»</a>, а про загальні принципи вибору — в статті <a href=\"/blog/yak-obraty-fiksator-armatury\" data-go=\"post\" data-a=\"1\">«Як обрати фіксатор арматури»</a>."], ["h2", "Типові помилки"], ["ul", "<li>Фіксатори ставлять лише по периметру, і в центрі прольоту сітка лягає на опалубку.</li><li>Беруть фіксатор «трохи нижчий», бо потрібного немає на майданчику.</li><li>Використовують металеві підставки без захисту — їхні сліди потім іржавіють на стелі.</li><li>Не закріплюють сітку, і вона зсувається під час подачі бетону.</li>"], ["h2", "Часті питання"], ["h3", "Чи видно пластикові фіксатори на стелі після розпалублення?"], ["p", "На поверхні можуть залишатися невеликі сліди опор, але пластик не іржавіє, тож вони не змінюють колір із часом і легко зникають під штукатуркою чи шпаклівкою."], ["h3", "Яку висоту фіксатора брати для перекриття 200 мм?"], ["p", "Висота фіксатора залежить не від товщини плити, а від проєктного захисного шару — зазвичай 15–25 мм для нижньої арматури. Точне значення дивіться в кресленнях."], ["h3", "Чи можна використовувати «Настил» на опалубці?"], ["p", "Можна, але немає потреби: «Настил» розрахований на сипкі основи. Для опалубки економніше й зручніше використовувати «Стійку» або «Защіпку»."], ["h2", "Висновок"], ["p", "Для монолітного перекриття ключове — точна висота фіксатора під тонкий захисний шар, достатня кількість опор і акуратне бетонування. «Стійка» й «Защіпка» тримають нижню сітку, «Засувка» — густе армування, «Зірочка» — торці. Залиште заявку нижче — підберемо комплект фіксаторів під ваше перекриття."]], [["p", "A cast-in-place floor slab is thin, and every millimetre counts. Slabs are typically 160–220 mm thick, with only 15–25 mm cover to the bottom rebar. If the mesh drops onto the formwork, rust lines appear on the ceiling after stripping and fire resistance falls. If it rises above the design level, the effective depth and load capacity decrease."], ["p", "This article covers which rebar spacers to use in floor slabs, how to place them on formwork and how to protect the cage during the pour."], ["h2", "Concrete cover in floor slabs"], ["p", "The bottom rebar works in tension and drives load capacity. Cover is relatively thin: about 15–25 mm for interior slabs, more for wet areas and slabs over car parks. Take the exact value from the design."], ["p", "Thin cover has two weaknesses:"], ["ul", "<li>it is easy to lose — a 5–10 mm sag between supports is enough;</li><li>any defect shows on the ceiling — rust stains, cracks along bars, spalling.</li>"], ["blockquote", "<p>A slab has no margin. A foundation may forgive a few millimetres; a thin slab shows the mistake on the ceiling.</p>"], ["h2", "Which spacers to use"], ["p", "The bottom mesh rests on plywood or panel formwork — a firm, flat base. Suitable products:"], ["h3", "“Stiika”"], ["p", "The <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika” chair</a> is the main choice for slabs. It stands firmly on formwork, spreads the weight of the mesh, and multi-level models (such as 20-25-30) give several heights in one part."], ["h3", "“Zashchipka”"], ["p", "<a href=\"/en/clip-spacer-zashchipka\" data-go=\"product\" data-a=\"4-0\">“Zashchipka”</a> clips onto the bar and holds it at 15, 20 or 25 mm. It suits thin cover and does not fall out when people walk on the mesh."], ["h3", "“Zasuvka”"], ["p", "<a href=\"/en/slide-spacer-zasuvka\" data-go=\"product\" data-a=\"5-0\">“Zasuvka”</a> is designed for heavier loads and bars up to 24 mm — used in congested zones, at column heads and over supports."], ["h3", "“Zirochka” at edges"], ["p", "At slab edges, edge formwork and openings, fit <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka” wheel spacers</a> on the outer bars to keep cover on the panel side."], ["cta", "{\"t\": \"A spacer set for your slab\", \"d\": \"We will calculate “Stiika”, “Zashchipka” and “Zirochka” quantities for your slab area and reinforcement.\", \"b\": [[\"Rebar spacers\", \"cat_rebar\", \"catalog\", \"rebar\", \"/en/rebar-spacers\"], [\"Request a quote\", \"rfq\"]]}"], ["h2", "Placing spacers on formwork"], ["ol", "<li>Take the bottom cover from the drawings and choose a spacer exactly to it.</li><li>Place supports staggered at about 0.6–0.8 m for 8–12 mm bars.</li><li>Add spacers along edges, around openings, under laps and in additional-reinforcement zones.</li><li>Support the top mesh on separate chairs — cover spacers are not meant for it.</li><li>Walk the cage before pouring and check the distance to formwork at several points.</li>"], ["h2", "Protecting the cage during the pour"], ["ul", "<li>Lay walkways or boards over the rebar, especially along barrow routes.</li><li>Do not drop concrete from height in one spot — place it evenly.</li><li>Keep the poker vibrator away from spacers and bars.</li><li>Keep spare spacers on site to replace damaged ones immediately.</li>"], ["h2", "How many spacers a slab needs"], ["p", "About 4–6 pcs per m² for the bottom mesh: 600–900 spacers for a 150 m² slab plus 5–10 % reserve. Thin bars (8–10 mm) need closer spacing than 12–16 mm. See <a href=\"/en/blog/how-to-calculate-rebar-spacers\" data-go=\"post\" data-a=\"9\">“How to calculate rebar spacers”</a> and <a href=\"/en/blog/how-to-choose-rebar-spacer\" data-go=\"post\" data-a=\"1\">“How to choose a rebar spacer”</a>."], ["h2", "Common mistakes"], ["ul", "<li>Placing spacers only along the perimeter, so the mesh rests on formwork mid-span.</li><li>Using a slightly lower spacer because the right one is not on site.</li><li>Using bare metal chairs whose marks later rust on the ceiling.</li><li>Not securing the mesh, so it shifts during the pour.</li>"], ["h2", "FAQ"], ["h3", "Are plastic spacers visible on the ceiling?"], ["p", "Small marks may remain, but plastic does not rust, so they do not stain over time and disappear under plaster or filler."], ["h3", "What spacer height for a 200 mm slab?"], ["p", "Height depends on the design cover, not slab thickness — usually 15–25 mm for bottom rebar. Check the drawings."], ["h3", "Can I use “Nastil” on formwork?"], ["p", "You can, but there is no need: “Nastil” is designed for loose bases. “Stiika” or “Zashchipka” are cheaper and easier on formwork."], ["h2", "Conclusion"], ["p", "In a floor slab, what matters is exact spacer height for thin cover, enough supports and a careful pour. “Stiika” and “Zashchipka” carry the bottom mesh, “Zasuvka” handles congested zones and “Zirochka” the edges. Leave a request below and we will put together a spacer set for your slab."]]]}, {"id": 10, "st": "pub", "img": "/assets/img/blog/plastykovi-fiksatory.webp", "tag": ["Поради", "Guides"], "date": "2025-09-16", "slug": {"uk": "plastykovi-fiksatory-chy-tsehla", "en": "plastic-spacers-vs-bricks-metal-chairs"}, "t": ["Пластикові фіксатори, цегла чи металеві підставки: що надійніше і що дешевше", "Plastic spacers, bricks or metal chairs: which is more reliable and which is cheaper"], "e": ["Порівнюємо пластикові фіксатори арматури з уламками цегли, бетонними прокладками, брусками й металевими підставками: точність, довговічність, вплив на корозію, швидкість монтажу та реальну вартість.", "We compare plastic rebar spacers with brick fragments, concrete blocks, timber and metal chairs: accuracy, durability, corrosion risk, installation speed and real cost."], "b": [[["p", "На багатьох будмайданчиках досі можна побачити арматурний каркас, покладений на уламки цегли, обрізки брусків чи металеві «стільчики» з арматури. Аргумент завжди однаковий: «так дешевше» і «завжди так робили». Але чи справді це економія, і що відбувається з такою конструкцією через 10–20 років?"], ["p", "У цій статті чесно порівнюємо пластикові фіксатори арматури з популярними замінниками за точністю, довговічністю, впливом на корозію, швидкістю роботи й реальною вартістю."], ["h2", "Чому взагалі потрібні опори під арматуру"], ["p", "Будь-яка опора під арматурою має одне завдання — забезпечити проєктний захисний шар бетону й утримати каркас на місці під час робіт. Від захисного шару залежить, скільки часу бетон захищатиме сталь від вологи й корозії. Детально про це — в статті <a href=\"/blog/zakhysnyi-shar-betonu\" data-go=\"post\" data-a=\"2\">«Захисний шар бетону»</a>."], ["h2", "Варіант 1. Уламки цегли й каміння"], ["p", "<b>Плюси:</b> «безкоштовно», бо є на майданчику."], ["p", "<b>Мінуси:</b>"], ["ul", "<li>довільна висота — шар у кожній точці різний;</li><li>цегла вбирає воду й може стати каналом для вологи до арматури;</li><li>уламки колються під вагою каркаса й від вібрації;</li><li>погане зчеплення з бетоном і можливі порожнини навколо.</li>"], ["h2", "Варіант 2. Дерев’яні бруски"], ["p", "<b>Плюси:</b> легко підрізати під потрібну висоту."], ["p", "<b>Мінуси:</b> дерево вбирає воду, набухає, з часом гниє й залишає в бетоні порожнину — прямий шлях для вологи до арматури. Використовувати дерево як опору, що залишається в бетоні, неприпустимо."], ["h2", "Варіант 3. Металеві підставки з арматури"], ["p", "<b>Плюси:</b> міцні й витримують велике навантаження."], ["p", "<b>Мінуси:</b> метал, що торкається опалубки чи основи, стає «містком» корозії — іржа починається з поверхні й іде вглиб по підставці до каркаса. На стелі після розпалублення такі місця часто проступають рудими плямами. Крім того, їх треба виготовляти вручну, а це час бригади."], ["h2", "Варіант 4. Бетонні прокладки"], ["p", "<b>Плюси:</b> той самий матеріал, що й конструкція, добре працюють під великими навантаженнями."], ["p", "<b>Мінуси:</b> важкі, крихкі, виготовлення потребує часу, а точність висоти залежить від якості виготовлення."], ["h2", "Варіант 5. Пластикові фіксатори"], ["p", "<b>Плюси:</b>"], ["ul", "<li>точна висота, задана пресформою, — однаковий шар по всій конструкції;</li><li>не вбирають воду й не іржавіють — не створюють шляху для корозії;</li><li>ажурна форма дозволяє бетону щільно обтікати фіксатор;</li><li>різні моделі під різні задачі: <a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">«Настил»</a> для сипкої основи, <a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">«Стійка»</a> для опалубки, <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">«Зірочка»</a> для стін і колон;</li><li>монтаж займає секунди, без в’язального дроту.</li>"], ["p", "<b>Мінуси:</b> потрібно заздалегідь купити й привезти на об’єкт потрібні розміри."], ["blockquote", "<p>Найдешевша опора — та, за яку не доведеться платити ремонтом. Відновлення захисного шару на готовій конструкції коштує в рази більше, ніж усі фіксатори об’єкта.</p>"], ["h2", "Порівняння вартості: що насправді дешевше"], ["p", "Пластиковий фіксатор коштує кілька гривень. На плиту площею 100 м² потрібно 400–600 штук — це незначна частка вартості бетонних робіт. Натомість «безкоштовні» замінники мають приховані витрати:"], ["ul", "<li>час бригади на підбір, підрізку й укладання цегли чи брусків;</li><li>ризик не пройти приймання робіт технагляду;</li><li>ремонт захисного шару, якщо після розпалублення арматура проступила на поверхні;</li><li>скорочення терміну служби конструкції.</li>"], ["cta", "{\"t\": \"Перейдіть на заводські фіксатори\", \"d\": \"Підберемо фіксатори під ваш об’єкт і порахуємо, скільки їх потрібно — з цінами виробника.\", \"b\": [[\"Фіксатори арматури\", \"cat_rebar\", \"catalog\", \"rebar\", \"/fiksatory-armatury\"], [\"Запросити розрахунок\", \"rfq\"]]}"], ["h2", "Коли все ж потрібні інші рішення"], ["p", "Пластикові фіксатори захисного шару тримають нижню арматуру й бічні грані. Для верхньої сітки плит і для дуже масивних каркасів використовують спеціальні підставки, розраховані на висоту між сітками. Це не замінник фіксаторів, а окремий елемент армування, який визначає проєкт."], ["h2", "Часті питання"], ["h3", "Чи витримують пластикові фіксатори вагу масивного каркаса?"], ["p", "Так, якщо підібрано правильну модель і крок установки. Для великих навантажень і діаметрів є «Засувка» — для стрижнів до 24 мм."], ["h3", "Чи не стане пластик слабким місцем у бетоні?"], ["p", "Ні. Переріз фіксатора дуже малий порівняно з конструкцією, а ажурна форма дає бетону заповнити простір навколо."], ["h3", "Чи приймає технагляд опори з цегли?"], ["p", "Технагляд перевіряє проєктний захисний шар. Довільні опори часто не дають його витримати, тож ризик зауважень значно вищий."], ["h2", "Висновок"], ["p", "Цегла, дерево й саморобні металеві підставки здаються безкоштовними, але дають довільний захисний шар і створюють шляхи для вологи й корозії. Пластикові фіксатори забезпечують точну висоту, не іржавіють і ставляться за секунди, а їхня вартість — незначна частка кошторису. Залиште заявку — підберемо фіксатори й підготуємо розрахунок."]], [["p", "On many sites you still see rebar cages resting on brick fragments, timber offcuts or home-made metal chairs. The argument is always the same: “it’s cheaper” and “we’ve always done it this way”. But is it really a saving, and what happens to such an element in 10–20 years?"], ["p", "This article honestly compares plastic rebar spacers with popular substitutes on accuracy, durability, corrosion, speed and real cost."], ["h2", "Why rebar needs supports at all"], ["p", "Any support under rebar has one job: provide the design concrete cover and hold the cage during works. Cover determines how long concrete protects steel from moisture and corrosion — see <a href=\"/en/blog/concrete-cover\" data-go=\"post\" data-a=\"2\">“Concrete cover”</a> for details."], ["h2", "Option 1. Brick fragments and stones"], ["p", "<b>Pros:</b> “free”, because they are already on site."], ["p", "<b>Cons:</b>"], ["ul", "<li>random height — cover differs at every point;</li><li>brick absorbs water and can become a moisture path to the rebar;</li><li>fragments crack under the cage and from vibration;</li><li>poor bond with concrete and possible voids around them.</li>"], ["h2", "Option 2. Timber offcuts"], ["p", "<b>Pros:</b> easy to cut to height."], ["p", "<b>Cons:</b> timber absorbs water, swells, rots over time and leaves a void in the concrete — a direct moisture path to the rebar. Timber must never be left in concrete as a support."], ["h2", "Option 3. Metal chairs made from rebar"], ["p", "<b>Pros:</b> strong, carry heavy loads."], ["p", "<b>Cons:</b> metal touching formwork or the base becomes a corrosion bridge — rust starts at the surface and travels along the chair into the cage. On ceilings these spots often show as rust stains after stripping. They are also made by hand, which costs crew time."], ["h2", "Option 4. Concrete blocks"], ["p", "<b>Pros:</b> the same material as the element; good under heavy loads."], ["p", "<b>Cons:</b> heavy, brittle, time-consuming to make, and height accuracy depends on how well they are made."], ["h2", "Option 5. Plastic spacers"], ["p", "<b>Pros:</b>"], ["ul", "<li>exact height set by the mold — equal cover across the element;</li><li>do not absorb water or rust — no corrosion path;</li><li>open shape lets concrete flow tightly around the spacer;</li><li>models for every task: <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil”</a> for loose bases, <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika”</a> for formwork, <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka”</a> for walls and columns;</li><li>installed in seconds, without tie wire.</li>"], ["p", "<b>Cons:</b> you need to buy and deliver the right sizes in advance."], ["blockquote", "<p>The cheapest support is the one you never pay to repair. Restoring cover on a finished element costs many times more than all the spacers on the project.</p>"], ["h2", "Cost comparison: what is really cheaper"], ["p", "A plastic spacer costs a few hryvnias. A 100 m² slab needs 400–600 of them — a tiny share of the concrete works budget. “Free” substitutes carry hidden costs:"], ["ul", "<li>crew time to find, cut and place bricks or timber;</li><li>the risk of failing technical supervision;</li><li>cover repairs if rebar shows on the surface after stripping;</li><li>a shorter service life of the structure.</li>"], ["cta", "{\"t\": \"Switch to factory-made spacers\", \"d\": \"We will pick spacers for your project and calculate how many you need — at manufacturer prices.\", \"b\": [[\"Rebar spacers\", \"cat_rebar\", \"catalog\", \"rebar\", \"/en/rebar-spacers\"], [\"Request a quote\", \"rfq\"]]}"], ["h2", "When other solutions are needed"], ["p", "Plastic cover spacers carry the bottom rebar and side faces. The top mesh of slabs and very massive cages use special chairs sized to the distance between meshes. These are not substitutes for spacers but a separate reinforcement element set by the design."], ["h2", "FAQ"], ["h3", "Can plastic spacers carry a heavy cage?"], ["p", "Yes, with the right model and spacing. For heavy loads and diameters there is “Zasuvka” — for bars up to 24 mm."], ["h3", "Will plastic become a weak point in concrete?"], ["p", "No. Its cross-section is tiny compared with the element, and its open shape lets concrete fill the space around it."], ["h3", "Will supervision accept brick supports?"], ["p", "Supervisors check the design cover. Random supports often fail to achieve it, so the risk of remarks is much higher."], ["h2", "Conclusion"], ["p", "Bricks, timber and home-made metal chairs look free but give random cover and create moisture and corrosion paths. Plastic spacers give an exact height, do not rust and install in seconds, at a tiny share of the budget. Leave a request and we will pick spacers and prepare a quote."]]]}, {"id": 6, "st": "pub", "img": "/assets/img/blog/fiksatory-fundamentna-plyta.webp", "tag": ["Будівництво", "Construction"], "date": "2025-08-12", "slug": {"uk": "fiksatory-dlia-fundamentnoi-plyty", "en": "rebar-spacers-for-raft-foundation"}, "t": ["Фіксатори арматури для фундаментної плити: вибір, схема розкладки та кількість", "Rebar spacers for raft foundations: choice, layout and quantity"], "e": ["Які фіксатори потрібні для фундаментної плити на піску, щебені чи плівці, як підібрати висоту під захисний шар фундаменту, як розкласти опори і скільки їх закласти на об’єкт.", "Which spacers suit a raft foundation on sand, gravel or membrane, how to match the height to the foundation cover, how to lay supports out and how many to order."], "b": [[["p", "Фундаментна плита — найнавантаженіша конструкція будинку, і водночас саме в ній найчастіше «з’їдають» захисний шар бетону. Арматурний каркас вагою в кілька тонн лежить на сипкій основі, по ньому ходять арматурники, тягнуть рукав бетононасоса, а потім ущільнюють суміш глибинним вібратором. Якщо нижня сітка опуститься до основи, сталь опиниться в зоні постійної вологи з ґрунту — і корозія почнеться значно раніше, ніж розраховував проєктувальник."], ["p", "У цій статті розбираємо, які фіксатори арматури підходять для фундаменту, як підібрати висоту під проєктний захисний шар, як правильно розкласти опори на піску, щебені чи гідроізоляції та скільки їх потрібно на плиту. Загальні принципи вибору ми описували в статті <a href=\"/blog/yak-obraty-fiksator-armatury\" data-go=\"post\" data-a=\"1\">«Як обрати фіксатор арматури»</a>, а тут — саме про фундамент."], ["h2", "Чому для фундаменту потрібен особливий фіксатор"], ["p", "Більшість фундаментних плит бетонують не на тверду основу, а на ущільнений пісок, щебеневу подушку, утеплювач або гідроізоляційну мембрану. Звичайна опора з малою площею під вагою каркаса просто тоне в такій основі, і захисний шар зменшується на кілька сантиметрів."], ["p", "Тому для фундаменту обирають фіксатори із широкою опорною площею. Вони розподіляють навантаження, не продавлюють основу й не прорізають плівку. Саме для цього створено <a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">фіксатор «Настил»</a>."], ["blockquote", "<p>На сипкій основі важить не лише висота фіксатора, а й площа, якою він спирається. Опора, що «пішла» в пісок на 15 мм, — це мінус 15 мм захисного шару по всій плиті.</p>"], ["h2", "Який захисний шар потрібен фундаменту"], ["p", "Фундамент працює в найагресивніших умовах: постійний контакт із ґрунтом, волога, іноді — агресивні ґрунтові води. Тому захисний шар тут більший, ніж у перекриттях. Орієнтовно:"], ["ul", "<li>плита на бетонній підготовці — від 35–40 мм;</li><li>плита, яку бетонують безпосередньо на ґрунт або пісок, — від 70 мм;</li><li>верхня арматура плити — зазвичай 25–40 мм залежно від умов експлуатації.</li>"], ["p", "Точні значення завжди беруть із проєкту. Детальніше про те, від чого залежить товщина і чим загрожує її порушення, читайте в статті <a href=\"/blog/zakhysnyi-shar-betonu\" data-go=\"post\" data-a=\"2\">«Захисний шар бетону»</a>."], ["h2", "Як підібрати фіксатор під фундамент"], ["h3", "Нижня сітка на сипкій основі"], ["p", "Для нижньої арматури на піску, щебені чи плівці використовуйте «Настил». Його висоти — від 25–30 до 90–100 мм, тож можна закрити і стандартний шар на підготовці, і збільшений шар при бетонуванні на ґрунт. Обирайте висоту, що дорівнює проєктному захисному шару; якщо точного розміру немає — найближчу більшу."], ["h3", "Нижня сітка на бетонній підготовці"], ["p", "Якщо під плитою є шар підготовки з пісного бетону, основа вже тверда. Тут можна застосовувати <a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">«Стійку»</a> — вона стабільно стоїть на рівній поверхні і має багаторівневі типорозміри. Для каркасів, по яких активно ходять, підійде <a href=\"/fiksator-zasuvka\" data-go=\"product\" data-a=\"5-0\">«Засувка»</a>: вона фіксується на стрижні й не зміщується."], ["h3", "Бічні грані плити й ростверку"], ["p", "Біля опалубки по периметру арматура має триматися на відстані від щитів. Для цього на крайні стрижні надягають <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">«Зірочки»</a> — вони забезпечують однаковий шар з боку опалубки."], ["h3", "Верхня сітка"], ["p", "Фіксатори захисного шару тримають лише нижню арматуру. Верхню сітку фундаменту встановлюють на окремі підставки або каркаси, розраховані на висоту між сітками. Не намагайтеся замінити їх високими фіксаторами — вони не розраховані на таке навантаження."], ["cta", "{\"t\": \"Підберемо фіксатори під ваш фундамент\", \"d\": \"Надішліть креслення плити — порахуємо кількість «Настилу», «Стійок» і «Зірочок» та запропонуємо доставку на об’єкт.\", \"b\": [[\"Фіксатори арматури\", \"cat_rebar\", \"catalog\", \"rebar\", \"/fiksatory-armatury\"], [\"Запросити розрахунок\", \"rfq\"]]}"], ["h2", "Схема розкладки фіксаторів на плиті"], ["ol", "<li>Розкладіть фіксатори рядами в шаховому порядку з кроком, що залежить від діаметра арматури: для стрижнів 10–12 мм — орієнтовно 0,6–0,8 м, для 14–20 мм — до 0,8–1 м.</li><li>Обов’язково поставте опори вздовж країв плити, біля отворів і в місцях нахлесту стрижнів.</li><li>Під місцями, де будуть ходити й котити тачки, крок зменшіть.</li><li>Після укладання сітки пройдіться по ній і перевірте, чи не прогинається вона між опорами.</li><li>Перед бетонуванням виміряйте відстань від арматури до основи в кількох точках по всій площі.</li>"], ["h2", "Скільки фіксаторів потрібно на фундаментну плиту"], ["p", "Орієнтовна витрата для нижньої сітки — 4–6 шт. на м². Для плити площею 100 м² це 400–600 фіксаторів «Настил». Додайте запас 5–10 % на втрати й підрізку. До цього числа додаються «Зірочки» для периметра — приблизно по одній на кожен метр бічної грані з кроком по висоті. Докладна методика є в статті <a href=\"/blog/yak-rozrakhuvaty-kilkist-fiksatoriv\" data-go=\"post\" data-a=\"9\">«Як розрахувати кількість фіксаторів»</a>."], ["p", "Фіксатори PLASTIZA постачаються упаковками від 100 до 2000 шт. — точне фасування вказане в картці кожного товару."], ["h2", "Типові помилки при армуванні фундаменту"], ["ul", "<li>Каркас кладуть на цеглу, щебінь чи бруски — висота довільна, а дерево й цегла вбирають вологу з ґрунту.</li><li>Використовують опори з малою площею на піску — вони тонуть під вагою каркаса.</li><li>Рвуть гідроізоляційну плівку гострими опорами, і вода з ґрунту отримує прямий шлях до бетону.</li><li>Ставлять фіксатори лише по периметру, а в центрі плити сітка лягає на основу.</li><li>Не перевіряють захисний шар перед бетонуванням.</li>"], ["h2", "Часті питання"], ["h3", "Чи можна класти арматуру фундаменту на цеглу?"], ["p", "Не варто. Цегла має довільну висоту, вбирає воду й може розколотися під вагою каркаса. Пластикові фіксатори дають точну висоту й не створюють шляху для вологи до арматури."], ["h3", "Чи не продавить «Настил» утеплювач XPS?"], ["p", "«Настил» має збільшену площу опори саме для м’яких основ. Для утеплювачів із низькою міцністю на стиск зменшіть крок установки, щоб розподілити навантаження."], ["h3", "Які фіксатори потрібні для стрічкового фундаменту?"], ["p", "Для підошви стрічки — ті самі «Настил» або «Стійка» залежно від основи, а для бічних граней і вертикальних випусків — «Зірочки»."], ["h2", "Висновок"], ["p", "Для фундаментної плити на сипкій основі обирайте «Настил» з висотою, що дорівнює проєктному захисному шару, на підготовці — «Стійку» або «Засувку», по периметру — «Зірочки». Розкладайте опори в шаховому порядку з кроком 0,6–1 м і перевіряйте каркас перед заливанням. Надішліть нам креслення — і ми підберемо фіксатори та відвантажимо їх зі складу у Львові чи Києві."]], [["p", "A raft foundation is the most heavily loaded element of a building — and the one where concrete cover is lost most often. A cage weighing several tonnes rests on a loose base, workers walk on it, the pump hose is dragged across it and a poker vibrator compacts the mix. If the bottom mesh sinks to the base, the steel ends up in constant ground moisture and corrosion starts far earlier than the designer assumed."], ["p", "This article explains which rebar spacers suit foundations, how to match the height to the design cover, how to lay supports out on sand, gravel or waterproofing and how many you need. General selection rules are in <a href=\"/en/blog/how-to-choose-rebar-spacer\" data-go=\"post\" data-a=\"1\">“How to choose a rebar spacer”</a>; here we focus on foundations."], ["h2", "Why foundations need a special spacer"], ["p", "Most rafts are cast not on a firm base but on compacted sand, a gravel bed, insulation or a waterproofing membrane. An ordinary support with a small footprint sinks into such a base under the cage, and the cover shrinks by centimetres."], ["p", "Foundations therefore need spacers with a wide footprint that spread the load, do not punch into the base and do not cut the membrane. That is what the <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil” slab chair</a> is for."], ["blockquote", "<p>On a loose base, footprint matters as much as height. A support that sinks 15 mm into sand means 15 mm less cover across the whole slab.</p>"], ["h2", "What cover a foundation needs"], ["p", "Foundations work in the harshest conditions: permanent soil contact, moisture and sometimes aggressive groundwater. Cover is therefore larger than in floor slabs. As a guide:"], ["ul", "<li>raft on concrete blinding — from 35–40 mm;</li><li>raft cast directly on soil or sand — from 70 mm;</li><li>top reinforcement — usually 25–40 mm depending on exposure.</li>"], ["p", "Always take the exact values from the design. See <a href=\"/en/blog/concrete-cover\" data-go=\"post\" data-a=\"2\">“Concrete cover”</a> for what determines thickness and what goes wrong when it is not achieved."], ["h2", "Choosing a spacer for the foundation"], ["h3", "Bottom mesh on a loose base"], ["p", "Use “Nastil” for bottom rebar on sand, gravel or membrane. Heights range from 25–30 to 90–100 mm, covering both standard cover on blinding and increased cover when casting on soil. Choose the height equal to the design cover; if it is unavailable, go one size up."], ["h3", "Bottom mesh on blinding"], ["p", "If the raft sits on lean-concrete blinding, the base is firm. <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika”</a> stands stably on a flat surface and has multi-level sizes. For cages with heavy foot traffic, <a href=\"/en/slide-spacer-zasuvka\" data-go=\"product\" data-a=\"5-0\">“Zasuvka”</a> clips onto the bar and does not move."], ["h3", "Raft and pile-cap edges"], ["p", "Next to perimeter formwork, rebar must stay clear of the panels. Fit <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka” wheel spacers</a> on the edge bars to keep cover equal on the formwork side."], ["h3", "Top mesh"], ["p", "Cover spacers only carry the bottom reinforcement. The top mesh sits on separate chairs sized to the distance between meshes — do not replace them with tall cover spacers."], ["cta", "{\"t\": \"Spacers for your foundation\", \"d\": \"Send the slab drawing — we will calculate “Nastil”, “Stiika” and “Zirochka” quantities and offer delivery to site.\", \"b\": [[\"Rebar spacers\", \"cat_rebar\", \"catalog\", \"rebar\", \"/en/rebar-spacers\"], [\"Request a quote\", \"rfq\"]]}"], ["h2", "Spacer layout on a raft"], ["ol", "<li>Lay spacers in staggered rows at a spacing set by bar diameter: about 0.6–0.8 m for 10–12 mm bars, up to 0.8–1 m for 14–20 mm.</li><li>Always add supports along slab edges, around openings and at bar laps.</li><li>Reduce spacing where people will walk and barrows will run.</li><li>Walk the mesh after laying and check it does not sag between supports.</li><li>Before the pour, measure the distance from rebar to base at several points across the slab.</li>"], ["h2", "How many spacers a raft needs"], ["p", "Allow roughly 4–6 pcs per m² for the bottom mesh: 400–600 “Nastil” spacers for a 100 m² raft, plus 5–10 % reserve. Add “Zirochka” spacers for the perimeter — about one per metre of edge per level. See <a href=\"/en/blog/how-to-calculate-rebar-spacers\" data-go=\"post\" data-a=\"9\">“How to calculate rebar spacers”</a> for the full method."], ["p", "PLASTIZA spacers come in packs of 100 to 2,000 pcs — the exact pack size is on each product page."], ["h2", "Common mistakes"], ["ul", "<li>Laying the cage on brick, gravel or timber — random height, and brick and timber absorb ground moisture.</li><li>Using small-footprint supports on sand — they sink under the cage.</li><li>Tearing the membrane with sharp supports, giving groundwater a direct path to the concrete.</li><li>Placing spacers only around the edge, so the centre of the mesh rests on the base.</li><li>Skipping the cover check before pouring.</li>"], ["h2", "FAQ"], ["h3", "Can foundation rebar sit on bricks?"], ["p", "Better not. Brick gives a random height, absorbs water and can crack under the cage. Plastic spacers give an exact height and no moisture path to the steel."], ["h3", "Will “Nastil” punch into XPS insulation?"], ["p", "“Nastil” has an enlarged footprint for soft bases. On low-strength insulation, reduce the spacing to spread the load."], ["h3", "Which spacers suit a strip foundation?"], ["p", "“Nastil” or “Stiika” for the footing depending on the base, and “Zirochka” for side faces and vertical starter bars."], ["h2", "Conclusion"], ["p", "On a loose base use “Nastil” at the design cover height, on blinding use “Stiika” or “Zasuvka”, and “Zirochka” around the perimeter. Lay supports staggered at 0.6–1 m and check the cage before pouring. Send us your drawing and we will pick the spacers and ship them from Lviv or Kyiv."]]]}, {"id": 5, "st": "pub", "date": "2025-07-01", "t": ["Конуси, корки й дистанційні труби для опалубки: як закрити отвори від стяжних гвинтів", "Formwork cones, plugs and spacer tubes: how to seal tie-rod holes"], "e": ["Як працює стяжка опалубки, навіщо потрібні дистанційна труба, конус і корок, як підібрати комплект і правильно закрити отвори в монолітних стінах.", "How formwork ties work, what spacer tubes, cones and plugs do, how to pick a set and how to seal holes in cast-in-place walls properly."], "b": [[["p", "Під час бетонування монолітних стін і колон щити опалубки стягують між собою стяжними гвинтами, які проходять крізь майбутню конструкцію. Після набору міцності бетону гвинти потрібно витягти, а отвори — закрити. Саме для цього існують дистанційні труби, конуси та корки."], ["p", "Це недорогі вироби, але від них залежить, чи вдасться легко демонтувати опалубку, чи не потече бетон крізь щити і як виглядатиме стіна після розпалублення. Розбираємо, як працює кожен елемент і як зібрати правильний комплект. Усі вироби є в нашому <a href=\"/fiksatory-dlia-opalubky\" data-go=\"catalog\" data-a=\"form\">каталозі фіксаторів для опалубки</a>."], ["h2", "Як влаштована стяжка опалубки"], ["p", "Щити опалубки встановлюють з обох боків майбутньої стіни. Щоб тиск свіжого бетону не розсунув їх, щити з’єднують стяжними гвинтами (тяжами) з гайками. Гвинт проходить крізь бетон — і якщо він опиниться в ньому «голим», витягти його буде неможливо. Тому гвинт пропускають усередині пластикової труби, а на її кінцях встановлюють конуси."], ["h2", "Дистанційна труба"], ["p", "<a href=\"/dystantsiina-truba\" data-go=\"product\" data-a=\"9-0\">Дистанційна труба</a> виконує дві функції: утримує проєктну відстань між щитами, тобто товщину стіни, і захищає стяжний гвинт від контакту з бетоном. Після бетонування гвинт легко виймається, а труба залишається в стіні."], ["p", "Труби виготовляють із поліетилену (П/Е) або ПВХ. Обидва матеріали стійкі до навантажень, агресивного середовища й перепадів температур. Довжину труби розраховують за товщиною стіни з урахуванням конусів на її кінцях."], ["h2", "Конус"], ["p", "<a href=\"/fiksator-konus\" data-go=\"product\" data-a=\"6-0\">Фіксатор «Конус»</a> надягається на кінець труби діаметром 22 мм і впирається в щит. Він збільшує площу контакту зі щитом, не дає бетону затікати в трубу й потрапляти на гвинт, а після демонтажу формує акуратний конічний вхід отвору, який зручно герметизувати."], ["h2", "Корок і корок-ялинка"], ["p", "Після розпалублення в стіні залишаються отвори. Їх закривають корками:"], ["ul", "<li><a href=\"/fiksator-korok\" data-go=\"product\" data-a=\"8-0\">«Корок»</a> — циліндрична заглушка, яка запобігає затіканню бетону в монтажні отвори опалубних щитів і герметизує отвори в монолітних конструкціях;</li><li><a href=\"/korok-yalynka\" data-go=\"product\" data-a=\"7-0\">«Корок-ялинка»</a> — універсальний корок із ребрами, що закриває невикористані отвори під анкерні стрижні в опалубці, а також отвори в стінах після демонтажу.</li>"], ["p", "Обидва вироби мають діаметр 24 мм — під отвір, сформований конусом."], ["blockquote", "<p>Комплект «труба + два конуси + два корки» на кожну точку стяжки коштує копійки, але саме він визначає, чи будуть стіни чистими й сухими після розпалублення.</p>"], ["h2", "Як підібрати комплект"], ["ol", "<li><b>Визначте систему стяжки.</b> Найпоширеніший варіант для щитової опалубки — гвинт, під який використовують трубку 22 мм. Уточніть параметри у постачальника опалубки.</li><li><b>Порахуйте кількість точок стяжки.</b> Вона визначається системою опалубки: щити мають отвори у фіксованих місцях. Множте кількість точок на щиті на кількість щитів, які встановлюються за одне бетонування, і на кількість захваток.</li><li><b>Розрахуйте довжину труб</b> під товщину кожної стіни.</li><li><b>Порахуйте конуси й корки:</b> по два на кожну трубу — з кожного боку стіни.</li><li><b>Додайте корки-ялинки</b> для невикористаних отворів у щитах.</li><li><b>Закладіть запас</b> 5–10 % на втрати під час монтажу.</li>"], ["cta", "{\"t\": \"Комплектуємо опалубку під ваш об’єкт\", \"d\": \"Труби, конуси й корки зі складу у Львові та Києві — підберемо комплект і порахуємо кількість.\", \"b\": [[\"Фіксатори для опалубки\", \"cat_form\", \"catalog\", \"form\", \"/fiksatory-dlia-opalubky\"], [\"Комплектація об’єктів\", \"srv2\", \"soon\", \"2\", \"/komplektatsiia-obiektiv\"], [\"Запросити розрахунок\", \"rfq\"]]}"], ["h2", "Герметизація отворів у стінах підвалів"], ["p", "Для внутрішніх стін зазвичай достатньо закрити отвір корком. Для стін підвалів, резервуарів та інших конструкцій, що контактують з водою чи ґрунтом, корок поєднують з додатковою гідроізоляцією: отвір заповнюють ремонтним або гідроізоляційним розчином, за проєктом — використовують спеціальні герметики. Конус, сформований фіксатором, полегшує цю роботу: розчин краще тримається в конічному отворі."], ["h2", "Типові помилки"], ["ul", "<li>Гвинт пропускають без труби — потім його доводиться зрізати й залишати в бетоні.</li><li>Не ставлять конуси — бетон затікає в трубу, а на поверхні залишаються напливи.</li><li>Залишають отвори відкритими — у них потрапляє вода, взимку вона замерзає й руйнує бетон.</li><li>Підбирають корки не під діаметр — вони випадають або не входять в отвір.</li>"], ["h2", "Часті питання"], ["h3", "Чи можна використовувати конуси повторно?"], ["p", "Конуси залишаються в стіні разом із трубою або виймаються під час розпалублення залежно від технології. Здебільшого їх розглядають як витратний матеріал."], ["h3", "Що краще: ПВХ чи поліетиленова труба?"], ["p", "Обидва варіанти надійні. Вибір залежить від вимог проєкту й умов роботи; менеджер підкаже оптимальний варіант для вашого об’єкта."], ["h3", "Чи є все це на складі?"], ["p", "Так, ходові позиції є в наявності на складах у Львові та Києві. Доставляємо Новою поштою, вантажними перевізниками або прямо на об’єкт — <a href=\"/dostavka\" data-go=\"delivery\">деталі доставки</a>."], ["h2", "Висновок"], ["p", "Дистанційна труба захищає гвинт і тримає товщину стіни, конус не пускає бетон у трубу й формує акуратний отвір, корок закриває його після розпалублення. Разом вони роблять монтаж і демонтаж опалубки швидким, а стіни — чистими. Якщо вам потрібен комплект на об’єкт, залиште заявку нижче — ми порахуємо кількість і підготуємо пропозицію."]], [["p", "When casting concrete walls and columns, formwork panels are tied together with rods that pass through the future structure. Once the concrete has gained strength, the rods are pulled out and the holes sealed. That is what spacer tubes, cones and plugs are for."], ["p", "They are inexpensive, yet they decide whether formwork strips easily, whether concrete leaks through the panels and how the wall looks afterwards. Here is how each part works and how to build the right set. All parts are in our <a href=\"/en/formwork-accessories\" data-go=\"catalog\" data-a=\"form\">formwork accessories catalog</a>."], ["h2", "How formwork ties work"], ["p", "Panels stand on both sides of the future wall. To stop fresh concrete pressure from pushing them apart, they are connected with tie rods and nuts. A bare rod cast into concrete cannot be removed — so it runs inside a plastic tube with cones at both ends."], ["h2", "Spacer tube"], ["p", "The <a href=\"/en/spacer-tube\" data-go=\"product\" data-a=\"9-0\">spacer tube</a> keeps the panels at the design distance — the wall thickness — and protects the tie rod from concrete. After the pour the rod slides out and the tube stays in the wall."], ["p", "Tubes are made of polyethylene (PE) or PVC; both resist loads, aggressive environments and temperature swings. Tube length is calculated from the wall thickness, allowing for the cones."], ["h2", "Cone"], ["p", "The <a href=\"/en/cone-spacer-konus\" data-go=\"product\" data-a=\"6-0\">“Konus” cone</a> fits onto the end of a 22 mm tube and bears against the panel. It increases the contact area, keeps concrete out of the tube and off the rod and, after stripping, leaves a neat conical hole that is easy to seal."], ["h2", "Plug and fir-tree plug"], ["p", "After stripping, holes remain in the wall. They are closed with plugs:"], ["ul", "<li>the <a href=\"/en/formwork-plug-korok\" data-go=\"product\" data-a=\"8-0\">“Korok” plug</a> — a cylindrical cap that stops concrete entering panel holes and seals holes in cast-in-place structures;</li><li>the <a href=\"/en/fir-tree-plug\" data-go=\"product\" data-a=\"7-0\">fir-tree plug</a> — a ribbed universal plug for unused tie holes in panels and for holes in walls after stripping.</li>"], ["p", "Both are 24 mm — matching the hole formed by the cone."], ["blockquote", "<p>A tube, two cones and two plugs per tie point cost very little, yet they decide whether walls come out clean and dry.</p>"], ["h2", "How to put a set together"], ["ol", "<li><b>Identify the tie system.</b> The most common panel-formwork option uses a 22 mm tube; confirm with your formwork supplier.</li><li><b>Count tie points</b> — fixed by the panel system: holes per panel × panels per pour × number of pours.</li><li><b>Work out tube lengths</b> for each wall thickness.</li><li><b>Count cones and plugs:</b> two per tube, one on each face.</li><li><b>Add fir-tree plugs</b> for unused panel holes.</li><li><b>Allow 5–10 %</b> for losses.</li>"], ["cta", "{\"t\": \"We supply formwork sets for your site\", \"d\": \"Tubes, cones and plugs in stock in Lviv and Kyiv — we will build the set and calculate quantities.\", \"b\": [[\"Formwork accessories\", \"cat_form\", \"catalog\", \"form\", \"/en/formwork-accessories\"], [\"Site supply\", \"srv2\", \"soon\", \"2\", \"/en/construction-supply\"], [\"Request a quote\", \"rfq\"]]}"], ["h2", "Sealing holes in basement walls"], ["p", "For internal walls a plug is usually enough. For basements, tanks and other elements in contact with water or soil, combine the plug with extra waterproofing: fill the hole with repair or waterproofing mortar or a specified sealant. The conical hole formed by the cone helps the mortar key in."], ["h2", "Common mistakes"], ["ul", "<li>Running the rod without a tube — it then has to be cut and left in the concrete.</li><li>Skipping cones — concrete enters the tube and leaves fins on the surface.</li><li>Leaving holes open — water gets in, freezes in winter and damages the concrete.</li><li>Using plugs of the wrong diameter — they fall out or do not fit.</li>"], ["h2", "FAQ"], ["h3", "Can cones be reused?"], ["p", "Depending on the method, cones stay in the wall with the tube or are removed at stripping. They are generally treated as consumables."], ["h3", "PVC or PE tube?"], ["p", "Both are reliable. The choice depends on the project and conditions; our manager will suggest the best option."], ["h3", "Is everything in stock?"], ["p", "Yes, fast-moving items are in stock in Lviv and Kyiv. We ship by Nova Post, freight carriers or straight to site — <a href=\"/en/delivery\" data-go=\"delivery\">delivery details</a>."], ["h2", "Conclusion"], ["p", "The spacer tube protects the rod and sets the wall thickness, the cone keeps concrete out and forms a neat hole, and the plug closes it after stripping. Together they make formwork fast to fit and strip and leave walls clean. Need a set for your site? Leave a request below and we will calculate quantities and send an offer."]]], "tag": ["Будівництво", "Construction"]}, {"id": 4, "st": "pub", "date": "2025-05-27", "t": ["Виготовлення пресформи на замовлення: що підготувати, вартість і терміни", "Custom injection mold: what to prepare, cost drivers and lead times"], "e": ["Що потрібно виробнику для розрахунку пресформи, з чого вона складається, які чинники формують ціну й терміни і як скоротити шлях до першої партії.", "What a manufacturer needs to quote an injection mold, what a mold consists of, what drives cost and lead time and how to reach the first batch faster."], "b": [[["p", "Пресформа — це інструмент, який визначає якість кожної деталі, що з неї вийде. Помилки в конструкції форми важко й дорого виправити пізніше, тому підготовка до замовлення має не менше значення, ніж саме виготовлення."], ["p", "У цій статті пояснюємо, з чого складається пресформа для лиття пластику, що підготувати до першого звернення, від чого залежить вартість і терміни, а також як скоротити шлях до серійної партії. Детальніше про послугу — на сторінці <a href=\"/vyhotovlennia-presform\" data-go=\"soon\" data-a=\"1\">«Виготовлення пресформ»</a>."], ["h2", "З чого складається пресформа"], ["p", "Навіть проста на вигляд форма — це складний механізм із десятків деталей:"], ["ul", "<li><b>Формоутворні вставки (матриця й пуансон)</b> — створюють зовнішню й внутрішню поверхні виробу.</li><li><b>Ливникова система</b> — канали, якими розплав надходить у порожнину. Буває холодноканальною та гарячоканальною.</li><li><b>Система охолодження</b> — канали для теплоносія, від яких залежить час циклу та стабільність розмірів.</li><li><b>Система виштовхування</b> — штовхачі, плити, знімачі, що знімають деталь з пуансона.</li><li><b>Рухомі елементи</b> — повзуни, знаки, клини для піднутрень, отворів збоку, різьб.</li><li><b>Корпус (пакет плит)</b> — з’єднує всі вузли й встановлюється на термопластавтомат.</li>"], ["h2", "Що підготувати до звернення"], ["p", "Що більше даних ви надасте, то точнішою буде комерційна пропозиція. Ідеальний набір:"], ["ol", "<li><b>Креслення або 3D-модель</b> виробу — бажано у форматі STEP або IGES, плюс PDF із розмірами й допусками.</li><li><b>Матеріал</b> — марка пластику або хоча б умови роботи деталі: навантаження, температура, вулиця чи приміщення.</li><li><b>Плановий обсяг</b> — партія та річна потреба. Від цього залежить кількість гнізд і клас форми.</li><li><b>Вимоги до точності та поверхні</b> — критичні розміри, глянець, текстура, видимі зони, де небажані сліди ливника.</li><li><b>Колір</b> і, за наявності, вимоги до маркування.</li><li><b>Бажані терміни</b> першої партії.</li>"], ["blockquote", "<p>Чим повніше технічне завдання, тим точніший розрахунок і менше сюрпризів на етапі пробного лиття.</p>"], ["h3", "Немає креслення? Працюємо зі зразком"], ["p", "Якщо у вас є лише фізичний зразок, ми виконаємо обмір і побудуємо 3D-модель. На цьому ж етапі можна виправити недоліки оригіналу — потоншити надто масивні стінки, додати ребра жорсткості чи ухили."], ["h2", "Від чого залежить вартість пресформи"], ["ul", "<li><b>Розміри та складність виробу.</b> Більша й складніша деталь — більші плити, довша механічна обробка.</li><li><b>Кількість гнізд.</b> Багатогніздна форма дорожча, але дає дешевшу деталь на великих тиражах.</li><li><b>Піднутрення та рухомі елементи.</b> Кожен повзун чи знак — це додатковий вузол.</li><li><b>Тип ливникової системи.</b> Гарячі канали дорожчі, але економлять матеріал і скорочують цикл.</li><li><b>Сталь і ресурс.</b> Для великих тиражів формоутворні частини виготовляють із загартованих інструментальних сталей, для менших — можна обрати простіше рішення.</li><li><b>Вимоги до поверхні й точності.</b> Полірування, текстурування, жорсткі допуски збільшують обсяг робіт.</li>"], ["h3", "Одногніздна чи багатогніздна форма"], ["p", "Одногніздна форма дешевша й швидша у виготовленні, її легше доводити. Багатогніздна виправдана, коли річний обсяг вимірюється десятками й сотнями тисяч деталей. Ми порахуємо обидва варіанти, щоб ви бачили загальну вартість проєкту, а не лише ціну форми."], ["h2", "Етапи та терміни виготовлення"], ["ol", "<li><b>Аналіз і комерційна пропозиція</b> — оцінюємо технологічність, погоджуємо конструкцію, вартість і терміни.</li><li><b>Проєктування</b> — 3D-модель пресформи, розрахунок ливникової системи й охолодження, погодження із замовником.</li><li><b>Виготовлення</b> — фрезерування на верстатах із ЧПК, електроерозійна обробка, шліфування, термообробка.</li><li><b>Складання й налагодження</b> — збирання вузлів, перевірка рухомих елементів і систем охолодження.</li><li><b>Пробне лиття</b> — перші відливки, вимірювання, за потреби — доведення форми.</li><li><b>Передача або серія</b> — форма переходить у серійне виробництво на нашому обладнанні чи передається вам.</li>"], ["p", "Загальний термін залежить від складності: проста форма виготовляється за кілька тижнів, складна багатогніздна — довше. Точний графік зафіксуємо в пропозиції."], ["cta", "{\"t\": \"Маєте креслення чи зразок?\", \"d\": \"Ознайомтеся з послугами або одразу надішліть файли — розрахуємо пресформу й лиття.\", \"b\": [[\"Виготовлення пресформ\", \"srv1\", \"soon\", \"1\", \"/vyhotovlennia-presform\"], [\"Лиття пластикових виробів\", \"srv0\", \"soon\", \"0\", \"/lyttia-plastyku\"], [\"Надіслати креслення\", \"rfq\"]]}"], ["h2", "Як скоротити терміни й бюджет"], ["ul", "<li>Закладайте технологічність у конструкцію: рівні стінки, ухили, радіуси.</li><li>Уникайте піднутрень, без яких можна обійтися, — кожне додає рухомий вузол.</li><li>Розгляньте сімейну форму, якщо кілька деталей виготовляються в однаковому матеріалі й кольорі.</li><li>Почніть із прототипу, якщо конструкція ще не остаточна: зміни до металу обходяться значно дешевше.</li>"], ["h2", "Кому належить пресформа"], ["p", "Пресформа, виготовлена й оплачена під ваш виріб, належить вам. Ви можете забрати її на власне підприємство або залишити в нас — тоді ми відливатимемо партії на своєму обладнанні й зберігатимемо форму між замовленнями. Як проходить сам процес лиття, ми описали в статті <a href=\"/blog/lyttia-pid-tyskom\" data-go=\"post\" data-a=\"3\">«Лиття пластмас під тиском»</a>."], ["h2", "Часті питання"], ["h3", "Скільки коштує пресформа?"], ["p", "Однозначної ціни немає: вона залежить від розмірів, складності, кількості гнізд і вимог до ресурсу. Після аналізу креслення ми надаємо пропозицію з розбивкою вартості."], ["h3", "Чи можна змінити виріб після виготовлення форми?"], ["p", "Частково — так, якщо зміни зводяться до видалення металу (поглиблення, подовження). Додавати метал складніше, тому основні рішення краще погодити до початку виготовлення."], ["h3", "Скільки циклів витримує пресформа?"], ["p", "Ресурс закладається на етапі проєктування під ваш плановий тираж і залежить від сталі, матеріалу виробу та умов експлуатації."], ["h2", "Висновок"], ["p", "Добре підготовлене звернення — це креслення або зразок, матеріал, обсяг і вимоги до точності. З ними ми швидко підготуємо пропозицію, а після погодження — спроєктуємо, виготовимо й запустимо форму у виробництво. Заповніть форму нижче, щоб отримати розрахунок."]], [["p", "The mold is the tool that defines the quality of every part it makes. Design mistakes are hard and costly to fix later, so preparing the request matters as much as the build itself."], ["p", "This article explains what an injection mold consists of, what to prepare for your first enquiry, what drives cost and lead time and how to shorten the road to series production. More about the service: <a href=\"/en/mold-making\" data-go=\"soon\" data-a=\"1\">Mold making</a>."], ["h2", "What a mold consists of"], ["ul", "<li><b>Cavity and core inserts</b> — form the outer and inner surfaces of the part.</li><li><b>Runner system</b> — channels that deliver the melt; cold or hot runner.</li><li><b>Cooling system</b> — channels that control cycle time and dimensional stability.</li><li><b>Ejection system</b> — pins, plates and strippers that remove the part.</li><li><b>Moving elements</b> — slides and lifters for undercuts, side holes and threads.</li><li><b>Mold base</b> — the plate stack that holds everything and mounts on the machine.</li>"], ["h2", "What to prepare"], ["ol", "<li><b>Drawing or 3D model</b> — ideally STEP or IGES, plus a PDF with dimensions and tolerances.</li><li><b>Material</b> — the grade, or at least operating conditions: load, temperature, indoor or outdoor.</li><li><b>Planned volume</b> — batch size and annual demand; this sets cavity count and mold class.</li><li><b>Accuracy and surface requirements</b> — critical dimensions, gloss, texture, visible areas where gate marks are unwanted.</li><li><b>Colour</b> and any marking requirements.</li><li><b>Target date</b> for the first batch.</li>"], ["blockquote", "<p>The fuller the brief, the more accurate the quote and the fewer surprises at the trial stage.</p>"], ["h3", "No drawing? We work from a sample"], ["p", "If you only have a physical sample, we will measure it and build a 3D model — and can fix the original’s weaknesses along the way, such as thick walls, missing ribs or draft."], ["h2", "What drives mold cost"], ["ul", "<li><b>Part size and complexity</b> — larger plates, longer machining.</li><li><b>Number of cavities</b> — a multi-cavity mold costs more but cuts unit price on large runs.</li><li><b>Undercuts and moving elements</b> — each slide or lifter is an extra assembly.</li><li><b>Runner type</b> — hot runners cost more but save material and cycle time.</li><li><b>Steel and tool life</b> — hardened tool steels for long runs, simpler options for smaller ones.</li><li><b>Surface and accuracy</b> — polishing, texturing and tight tolerances add work.</li>"], ["h3", "Single or multi-cavity"], ["p", "A single-cavity mold is cheaper, faster to build and easier to tune. Multi-cavity pays off when annual volume reaches tens or hundreds of thousands of parts. We will price both so you see the total project cost, not just the mold."], ["h2", "Stages and lead times"], ["ol", "<li><b>Review and quote</b> — manufacturability, design, price and timing.</li><li><b>Design</b> — 3D mold model, runner and cooling layout, customer approval.</li><li><b>Manufacturing</b> — CNC milling, EDM, grinding, heat treatment.</li><li><b>Assembly and setup</b> — fitting assemblies, checking moving parts and cooling.</li><li><b>Trial molding</b> — first shots, measurement and adjustments if needed.</li><li><b>Handover or production</b> — the mold goes into series production with us or is handed over to you.</li>"], ["p", "A simple mold takes a few weeks; a complex multi-cavity tool takes longer. The exact schedule is fixed in the quote."], ["cta", "{\"t\": \"Have a drawing or sample?\", \"d\": \"Explore our services or send files right away — we will quote the mold and molding.\", \"b\": [[\"Mold making\", \"srv1\", \"soon\", \"1\", \"/en/mold-making\"], [\"Injection molding\", \"srv0\", \"soon\", \"0\", \"/en/injection-molding\"], [\"Send a drawing\", \"rfq\"]]}"], ["h2", "How to save time and budget"], ["ul", "<li>Design for manufacturing: even walls, draft, radii.</li><li>Avoid undercuts you do not need — each adds a moving assembly.</li><li>Consider a family mold for several parts in the same material and colour.</li><li>Start with a prototype if the design is not final — changes before steel are far cheaper.</li>"], ["h2", "Who owns the mold"], ["p", "A mold made and paid for your part is yours. You can take it to your own plant or keep it with us — we will mold batches on our equipment and store the tool between orders. How molding itself works is covered in <a href=\"/en/blog/injection-molding-process\" data-go=\"post\" data-a=\"3\">“Plastic injection molding”</a>."], ["h2", "FAQ"], ["h3", "How much does a mold cost?"], ["p", "There is no single price: it depends on size, complexity, cavities and tool life. After reviewing the drawing we send a quote with a cost breakdown."], ["h3", "Can the part be changed after the mold is built?"], ["p", "Partly — if changes mean removing steel (deeper, longer features). Adding steel is harder, so key decisions are best agreed before manufacturing."], ["h3", "How many cycles does a mold last?"], ["p", "Tool life is designed in for your planned volume and depends on the steel, the plastic and operating conditions."], ["h2", "Conclusion"], ["p", "A well-prepared enquiry includes a drawing or sample, material, volume and accuracy requirements. With these we can quote quickly and then design, build and launch the mold. Fill in the form below to get a quote."]]], "tag": ["Пресформи", "Molds"]}, {"id": 3, "st": "pub", "date": "2025-04-22", "t": ["Лиття пластмас під тиском: етапи від креслення до серійної партії", "Plastic injection molding: stages from drawing to production run"], "e": ["Як працює лиття пластику під тиском, які матеріали використовують, з яких етапів складається запуск виробу і від чого залежить ціна деталі.", "How plastic injection molding works, which materials are used, what stages a new part goes through and what drives the unit price."], "b": [[["p", "Лиття під тиском — основна технологія, за якою виготовляють більшість пластикових деталей навколо нас: від корпусів побутової техніки до будівельних фіксаторів. Вона дозволяє випускати тисячі однакових виробів зі стабільною геометрією та за прогнозовану ціну."], ["p", "Але між ідеєю й першою серійною партією лежить кілька етапів: аналіз креслення, проєктування й виготовлення пресформи, пробне лиття, доведення і лише потім — серія. У цій статті розповідаємо, як проходить цей шлях на виробництві PLASTIZA у Львові, на що звернути увагу замовнику і як зекономити час і бюджет. Детальніше про послугу — на сторінці <a href=\"/lyttia-plastyku\" data-go=\"soon\" data-a=\"0\">«Лиття пластикових виробів»</a>."], ["h2", "Що таке лиття пластмас під тиском"], ["p", "Сировину — полімерні гранули — подають у матеріальний циліндр термопластавтомата (ТПА). Там вона нагрівається й пластифікується шнеком. Далі розплав під високим тиском впорскується в закриту пресформу, заповнює порожнину та охолоджується. Пресформа розкривається, виштовхувачі знімають готовий виріб, і цикл повторюється."], ["p", "Тривалість одного циклу — від кількох секунд до хвилини й більше. Вона залежить від товщини стінок, матеріалу та кількості гнізд у формі. Саме час циклу — один із головних чинників собівартості деталі."], ["h2", "Переваги технології"], ["ul", "<li><b>Повторюваність.</b> Кожен виріб у партії має однакову геометрію, задану пресформою.</li><li><b>Складна форма.</b> Ребра жорсткості, отвори, защіпки, різьби — усе формується за один цикл.</li><li><b>Низька ціна деталі на великих тиражах.</b> Витрати на пресформу розподіляються на весь обсяг випуску.</li><li><b>Мінімум відходів.</b> Ливники й брак переробляють і повторно використовують там, де це дозволяють вимоги до виробу.</li><li><b>Широкий вибір матеріалів</b> — від м’яких до конструкційних пластиків.</li>"], ["h2", "Які матеріали використовують"], ["p", "Матеріал обирають під умови роботи виробу: навантаження, температуру, контакт із хімією, ультрафіолетом чи вологою. Найпоширеніші:"], ["ul", "<li><b>Поліпропілен (PP)</b> — легкий, хімічно стійкий, добре підходить для технічних і будівельних виробів;</li><li><b>Поліетилен (PE)</b> — еластичний, стійкий до вологи та низьких температур;</li><li><b>ABS</b> — жорсткий, з гарною поверхнею, для корпусів і декоративних деталей;</li><li><b>Поліамід (PA)</b> — міцний і зносостійкий, для навантажених механічних деталей;</li><li><b>Полікарбонат (PC) і POM</b> — для точних деталей і підвищених вимог до міцності.</li>"], ["p", "До базового полімеру додають барвники, УФ-стабілізатори, наповнювачі. Склад погоджуємо із замовником на етапі технічного завдання."], ["h2", "Етапи: від креслення до серійної партії"], ["h3", "1. Аналіз креслення і технологічності"], ["p", "Інженер перевіряє, чи можна виготовити деталь литтям без зайвих ускладнень. Ключові моменти: рівномірна товщина стінок, ухили для виймання з форми, радіуси замість гострих кутів, піднутрення, місце впорскування. На цьому етапі ми часто пропонуємо невеликі зміни конструкції, які спрощують пресформу й зменшують брак."], ["h3", "2. Проєктування та виготовлення пресформи"], ["p", "Пресформа — найдорожча й найвідповідальніша частина проєкту. Її проєктують у 3D, погоджують із замовником і виготовляють на верстатах із ЧПК. Про те, що підготувати до звернення і від чого залежить вартість, читайте в статті <a href=\"/blog/presforma-pid-vash-vyrib\" data-go=\"post\" data-a=\"4\">«Пресформа на замовлення: що підготувати»</a>, а про саму послугу — на сторінці <a href=\"/vyhotovlennia-presform\" data-go=\"soon\" data-a=\"1\">«Виготовлення пресформ»</a>."], ["h3", "3. Пробне лиття і доведення"], ["p", "Перші відливки показують, як форма працює в реальності. Технолог підбирає температуру, тиск, швидкість впорскування й час охолодження. За потреби форму доопрацьовують, щоб деталь відповідала кресленню."], ["h3", "4. Погодження зразків"], ["p", "Замовник отримує пробні вироби для перевірки розмірів, складання з іншими деталями та зовнішнього вигляду. Після погодження параметри процесу фіксуються."], ["h3", "5. Серійне виробництво і контроль якості"], ["p", "Серія йде на зафіксованих режимах. Розміри й вигляд виробів контролюють під час усього тиражу, щоб перша й остання деталь партії були однаковими."], ["blockquote", "<p>Найдешевше виправляти помилку на кресленні, дорожче — у металі пресформи, і найдорожче — у готовій партії. Тому ми приділяємо стільки уваги першому етапу.</p>"], ["cta", "{\"t\": \"Дослідіть наші напрями\", \"d\": \"Повний цикл в одних руках: від креслення та пресформи до серійної партії й доставки.\", \"b\": [[\"Лиття пластикових виробів\", \"srv0\", \"soon\", \"0\", \"/lyttia-plastyku\"], [\"Виготовлення пресформ\", \"srv1\", \"soon\", \"1\", \"/vyhotovlennia-presform\"], [\"Наше виробництво\", \"about\", \"about\", \"\", \"/vyrobnytstvo\"]]}"], ["h2", "Від чого залежить ціна пластикового виробу"], ["ul", "<li><b>Матеріал і маса деталі</b> — вартість сировини на кожен виріб.</li><li><b>Час циклу</b> — що довше охолоджується деталь, то дорожча машинна година на одиницю.</li><li><b>Кількість гнізд у пресформі</b> — багатогніздна форма дає більше деталей за цикл.</li><li><b>Вартість пресформи та тираж</b> — на великій серії частка форми в ціні мінімальна.</li><li><b>Додаткові операції</b> — складання, маркування, пакування.</li>"], ["h2", "Типові дефекти і як їх уникають"], ["ul", "<li><b>Недолив</b> — деталь заповнена не повністю; причина в недостатньому тиску, температурі чи вентиляції форми.</li><li><b>Облой</b> — тонкий «ласт» по лінії рознімання; виникає при зношеній формі або надмірному тиску.</li><li><b>Утяжини</b> — западини на товстих ділянках; лікуються рівномірною товщиною стінок і режимом підживлення.</li><li><b>Короблення</b> — деформація після виймання через нерівномірне охолодження.</li><li><b>Сліди потоку й лінії спаю</b> — видимі смуги на поверхні; залежать від розташування ливника.</li>"], ["p", "Більшість цих проблем закладається ще на етапі конструкції, тому аналіз технологічності — не формальність."], ["h2", "Обладнання та можливості PLASTIZA"], ["p", "Наше виробництво у Львові оснащене термопластавтоматами різного зусилля змикання, що дозволяє лити як дрібні фіксатори, так і великі технічні деталі. Ми працюємо як із власними пресформами, так і з формами замовника. Більше про парк обладнання — на сторінці <a href=\"/vyrobnytstvo\" data-go=\"about\">«Виробництво»</a>."], ["h2", "Часті питання"], ["h3", "Який мінімальний тираж?"], ["p", "Залежить від виробу та пресформи. Лиття під тиском вигідне від кількох тисяч деталей; для менших обсягів підкажемо, як оптимізувати конструкцію форми."], ["h3", "Чи можна лити вироби в моїй пресформі?"], ["p", "Так. Ми перевіримо стан форми, підберемо відповідний ТПА й режими та виготовимо партію. Також можемо передати вам пресформу, виготовлену під ваш виріб."], ["h3", "Скільки часу займає запуск?"], ["p", "Найбільше часу забирає виготовлення пресформи. Після її готовності пробне лиття й погодження зразків займає від кількох днів, а серію запускаємо відразу після погодження."], ["h2", "Висновок"], ["p", "Лиття під тиском — це точність, повторюваність і низька ціна деталі на тиражі. Успіх проєкту залежить від якісного креслення, продуманої пресформи й налаштованого процесу. Надішліть нам креслення, 3D-модель або зразок — підготуємо розрахунок вартості й термінів через форму нижче."]], [["p", "Injection molding is the main technology behind most plastic parts around us, from appliance housings to construction spacers. It produces thousands of identical parts with stable geometry at a predictable price."], ["p", "Between an idea and the first production batch lie several stages: drawing review, mold design and build, trial molding, fine-tuning and only then series production. Here is how that path looks at the PLASTIZA plant in Lviv, what customers should watch for and how to save time and budget. More about the service: <a href=\"/en/injection-molding\" data-go=\"soon\" data-a=\"0\">Plastic injection molding</a>."], ["h2", "What injection molding is"], ["p", "Polymer pellets are fed into the barrel of an injection molding machine, heated and plasticised by a screw. The melt is injected under high pressure into a closed mold, fills the cavity and cools. The mold opens, ejectors push the part out and the cycle repeats."], ["p", "A cycle takes from a few seconds to a minute or more, depending on wall thickness, material and the number of cavities. Cycle time is one of the main cost drivers."], ["h2", "Advantages"], ["ul", "<li><b>Repeatability</b> — every part in a batch has the geometry set by the mold.</li><li><b>Complex shapes</b> — ribs, holes, snap-fits and threads in one cycle.</li><li><b>Low unit cost at volume</b> — mold cost is spread across the run.</li><li><b>Little waste</b> — runners and rejects are reground where the specification allows.</li><li><b>Wide material choice</b> — from flexible to engineering plastics.</li>"], ["h2", "Materials"], ["ul", "<li><b>Polypropylene (PP)</b> — light and chemically resistant, good for technical and construction parts;</li><li><b>Polyethylene (PE)</b> — flexible, resistant to moisture and low temperatures;</li><li><b>ABS</b> — rigid with a good surface, for housings and visible parts;</li><li><b>Polyamide (PA)</b> — strong and wear-resistant for loaded parts;</li><li><b>Polycarbonate (PC) and POM</b> — for precise and demanding parts.</li>"], ["p", "Colourants, UV stabilisers and fillers are added as needed and agreed in the specification."], ["h2", "Stages: from drawing to production run"], ["h3", "1. Drawing and manufacturability review"], ["p", "An engineer checks wall thickness uniformity, draft angles, radii, undercuts and gate location. At this stage we often suggest small design changes that simplify the mold and reduce rejects."], ["h3", "2. Mold design and build"], ["p", "The mold is the most expensive and critical part of the project. It is designed in 3D, approved by the customer and machined on CNC equipment. See <a href=\"/en/blog/custom-mold-checklist\" data-go=\"post\" data-a=\"4\">“Custom mold: what to prepare”</a> and our <a href=\"/en/mold-making\" data-go=\"soon\" data-a=\"1\">mold making</a> service."], ["h3", "3. Trial molding and tuning"], ["p", "First shots show how the mold behaves. The process engineer sets temperature, pressure, injection speed and cooling time; the mold is adjusted if needed."], ["h3", "4. Sample approval"], ["p", "The customer checks sample dimensions, assembly and appearance. After approval, process parameters are locked."], ["h3", "5. Series production and quality control"], ["p", "The run uses the locked settings, with dimensions and appearance checked throughout so the first and last parts match."], ["blockquote", "<p>Fixing a mistake on the drawing is cheapest, in mold steel it costs more, and in a finished batch it costs the most. That is why we spend so much time on stage one.</p>"], ["cta", "{\"t\": \"Explore our services\", \"d\": \"Full cycle in one place: from drawing and mold to production batch and delivery.\", \"b\": [[\"Injection molding\", \"srv0\", \"soon\", \"0\", \"/en/injection-molding\"], [\"Mold making\", \"srv1\", \"soon\", \"1\", \"/en/mold-making\"], [\"Our production\", \"about\", \"about\", \"\", \"/en/production\"]]}"], ["h2", "What drives the unit price"], ["ul", "<li><b>Material and part weight.</b></li><li><b>Cycle time</b> — longer cooling means more machine time per part.</li><li><b>Number of cavities</b> — more parts per cycle.</li><li><b>Mold cost versus run size</b> — on large runs the mold share is minimal.</li><li><b>Secondary operations</b> — assembly, marking, packing.</li>"], ["h2", "Common defects and how to avoid them"], ["ul", "<li><b>Short shots</b> — incomplete fill from low pressure, temperature or poor venting.</li><li><b>Flash</b> — thin fins on the parting line from wear or excess pressure.</li><li><b>Sink marks</b> — dips over thick sections; fixed by uniform walls and packing pressure.</li><li><b>Warpage</b> — distortion from uneven cooling.</li><li><b>Flow and weld lines</b> — visible streaks depending on gate position.</li>"], ["p", "Most of these are designed in, so a manufacturability review is not a formality."], ["h2", "PLASTIZA capabilities"], ["p", "Our Lviv plant runs injection molding machines with a range of clamping forces, from small spacers to large technical parts. We work with our own molds and with customer molds. More on our equipment: <a href=\"/en/production\" data-go=\"about\">Production</a>."], ["h2", "FAQ"], ["h3", "What is the minimum run?"], ["p", "It depends on the part and the mold. Injection molding usually pays off from several thousand parts; for smaller volumes we will suggest how to optimise the mold."], ["h3", "Can you mold parts in my tool?"], ["p", "Yes. We will check the mold, choose a suitable machine and settings, and produce your batch. We can also hand over a mold made for your part."], ["h3", "How long does a launch take?"], ["p", "Mold making takes the most time. Once the mold is ready, trials and sample approval take from a few days, and series production starts right after approval."], ["h2", "Conclusion"], ["p", "Injection molding means precision, repeatability and low unit cost at volume. Success depends on a good drawing, a well-designed mold and a tuned process. Send us a drawing, 3D model or sample through the form below for a price and lead-time estimate."]]], "tag": ["Виробництво", "Production"]}, {"id": 1, "st": "pub", "date": "2025-03-18", "t": ["Як обрати фіксатор арматури: види, розміри та витрата на 1 м²", "How to choose a rebar spacer: types, sizes and quantity per m²"], "e": ["Який фіксатор арматури потрібен для плити, фундаменту на ґрунті, стіни чи колони, як підібрати висоту під захисний шар бетону і скільки штук закласти на квадратний метр.", "Which rebar spacer suits a slab, a ground-bearing foundation, a wall or a column, how to size it to the concrete cover and how many to use per square metre."], "b": [[["p", "Фіксатор арматури — невелика пластикова деталь, від якої залежить, чи опиниться арматура там, де її поставив проєктувальник. Саме фіксатори тримають арматурний каркас на заданій висоті, поки по ньому ходять монтажники, поки бетон заливають із бетононасоса й ущільнюють глибинним вібратором. Якщо каркас «сів» хоча б на кілька міліметрів, конструкція втрачає захисний шар, а з ним — частину довговічності."], ["p", "На ринку десятки форм і розмірів, і через це виникає плутанина: що купувати для фундаментної плити на піщаній подушці, а що — для перекриття по профлисту чи для стіни підвалу. У цій статті розбираємо, як вибрати фіксатор арматури за типом основи та конструкції, як підібрати висоту під проєктний захисний шар і як порахувати потрібну кількість на об’єкт. Усі вироби, про які йдеться, PLASTIZA виготовляє на власному виробництві у Львові — їх можна переглянути в <a href=\"/fiksatory-armatury\" data-go=\"catalog\" data-a=\"rebar\">каталозі фіксаторів арматури</a>."], ["h2", "Навіщо потрібні пластикові фіксатори"], ["p", "Основне завдання фіксатора — забезпечити проєктну товщину захисного шару бетону, тобто відстань від поверхні конструкції до найближчого стрижня. Від неї залежить, наскільки надійно бетон захищатиме сталь від вологи, корозії та вогню. Докладно про це ми розповідаємо в статті <a href=\"/blog/zakhysnyi-shar-betonu\" data-go=\"post\" data-a=\"2\">«Захисний шар бетону: норми і як його забезпечити»</a>."], ["p", "Друге завдання — зберегти геометрію каркаса під час робіт. Арматурна сітка на перекритті витримує вагу людей, тачок, рукава бетононасоса; стіни й колони зазнають тиску свіжої бетонної суміші. Фіксатори розподіляють ці навантаження й не дають стрижням зміщуватися."], ["p", "Чому саме пластик, а не уламки цегли, бруски чи обрізки арматури, які досі трапляються на будмайданчиках:"], ["ul", "<li>пластиковий фіксатор має точну висоту, задану пресформою, — без «на око»;</li><li>він не вбирає воду й не створює в бетоні каналу, по якому волога дістанеться до арматури;</li><li>не іржавіє і не стає «містком» корозії, як металеві підкладки;</li><li>встановлюється за секунди, а ажурна форма дозволяє бетону щільно обтікати виріб.</li>"], ["blockquote", "<p>Фіксатор коштує в сотні разів менше, ніж ремонт конструкції, у якій арматура опинилася біля самої поверхні. Тому економити на кількості фіксаторів — найдорожча економія на об’єкті.</p>"], ["h2", "Від чого залежить вибір фіксатора"], ["p", "Перш ніж обирати конкретну модель, дайте відповідь на кілька запитань. Вони одразу звужують вибір до одного-двох варіантів:"], ["ul", "<li><b>Яка основа?</b> Сипка (ґрунт, пісок, щебінь, гідроізоляційна плівка) чи тверда (бетонна підготовка, плита, опалубка).</li><li><b>Як розташована арматура?</b> Горизонтально — у плитах, стяжках, підлогах; вертикально — у стінах, колонах, пілонах.</li><li><b>Який проєктний захисний шар?</b> Його беруть із креслень: 15, 20, 25, 30, 40, 50 мм і більше.</li><li><b>Який діаметр стрижнів?</b> Це важливо для фіксаторів, що надягаються на стрижень або защіпаються на нього.</li><li><b>Яке навантаження?</b> Важкий каркас фундаментної плити й легка сітка стяжки потребують різної опори.</li>"], ["h2", "Фіксатори для горизонтальної арматури"], ["h3", "«Настил» — для ґрунту, піску, щебеню й плівки"], ["p", "<a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">Фіксатор «Настил»</a> створений для сипкої та м’якої основи. Його головна особливість — збільшена площа опори: виріб не продавлює пісок чи утеплювач і не рве гідроізоляційну мембрану. Саме його обирають для фундаментних плит, плит на ґрунті, підлог по підготовці зі щебеню. Доступні висоти — від 25–30 до 90–100 мм, тож «Настил» закриває і звичайні, і збільшені захисні шари фундаментів."], ["h3", "«Стійка» — для плит і підлог на твердій основі"], ["p", "<a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">Фіксатор «Стійка»</a> тримає горизонтальну арматуру на бетонній або іншій твердій поверхні: у плитах перекриття, стяжках, промислових підлогах. Конструкція рівномірно розподіляє вагу каркаса. Частина типорозмірів багаторівнева — наприклад, 20-25-30: один виріб дає три висоти залежно від того, як його поставити. Це зручно, коли на об’єкті потрібні різні захисні шари."], ["h3", "«Защіпка» і «Засувка» — фіксація на стрижні"], ["p", "<a href=\"/fiksator-zashchipka\" data-go=\"product\" data-a=\"4-0\">«Защіпка»</a> защіпається на арматуру й утримує її на твердій основі; типорозміри 15/10, 20/10 і 25/10, де перше число — висота захисного шару в міліметрах. <a href=\"/fiksator-zasuvka\" data-go=\"product\" data-a=\"5-0\">«Засувка»</a> розрахована на більші навантаження й діаметри: розмір 50/8-24 означає захисний шар 50 мм для стрижнів від 8 до 24 мм. Такі фіксатори не зсуваються зі свого місця, навіть коли по сітці активно ходять."], ["cta", "{\"t\": \"Не знаєте, який фіксатор підійде?\", \"d\": \"Надішліть креслення або специфікацію — підберемо модель, висоту й кількість під ваш проєкт.\", \"b\": [[\"Каталог фіксаторів\", \"cat_rebar\", \"catalog\", \"rebar\", \"/fiksatory-armatury\"], [\"Запросити розрахунок\", \"rfq\"]]}"], ["h2", "Фіксатори для вертикальних конструкцій"], ["h3", "«Зірочка» — для стін, колон і пілонів"], ["p", "<a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">Фіксатор «Зірочка»</a> надягається на вертикальний стрижень і впирається в щит опалубки по колу, тому захисний шар однаковий з будь-якого боку. Під час монтажу опалубки «колесо» прокочується по щиту, не чіпляючись за нього. Розміри від 15/6-12 до 50/12-20: перше число — захисний шар, далі — діапазон діаметрів арматури. Еластичний замок надійно тримається на стрижнях різної товщини."], ["p", "«Зірочку» також використовують у кутах і на бічних гранях горизонтальних каркасів — скрізь, де арматура має триматися на відстані від вертикальної опалубки."], ["h2", "Як підібрати висоту фіксатора"], ["p", "Висота фіксатора — це не «приблизно», а конкретне значення з проєкту. Діяти варто в такому порядку:"], ["ol", "<li>Знайдіть у кресленнях проєктну товщину захисного шару для кожного елемента: фундаменту, перекриття, стін.</li><li>Пам’ятайте, що шар відраховують від поверхні бетону до найближчого стрижня — часто це хомут або поперечна арматура, а не робочий стрижень.</li><li>Підберіть фіксатор, висота якого дорівнює цьому значенню. Якщо точного розміру немає, беріть найближчий більший, але не менший.</li><li>Для «Зірочки» й «Засувки» перевірте, чи входить діаметр вашої арматури в діапазон виробу.</li><li>Для верхньої сітки плити фіксатори захисного шару не підходять — її тримають окремі підставки або каркаси, розраховані на висоту між сітками.</li>"], ["h2", "Скільки фіксаторів потрібно на 1 м²"], ["p", "Для горизонтальної арматури орієнтовна витрата — 4–6 шт. на м². Що тонші стрижні й що більший крок сітки, то частіше ставлять фіксатори: тонка арматура прогинається між опорами. Для масивних каркасів із великим діаметром стрижнів крок можна збільшити."], ["p", "Для стін і колон «Зірочки» розставляють у шаховому порядку, приблизно через кожен метр по висоті й довжині, з кожного боку стіни. Обов’язково — біля країв, отворів і в місцях з’єднання каркасів."], ["p", "Приклад розрахунку: фундаментна плита площею 120 м², витрата 5 шт./м² — це 600 фіксаторів «Настил». Додайте запас 5–10 % на підрізку й втрати — і отримаєте 650–660 шт. Фіксатори PLASTIZA постачаються упаковками від 100 до 2000 шт., точне фасування вказане в картці кожного товару."], ["h2", "Типові помилки під час вибору та монтажу"], ["ul", "<li>Ставлять «Стійку» на пісок або утеплювач — фіксатор продавлює основу, і шар зменшується.</li><li>Обирають висоту «трохи меншу», бо потрібної немає на складі, — і закладають дефект у конструкцію.</li><li>Економлять на кількості: між рідкими опорами сітка прогинається під ногами.</li><li>Підбирають «Зірочку» не під той діаметр — вона сповзає або не надягається.</li><li>Не перевіряють каркас перед бетонуванням. Кілька хвилин з рулеткою вберігають від місяців ремонту.</li>"], ["h2", "Часті питання"], ["h3", "Чи можна використовувати один фіксатор для різних висот?"], ["p", "Так, частина моделей «Стійка» багаторівнева: залежно від положення виробу він дає дві або три висоти. Це зменшує кількість позицій у замовленні."], ["h3", "Чи витримують пластикові фіксатори вагу людей і бетону?"], ["p", "Так, якщо їх правильно підібрано й розставлено з потрібним кроком. Фіксатори розраховані на тиск арматурного каркаса та ходіння по сітці під час робіт."], ["h3", "Чи не стає фіксатор слабким місцем у бетоні?"], ["p", "Ні. Його переріз малий порівняно з конструкцією, а ажурна форма дає бетону щільно заповнити простір навколо. Пластик не вбирає воду й не іржавіє, тому не створює шляху для корозії."], ["h2", "Висновок"], ["p", "Правильний фіксатор арматури підбирають за трьома параметрами: основа, положення стрижнів і проєктний захисний шар. «Настил» — для сипкої основи, «Стійка», «Защіпка» й «Засувка» — для твердої, «Зірочка» — для вертикальних елементів. Якщо сумніваєтеся, надішліть нам специфікацію: менеджер підбере моделі, розрахує кількість і запропонує доставку зі складу у Львові або Києві — <a href=\"/dostavka\" data-go=\"delivery\">умови доставки</a>."]], [["p", "A rebar spacer is a small plastic part that decides whether reinforcement ends up where the designer put it. Spacers hold the cage at the specified height while workers walk on it, while concrete is pumped in and while it is compacted with a poker vibrator. If the cage sinks even a few millimetres, the structure loses part of its concrete cover — and part of its service life."], ["p", "There are dozens of shapes and sizes on the market, which causes confusion: what to buy for a raft on a sand bed, for a slab on decking or for a basement wall. This article explains how to choose a rebar spacer by base and element type, how to match its height to the design cover and how to work out the quantity for a site. Every product mentioned is made by PLASTIZA at our own plant in Lviv — see the <a href=\"/en/rebar-spacers\" data-go=\"catalog\" data-a=\"rebar\">rebar spacer catalog</a>."], ["h2", "Why plastic spacers are used"], ["p", "The main job of a spacer is to provide the design concrete cover — the distance from the surface of the element to the nearest bar. It determines how well concrete protects steel from moisture, corrosion and fire. We cover this in detail in <a href=\"/en/blog/concrete-cover\" data-go=\"post\" data-a=\"2\">“Concrete cover: requirements and how to achieve it”</a>."], ["p", "The second job is to keep the cage geometry during works. A slab mesh carries people, barrows and the pump hose; walls and columns take the pressure of fresh concrete. Spacers spread these loads and stop the bars from moving."], ["p", "Why plastic rather than broken bricks, timber offcuts or rebar scraps that still appear on sites:"], ["ul", "<li>a plastic spacer has an exact height set by the mold — no guesswork;</li><li>it does not absorb water or create a channel for moisture to reach the steel;</li><li>it does not rust or form a corrosion bridge like metal chairs;</li><li>it installs in seconds, and its open shape lets concrete flow tightly around it.</li>"], ["blockquote", "<p>A spacer costs hundreds of times less than repairing an element whose rebar ended up next to the surface. Saving on the number of spacers is the most expensive saving on site.</p>"], ["h2", "What the choice depends on"], ["p", "Answer a few questions first — they narrow the choice to one or two models:"], ["ul", "<li><b>What is the base?</b> Loose (soil, sand, gravel, membrane) or firm (blinding concrete, slab, formwork).</li><li><b>How is the rebar positioned?</b> Horizontally — slabs, screeds, floors; vertically — walls, columns, piers.</li><li><b>What is the design cover?</b> Taken from the drawings: 15, 20, 25, 30, 40, 50 mm or more.</li><li><b>What bar diameter?</b> Important for spacers that clip onto or slide over the bar.</li><li><b>What load?</b> A heavy raft cage and a light screed mesh need different support.</li>"], ["h2", "Spacers for horizontal rebar"], ["h3", "“Nastil” — for soil, sand, gravel and membranes"], ["p", "The <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil” slab chair</a> is designed for loose and soft bases. Its wide footprint does not punch into sand or insulation and does not tear waterproofing membranes. It is the usual choice for raft foundations, slabs on grade and floors on a gravel bed. Heights range from 25–30 to 90–100 mm, covering both standard and increased foundation covers."], ["h3", "“Stiika” — for slabs and floors on a firm base"], ["p", "The <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika” chair</a> holds horizontal rebar on concrete or another firm surface: floor slabs, screeds, industrial floors. It spreads the weight of the cage evenly. Some sizes are multi-level — for example 20-25-30: one part gives three heights depending on how it is placed, which is handy when a site needs several covers."], ["h3", "“Zashchipka” and “Zasuvka” — clip-on spacers"], ["p", "<a href=\"/en/clip-spacer-zashchipka\" data-go=\"product\" data-a=\"4-0\">“Zashchipka”</a> clips onto the bar and holds it on a firm base; sizes 15/10, 20/10 and 25/10, where the first number is the cover in millimetres. <a href=\"/en/slide-spacer-zasuvka\" data-go=\"product\" data-a=\"5-0\">“Zasuvka”</a> is designed for heavier loads and diameters: size 50/8-24 means 50 mm cover for bars from 8 to 24 mm. These spacers stay in place even with heavy foot traffic on the mesh."], ["cta", "{\"t\": \"Not sure which spacer fits?\", \"d\": \"Send us a drawing or schedule — we will pick the model, height and quantity for your project.\", \"b\": [[\"Rebar spacers\", \"cat_rebar\", \"catalog\", \"rebar\", \"/en/rebar-spacers\"], [\"Request a quote\", \"rfq\"]]}"], ["h2", "Spacers for vertical elements"], ["h3", "“Zirochka” — for walls, columns and piers"], ["p", "The <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka” wheel spacer</a> clips onto a vertical bar and bears against the formwork all around, so the cover is equal on every side. When the formwork is closed, the wheel rolls along the panel instead of snagging. Sizes run from 15/6-12 to 50/12-20: the first number is the cover, then the range of bar diameters. The flexible lock holds firmly on bars of different thickness."], ["p", "“Zirochka” is also used at corners and side faces of horizontal cages — anywhere rebar must stay clear of vertical formwork."], ["h2", "How to choose the spacer height"], ["p", "Spacer height is not “roughly” — it is a specific value from the design:"], ["ol", "<li>Find the design cover for each element in the drawings: foundation, slab, walls.</li><li>Remember that cover is measured to the nearest bar — often a link or distribution bar, not the main bar.</li><li>Choose a spacer equal to that value. If the exact size is unavailable, go up, never down.</li><li>For “Zirochka” and “Zasuvka”, check that your bar diameter is within the part’s range.</li><li>Cover spacers are not for the top mesh of a slab — it needs separate supports sized to the distance between meshes.</li>"], ["h2", "How many spacers per m²"], ["p", "For horizontal rebar, allow roughly 4–6 pcs per m². The thinner the bars and the wider the mesh, the closer the spacing — thin bars sag between supports. Heavy cages with large bars allow wider spacing."], ["p", "For walls and columns, place “Zirochka” spacers in a staggered pattern about every metre in height and length, on each face — and always near edges, openings and cage joints."], ["p", "Example: a 120 m² raft at 5 pcs/m² needs 600 “Nastil” spacers. Add 5–10 % for waste and you get 650–660 pcs. PLASTIZA spacers come in packs of 100 to 2,000 pcs; the exact pack size is shown on each product page."], ["h2", "Common mistakes"], ["ul", "<li>Using “Stiika” on sand or insulation — it punches into the base and the cover shrinks.</li><li>Choosing a slightly lower height because the right one is out of stock — building a defect into the structure.</li><li>Saving on quantity — the mesh sags underfoot between sparse supports.</li><li>Picking a “Zirochka” for the wrong diameter — it slides off or does not fit.</li><li>Skipping the pre-pour check. A few minutes with a tape measure save months of repairs.</li>"], ["h2", "FAQ"], ["h3", "Can one spacer serve several heights?"], ["p", "Yes, some “Stiika” models are multi-level and give two or three heights depending on orientation, which reduces the number of line items."], ["h3", "Can plastic spacers carry people and concrete?"], ["p", "Yes, when correctly chosen and spaced. They are designed for the weight of the cage and foot traffic during works."], ["h3", "Does a spacer become a weak point in concrete?"], ["p", "No. Its cross-section is tiny compared to the element, and its open shape lets concrete fill the space around it. Plastic does not absorb water or rust, so it creates no corrosion path."], ["h2", "Conclusion"], ["p", "The right rebar spacer depends on three things: the base, the bar position and the design cover. “Nastil” for loose bases; “Stiika”, “Zashchipka” and “Zasuvka” for firm ones; “Zirochka” for vertical elements. If in doubt, send us your schedule: we will pick the models, calculate quantities and ship from our Lviv or Kyiv warehouse — see <a href=\"/en/delivery\" data-go=\"delivery\">delivery options</a>."]]], "tag": ["Поради", "Guides"]}, {"id": 2, "st": "pub", "date": "2025-02-11", "t": ["Захисний шар бетону: що це, норми та як його забезпечити на об’єкті", "Concrete cover: what it is, typical values and how to achieve it on site"], "e": ["Що таке захисний шар бетону, від чого залежить його товщина, чим загрожують помилки і як пластикові фіксатори допомагають витримати проєктне значення.", "What concrete cover is, what determines its thickness, what goes wrong when it is too thin or too thick, and how plastic spacers help you hit the design value."], "b": [[["p", "Захисний шар бетону — один із тих параметрів, які непомітні в готовій будівлі, але визначають, скільки вона прослужить. Це відстань від поверхні бетону до найближчої арматури. Кілька міліметрів різниці здаються дрібницею під час бетонування, а через роки перетворюються на іржаві патьоки, тріщини й відшарування бетону."], ["p", "У цій статті пояснюємо, навіщо потрібен захисний шар, від чого залежить його товщина, які орієнтовні значення використовують для типових конструкцій, що відбувається, коли шар порушено, і як забезпечити його на будмайданчику за допомогою <a href=\"/fiksatory-armatury\" data-go=\"catalog\" data-a=\"rebar\">фіксаторів арматури</a>."], ["h2", "Що таке захисний шар бетону"], ["p", "Захисний шар — це товщина бетону між зовнішньою поверхнею конструкції та поверхнею найближчого арматурного стрижня. Важливо: найближчим часто є не робоча арматура, а хомути, поперечні стрижні чи монтажні елементи. Саме до них і ведуть відлік."], ["p", "У проєкті зазвичай вказують номінальне значення — те, яке потрібно витримати під час монтажу. Воно вже містить запас на неминучі відхилення при виготовленні каркаса."], ["h2", "Навіщо потрібен захисний шар"], ["p", "Бетон — це не лише «обгортка» для арматури. Він виконує кілька функцій одночасно:"], ["ul", "<li><b>Захист від корозії.</b> Свіжий бетон має сильно лужне середовище, у якому сталь вкривається пасивною плівкою й не іржавіє. З роками вуглекислий газ із повітря поступово нейтралізує бетон від поверхні вглиб — це карбонізація. Поки фронт карбонізації не дійшов до арматури, вона захищена.</li><li><b>Вогнестійкість.</b> Під час пожежі бетон уповільнює нагрівання сталі. Тонкий шар — це швидша втрата міцності арматури.</li><li><b>Спільна робота бетону й арматури.</b> Для зчеплення та анкерування стрижень має бути повністю оточений бетоном достатньої товщини.</li><li><b>Довговічність загалом.</b> Волога, солі, агресивні ґрунтові води — усе це має пройти крізь захисний шар, перш ніж дістанеться до металу.</li>"], ["blockquote", "<p>Арматура в бетоні не іржавіє доти, доки її захищає лужне середовище. Захисний шар — це запас часу, за який агресивні чинники мають пройти шлях до сталі.</p>"], ["h2", "Від чого залежить товщина захисного шару"], ["p", "Мінімальну й номінальну товщину визначає проєктувальник на підставі норм — в Україні це, зокрема, ДБН В.2.6-98:2009 «Бетонні та залізобетонні конструкції» та ДСТУ Б В.2.6-156:2010, у європейській практиці — EN 1992-1-1 (Єврокод 2). Основні чинники:"], ["ul", "<li><b>Умови експлуатації.</b> Сухе приміщення, вулиця, контакт із ґрунтом, вода, солі — що агресивніше середовище, то товщий шар.</li><li><b>Тип конструкції.</b> Плити, балки, колони, фундаменти мають різні вимоги.</li><li><b>Діаметр арматури.</b> Шар не може бути меншим за діаметр стрижня.</li><li><b>Вимоги до вогнестійкості.</b> Для конструкцій із нормованою межею вогнестійкості шар збільшують.</li><li><b>Наявність підготовки під фундамент.</b> Бетонування прямо на ґрунт вимагає значно більшого шару.</li>"], ["h3", "Орієнтовні значення для типових конструкцій"], ["p", "Щоб зорієнтуватися в порядку цифр, наведемо значення, які найчастіше трапляються в проєктах житлових і громадських будівель:"], ["ul", "<li>плити перекриття та внутрішні стіни в сухих приміщеннях — близько 15–25 мм;</li><li>балки, ригелі та колони — близько 20–30 мм;</li><li>конструкції на відкритому повітрі та у вологих умовах — 30–40 мм і більше;</li><li>фундаменти з бетонною підготовкою — від 35–40 мм;</li><li>фундаменти, які бетонують безпосередньо на ґрунт, без підготовки, — від 70 мм.</li>"], ["p", "Це лише орієнтир для розуміння. Для конкретного об’єкта значення завжди беруть із проєкту: саме воно враховує клас бетону, середовище й вимоги до вогнестійкості."], ["h2", "Чим загрожує порушення захисного шару"], ["h3", "Занадто тонкий шар"], ["p", "Карбонізація й волога швидше доходять до сталі. Арматура починає іржавіти, а продукти корозії займають у кілька разів більший об’єм, ніж метал. Вони розпирають бетон зсередини: з’являються тріщини вздовж стрижнів, рудий наліт, згодом — відколи й оголена арматура. Окрім того, знижується вогнестійкість і погіршується анкерування стрижнів."], ["h3", "Занадто товстий шар"], ["p", "Перебір теж шкодить. Якщо нижня арматура плити піднялася вище за проєкт, зменшується робоча висота перерізу — і несна здатність падає. Товстий шар без армування схильний до тріщиноутворення, а конструкція стає важчою, ніж розраховано."], ["h2", "Чому захисний шар порушується на будмайданчику"], ["p", "Більшість проблем виникає не в проєкті, а під час монтажу:"], ["ul", "<li>каркас кладуть на уламки цегли, дерев’яні бруски чи камені — висота довільна, а дерево ще й вбирає воду;</li><li>фіксаторів ставлять занадто мало, і сітка прогинається під вагою людей;</li><li>фіксатори обирають «приблизно» за висотою;</li><li>на сипкій основі використовують опори з малою площею — вони тонуть у піску;</li><li>під час вібрування й подачі бетону каркас зміщується, бо не закріплений.</li>"], ["h2", "Як забезпечити проєктний захисний шар"], ["p", "Надійний спосіб — пластикові фіксатори заводського виготовлення, підібрані під конкретний елемент. Порядок дій:"], ["ol", "<li>Візьміть із проєкту значення захисного шару для кожного типу конструкцій.</li><li>Підберіть тип фіксатора під основу й положення арматури: <a href=\"/fiksator-nastyl\" data-go=\"product\" data-a=\"1-0\">«Настил»</a> — для ґрунту, піску та плівки; <a href=\"/fiksator-stiika\" data-go=\"product\" data-a=\"2-0\">«Стійка»</a> і <a href=\"/fiksator-zashchipka\" data-go=\"product\" data-a=\"4-0\">«Защіпка»</a> — для твердої основи; <a href=\"/fiksator-zirochka\" data-go=\"product\" data-a=\"3-0\">«Зірочка»</a> — для стін і колон.</li><li>Підберіть висоту, що точно відповідає проєктному шару.</li><li>Розставте фіксатори з потрібним кроком — для горизонтальної арматури в середньому 4–6 шт. на м². Як порахувати точніше, розповідаємо в статті <a href=\"/blog/yak-obraty-fiksator-armatury\" data-go=\"post\" data-a=\"1\">«Як обрати фіксатор арматури»</a>.</li><li>Перед бетонуванням перевірте каркас: виміряйте відстань до опалубки й основи в кількох точках, особливо біля країв і отворів.</li>"], ["cta", "{\"t\": \"Потрібні фіксатори під ваш проєктний шар?\", \"d\": \"Підберемо модель і висоту для кожного елемента та порахуємо кількість на об’єкт.\", \"b\": [[\"Фіксатори арматури\", \"cat_rebar\", \"catalog\", \"rebar\", \"/fiksatory-armatury\"], [\"Обговорити замовлення\", \"rfq\"]]}"], ["h2", "Як перевірити захисний шар"], ["p", "До бетонування шар контролюють рулеткою або шаблоном — це найпростіше й найдешевше. Після бетонування його можна перевірити неруйнівним методом: магнітні прилади (вимірювачі захисного шару) визначають відстань до арматури крізь бетон. Таку перевірку проводять під час приймання робіт або обстеження будівель."], ["h2", "Часті питання"], ["h3", "Чи можна виправити тонкий захисний шар після бетонування?"], ["p", "Частково — ремонтними складами, торкретуванням, захисними покриттями. Але це дорожче й менш надійно, ніж правильно встановити фіксатори до заливання."], ["h3", "Чи враховують фіксатори в захисному шарі?"], ["p", "Фіксатор лише утримує арматуру на потрібній відстані. Його висота має дорівнювати проєктному шару, а сам виріб залишається в бетоні й не впливає на довговічність."], ["h3", "Скільки коштує забезпечити захисний шар?"], ["p", "Вартість фіксаторів для типової плити — незначна частка кошторису бетонних робіт. Точну суму розрахуємо за вашою специфікацією."], ["h2", "Висновок"], ["p", "Захисний шар бетону — це гарантія того, що арматура працюватиме десятиліттями. Його значення задає проєкт, а витримати його на об’єкті допомагають правильно підібрані фіксатори. Якщо потрібна консультація щодо вибору або розрахунок кількості — залиште заявку нижче, і менеджер PLASTIZA зв’яжеться з вами."]], [["p", "Concrete cover is one of those parameters you cannot see in a finished building, yet it decides how long the building lasts. It is the distance from the concrete surface to the nearest reinforcement. A few millimetres seem trivial during the pour, but years later they turn into rust stains, cracks and spalling."], ["p", "This article explains why cover matters, what determines its thickness, which values are typical for common elements, what happens when it is wrong and how to achieve it on site with <a href=\"/en/rebar-spacers\" data-go=\"catalog\" data-a=\"rebar\">rebar spacers</a>."], ["h2", "What concrete cover is"], ["p", "Cover is the thickness of concrete between the outer face of an element and the surface of the nearest bar. The nearest bar is often a link, stirrup or distribution bar rather than the main reinforcement — and cover is measured to it."], ["p", "Drawings usually state the nominal cover: the value to achieve during fixing. It already includes an allowance for unavoidable deviations."], ["h2", "Why cover matters"], ["ul", "<li><b>Corrosion protection.</b> Fresh concrete is highly alkaline, so steel forms a passive film and does not rust. Over the years carbon dioxide neutralises concrete from the surface inwards — carbonation. Until the carbonation front reaches the steel, the bars are protected.</li><li><b>Fire resistance.</b> In a fire, concrete slows the heating of steel. A thin cover means faster loss of strength.</li><li><b>Bond and anchorage.</b> Bars must be fully surrounded by enough concrete to work together with it.</li><li><b>Durability in general.</b> Moisture, salts and aggressive groundwater must pass through the cover before reaching the metal.</li>"], ["blockquote", "<p>Rebar in concrete does not rust while the alkaline environment protects it. Cover is the time it takes aggressive agents to travel to the steel.</p>"], ["h2", "What determines cover thickness"], ["p", "Minimum and nominal values are set by the designer under the applicable codes — in Ukraine, DBN V.2.6-98:2009 and DSTU B V.2.6-156:2010; in European practice, EN 1992-1-1 (Eurocode 2). Key factors:"], ["ul", "<li><b>Exposure conditions:</b> dry interior, outdoors, contact with soil, water or salts.</li><li><b>Element type:</b> slabs, beams, columns and foundations differ.</li><li><b>Bar diameter:</b> cover may not be less than the bar diameter.</li><li><b>Fire resistance requirements.</b></li><li><b>Blinding under foundations:</b> casting directly against soil needs much more cover.</li>"], ["h3", "Typical values for common elements"], ["p", "To give a sense of scale, these values are often seen in residential and public buildings:"], ["ul", "<li>floor slabs and internal walls in dry rooms — about 15–25 mm;</li><li>beams and columns — about 20–30 mm;</li><li>outdoor and wet elements — 30–40 mm or more;</li><li>foundations on blinding — from 35–40 mm;</li><li>foundations cast directly against soil — from 70 mm.</li>"], ["p", "These are orientation figures only. For a real project, always take the value from the design."], ["h2", "What goes wrong"], ["h3", "Cover too thin"], ["p", "Carbonation and moisture reach the steel sooner. Rust occupies several times the volume of the metal and bursts the concrete from inside: cracks along the bars, rust stains, later spalling and exposed rebar. Fire resistance and anchorage also suffer."], ["h3", "Cover too thick"], ["p", "If the bottom rebar of a slab sits higher than designed, the effective depth falls — and so does load capacity. Thick unreinforced cover is prone to cracking and adds weight."], ["h2", "Why cover fails on site"], ["ul", "<li>cages are laid on bricks, timber or stones — random heights, and timber absorbs water;</li><li>too few spacers, so the mesh sags under foot traffic;</li><li>spacer heights chosen “roughly”;</li><li>small-footprint supports used on loose bases sink into sand;</li><li>the cage moves during vibration and pumping because it is not secured.</li>"], ["h2", "How to achieve the design cover"], ["ol", "<li>Take the cover for each element type from the drawings.</li><li>Choose the spacer type for the base and bar position: <a href=\"/en/slab-chair-nastil\" data-go=\"product\" data-a=\"1-0\">“Nastil”</a> for soil, sand and membranes; <a href=\"/en/rebar-chair-stiika\" data-go=\"product\" data-a=\"2-0\">“Stiika”</a> and <a href=\"/en/clip-spacer-zashchipka\" data-go=\"product\" data-a=\"4-0\">“Zashchipka”</a> for firm bases; <a href=\"/en/star-spacer-zirochka\" data-go=\"product\" data-a=\"3-0\">“Zirochka”</a> for walls and columns.</li><li>Choose the height that exactly matches the design cover.</li><li>Space them correctly — on average 4–6 pcs per m² for horizontal rebar. See <a href=\"/en/blog/how-to-choose-rebar-spacer\" data-go=\"post\" data-a=\"1\">“How to choose a rebar spacer”</a> for details.</li><li>Check the cage before pouring at several points, especially near edges and openings.</li>"], ["cta", "{\"t\": \"Need spacers for your design cover?\", \"d\": \"We will pick the model and height for each element and calculate quantities for the site.\", \"b\": [[\"Rebar spacers\", \"cat_rebar\", \"catalog\", \"rebar\", \"/en/rebar-spacers\"], [\"Discuss an order\", \"rfq\"]]}"], ["h2", "How to check cover"], ["p", "Before the pour, use a tape measure or template — the cheapest check. After the pour, magnetic cover meters measure the distance to rebar through concrete without damage; they are used at handover and in building surveys."], ["h2", "FAQ"], ["h3", "Can thin cover be fixed after pouring?"], ["p", "Partly — with repair mortars, sprayed concrete or protective coatings. It is costlier and less reliable than fitting spacers correctly before the pour."], ["h3", "Is the spacer part of the cover?"], ["p", "The spacer only holds the bar at the right distance. Its height equals the design cover; it stays in the concrete and does not affect durability."], ["h3", "How much does it cost to ensure cover?"], ["p", "Spacers for a typical slab are a tiny share of the concrete works budget. We will price your schedule exactly."], ["h2", "Conclusion"], ["p", "Concrete cover is what lets rebar work for decades. The design sets the value; correctly chosen spacers let you achieve it on site. For advice or a quantity estimate, leave a request below and a PLASTIZA manager will contact you."]]], "tag": ["Будівництво", "Construction"]}], "faqs": [{"c": "gen", "q": {"uk": "Як замовити фіксатори арматури оптом і отримати розрахунок вартості?", "en": "How do I order rebar spacers wholesale and get a price quote?"}, "a": {"uk": "Залиште заявку на сайті, зателефонуйте або напишіть на email чи в месенджер. Вкажіть потрібні фіксатори, розміри та кількість упаковок або прикріпіть специфікацію, кошторис чи креслення — менеджер у робочий час підготує комерційну пропозицію з цінами виробника та термінами відвантаження.", "en": "Send a request on the website, call us or write by email or messenger. List the spacers, sizes and number of packs, or attach a specification, bill of quantities or drawing — during working hours a manager will send a quote with manufacturer prices and shipping dates."}, "on": true}, {"c": "gen", "q": {"uk": "Ви виробник фіксаторів чи посередник?", "en": "Are you a rebar spacer manufacturer or a reseller?"}, "a": {"uk": "PLASTIZA — український виробник пластикових фіксаторів арматури та елементів для опалубки з власним виробництвом у Львові. Ви купуєте напряму від виробника, без націнок посередників, і отримуєте однакову якість кожної партії.", "en": "PLASTIZA is a Ukrainian manufacturer of plastic rebar spacers and formwork accessories with its own production in Lviv. You buy directly from the factory, with no reseller mark-up and consistent quality in every batch."}, "on": true}, {"c": "gen", "q": {"uk": "Чи працюєте ви з юридичними особами та ФОП?", "en": "Do you work with companies and sole traders?"}, "a": {"uk": "Так. Постачаємо фіксатори будівельним компаніям, забудовникам, підрядникам, магазинам будматеріалів і виробникам. До кожного відвантаження надаємо рахунок, видаткову накладну й ТТН для безготівкового розрахунку.", "en": "Yes. We supply contractors, developers, building-material stores and manufacturers. Every shipment comes with an invoice, delivery note and waybill for bank-transfer payment."}, "on": true}, {"c": "gen", "q": {"uk": "Де купити фіксатори арматури у Львові та Києві?", "en": "Where can I buy rebar spacers in Lviv and Kyiv?"}, "a": {"uk": "Офіси та склади PLASTIZA працюють у Львові (вул. Шевченка, 154) і Києві (пров. Ю. Матущака, 18). Ходові позиції є в наявності: замовлення можна забрати самовивозом або отримати доставкою по Україні. Візит радимо заздалегідь погодити з менеджером телефоном.", "en": "PLASTIZA has offices and warehouses in Lviv (154 Shevchenka St.) and Kyiv (18 Yu. Matushchaka Ln.). Fast-moving items are in stock for pickup or delivery across Ukraine. Please arrange your visit with a manager by phone in advance."}, "on": true}, {"c": "prod", "q": {"uk": "Як обрати фіксатор арматури для плити, фундаменту чи стіни?", "en": "Which rebar spacer do I need for a slab, foundation or wall?"}, "a": {"uk": "Вибір залежить від основи та положення арматури. «Настил» — для фундаментних плит і плит на ґрунті, піску чи плівці; «Стійка», «Защіпка» й «Засувка» — для плит перекриття, стяжок і підлог на твердій основі; «Зірочка» — для стін, колон і пілонів. Висоту підбирають під проєктний захисний шар бетону — менеджер допоможе з вибором.", "en": "It depends on the base and bar position. “Nastil” suits rafts and slabs on soil, sand or membrane; “Stiika”, “Zashchipka” and “Zasuvka” suit floor slabs, screeds and floors on a firm base; “Zirochka” wheel spacers suit walls, columns and piers. The height is matched to the design concrete cover — a manager will help you choose."}, "on": true}, {"c": "prod", "q": {"uk": "Як підібрати висоту фіксатора під захисний шар бетону?", "en": "How do I choose the spacer height for the concrete cover?"}, "a": {"uk": "Висота фіксатора має дорівнювати проєктній товщині захисного шару з креслень — 15, 20, 25, 30, 40, 50 мм і більше. Якщо точного розміру немає, беруть найближчий більший, але не менший. Для «Зірочки» й «Засувки» також перевіряють, чи підходить діаметр арматури.", "en": "The spacer height should equal the design concrete cover shown in the drawings — 15, 20, 25, 30, 40, 50 mm or more. If the exact size is not available, go one size up, never down. For “Zirochka” and “Zasuvka”, also check the bar diameter range."}, "on": true}, {"c": "prod", "q": {"uk": "Скільки фіксаторів арматури потрібно на 1 м²?", "en": "How many rebar spacers are needed per m²?"}, "a": {"uk": "Для горизонтальної арматури орієнтовна витрата — 4–6 шт. на м² залежно від діаметра й кроку стрижнів та навантаження. «Зірочки» на стінах і колонах ставлять у шаховому порядку приблизно через кожен метр з кожного боку. Закладіть запас 5–10 %, а для точного розрахунку надішліть креслення чи специфікацію.", "en": "For horizontal rebar, allow roughly 4–6 pcs per m² depending on bar diameter, spacing and load. “Zirochka” spacers on walls and columns go in a staggered pattern about every metre on each face. Add 5–10 % reserve, and send a drawing or schedule for an exact estimate."}, "on": true}, {"c": "prod", "q": {"uk": "Яка мінімальна партія і як фасуються фіксатори?", "en": "What is the minimum order and how are spacers packed?"}, "a": {"uk": "Фіксатори постачаємо упаковками від 100 до 2000 шт. залежно від виробу та розміру — точне фасування вказане в картці кожного товару. Дистанційну трубу відпускаємо метрами. Обсяг для нестандартних виробів погоджуємо індивідуально.", "en": "Spacers come in packs of 100 to 2,000 pcs depending on the item and size — the exact pack size is on each product page. Spacer tube is sold by the metre. Volumes for custom parts are agreed individually."}, "on": true}, {"c": "prod", "q": {"uk": "Чи є в наявності конуси, корки та дистанційні труби для опалубки?", "en": "Do you have formwork cones, plugs and spacer tubes in stock?"}, "a": {"uk": "Так. Пропонуємо конус для труби 22 мм, корок і корок-ялинку діаметром 24 мм, а також дистанційну трубу з поліетилену або ПВХ, яку відпускаємо метрами. Ходові позиції є на складах у Львові та Києві — підберемо комплект під вашу систему опалубки.", "en": "Yes. We offer cones for 22 mm tube, 24 mm plugs and fir-tree plugs, and PE or PVC spacer tube sold by the metre. Fast-moving items are in stock in Lviv and Kyiv — we will put together a set for your formwork system."}, "on": true}, {"c": "prod", "q": {"uk": "Чому пластикові фіксатори кращі за цеглу чи бруски?", "en": "Why are plastic spacers better than bricks or timber?"}, "a": {"uk": "Пластиковий фіксатор має точну висоту, не вбирає воду й не іржавіє, тому не створює в бетоні шляхів для корозії арматури. Ажурна форма дозволяє бетону щільно обтікати виріб, а монтаж займає секунди. Уламки цегли й дерева дають довільну висоту і з часом руйнують захисний шар.", "en": "A plastic spacer has an exact height, does not absorb water and does not rust, so it creates no corrosion path to the rebar. Its open shape lets concrete flow tightly around it, and it installs in seconds. Brick and timber offcuts give random heights and damage the concrete cover over time."}, "on": true}, {"c": "prod", "q": {"uk": "Чи надаєте ви документи якості на продукцію?", "en": "Do you provide quality documents?"}, "a": {"uk": "Так, документи, що підтверджують якість продукції, надаємо на запит. Уточніть у менеджера, які саме документи потрібні для вашого об’єкта чи тендеру.", "en": "Yes, documents confirming product quality are available on request. Let your manager know which documents your project or tender requires."}, "on": true}, {"c": "mfg", "q": {"uk": "Чи можна замовити лиття пластмас під тиском за моїм кресленням?", "en": "Can you injection-mold a plastic part from my drawing?"}, "a": {"uk": "Так. Надішліть креслення, 3D-модель або зразок — ми оцінимо технологічність, підберемо матеріал і підготуємо розрахунок вартості пресформи та лиття з термінами. Можемо почати з прототипу, щоб перевірити виріб до запуску серійного виробництва.", "en": "Yes. Send a drawing, 3D model or sample — we will check manufacturability, choose the material and quote the mold and molding with lead times. We can start with a prototype to test the part before series production."}, "on": true}, {"c": "mfg", "q": {"uk": "Скільки коштує виготовлення пресформи для лиття пластику?", "en": "How much does an injection mold cost?"}, "a": {"uk": "Вартість залежить від розмірів і складності виробу, кількості гнізд, наявності рухомих елементів і вимог до точності та ресурсу. Після аналізу креслення або зразка надаємо комерційну пропозицію з розбивкою вартості й термінами.", "en": "The cost depends on part size and complexity, number of cavities, moving elements and precision and tool-life requirements. After reviewing your drawing or sample we send a quote with a cost breakdown and lead times."}, "on": true}, {"c": "mfg", "q": {"uk": "Чи можете ви лити в моїй пресформі або передати пресформу мені?", "en": "Can you mold in my tool or hand the mold over to me?"}, "a": {"uk": "Так, обидва варіанти можливі. Пресформу, виготовлену під ваш виріб, можемо передати на ваше підприємство або зберігати в нас і відливати партії на нашому обладнанні, передаючи вам готову продукцію.", "en": "Both are possible. A mold made for your part can be handed over to your plant, or kept with us so we mold batches on our equipment and deliver finished parts."}, "on": true}, {"c": "mfg", "q": {"uk": "Які терміни виготовлення фіксаторів і виробів на замовлення?", "en": "What are the lead times for spacers and custom parts?"}, "a": {"uk": "Для виробів із каталогу терміни залежать від обсягу партії, ходові позиції відвантажуємо зі складу. Для нових виробів строк визначає складність пресформи та тираж. Точні дати фіксуємо в комерційній пропозиції.", "en": "For catalog items lead time depends on batch size, and fast-moving items ship from stock. For new parts it depends on mold complexity and run size. Exact dates are fixed in the quote."}, "on": true}, {"c": "del", "q": {"uk": "Як здійснюється доставка фіксаторів по Україні?", "en": "How do you deliver rebar spacers across Ukraine?"}, "a": {"uk": "Доставляємо по всій Україні та за кордон: Новою поштою, Укрпоштою, вантажними перевізниками або транспортом прямо на об’єкт. Великі обсяги можемо відвантажувати партіями під етапи робіт. Вартість і терміни доставки погоджуємо під час оформлення замовлення.", "en": "We deliver across Ukraine and abroad by Nova Post, Ukrposhta, freight carriers or straight to your site. Large orders can ship in batches by work stage. Delivery cost and timing are agreed when you order."}, "on": true}, {"c": "del", "q": {"uk": "Які умови оплати?", "en": "What are the payment terms?"}, "a": {"uk": "Працюємо за безготівковим розрахунком на рахунок для юридичних осіб і ФОП, надаємо повний пакет документів. Для постійних клієнтів можливі індивідуальні умови.", "en": "We work by bank transfer against an invoice for companies and sole traders, with full paperwork. Individual terms are available for regular clients."}, "on": true}, {"c": "del", "q": {"uk": "Чи можна забрати замовлення самовивозом?", "en": "Can I collect my order myself?"}, "a": {"uk": "Так, самовивіз можливий зі складів у Львові та Києві за попереднім погодженням часу з менеджером.", "en": "Yes, you can collect from our Lviv or Kyiv warehouse by prior arrangement with a manager."}, "on": true}]};
